package com.raredropping;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.ActionEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.AbstractAction;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.KeyStroke;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/** The intentionally quiet, glanceable main view for Exodus Bingo. */
final class BingoDashboardPanel extends JPanel
{
	static final Color UNSTARTED_RED = new Color(0x512C32);
	static final Color UNSTARTED_BORDER = new Color(0xD45C65);
	static final Color COMPLETED_GREEN = new Color(0x234B34);
	static final Color COMPLETED_BORDER = new Color(0x49C67B);
	static final Color PROGRESS_GOLD = new Color(0xE0AD52);
	static final Color SELECTED_GOLD = new Color(0xF2CA72);
	static final long TRANSITION_MILLIS = 1_800L;
	private static final int WRAPPED_LABEL_WIDTH = PluginPanel.PANEL_WIDTH - 30;
	private static final int BOARD_WIDTH = PluginPanel.PANEL_WIDTH - 20;
	private static final int BOARD_HEIGHT = 158;

	private final Map<String, Long> completionTransitions = new HashMap<>();
	private final Timer transitionTimer;
	private Runnable settingsHandler = () -> { };
	private BingoSidebarData.Catalog catalog;
	private BingoSidebarData.Board board;
	private List<BingoSidebarData.Achievement> achievements = Collections.emptyList();
	private String selectedCompetitionId;
	private String selectedTileId;
	private String status;
	private boolean connected;
	private boolean loading;

	BingoDashboardPanel()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setOpaque(true);
		setVisible(true);
		transitionTimer = new Timer(75, event -> updateTransitionColors());
		transitionTimer.setRepeats(true);
	}

	/** Compatibility seam while these actions live in the Settings view. */
	void setActions(Runnable refreshHandler, Consumer<String> competitionHandler,
		Consumer<String> joinHandler, Consumer<String> chatHandler)
	{
		// Main dashboard actions are deliberately limited to tile inspection and Settings.
	}

	void setSettingsHandler(Runnable settingsHandler)
	{
		this.settingsHandler = settingsHandler == null ? () -> { } : settingsHandler;
	}

	void setConnected(boolean connected, String character)
	{
		runOnEdt(() ->
		{
			this.connected = connected;
			if (!connected)
			{
				catalog = null;
				board = null;
				selectedCompetitionId = null;
				selectedTileId = null;
				achievements = Collections.emptyList();
				completionTransitions.clear();
				transitionTimer.stop();
				loading = false;
				status = null;
			}
			setVisible(true);
			rebuild();
		});
	}

	void showLoading(String detail)
	{
		runOnEdt(() ->
		{
			loading = true;
			status = first(detail, "Updating bingo…");
			rebuild();
		});
	}

	void showError(String detail)
	{
		runOnEdt(() ->
		{
			loading = false;
			status = first(detail, "Update failed. Open Settings to retry.");
			rebuild();
		});
	}

	void setCatalog(BingoSidebarData.Catalog nextCatalog, String preferredCompetitionId)
	{
		runOnEdt(() ->
		{
			String previousCompetitionId = selectedCompetitionId;
			catalog = nextCatalog;
			String preferred = containsCompetition(nextCatalog, preferredCompetitionId)
				? preferredCompetitionId
				: containsCompetition(nextCatalog, nextCatalog == null ? null : nextCatalog.defaultCompetitionId)
					? nextCatalog.defaultCompetitionId
					: nextCatalog != null && !nextCatalog.competitions.isEmpty()
						? nextCatalog.competitions.get(0).id : null;
			selectedCompetitionId = preferred;
			boolean competitionChanged = previousCompetitionId == null
				? preferred != null : !previousCompetitionId.equals(preferred);
			if (competitionChanged || preferred == null) clearCompetitionContent();
			loading = false;
			status = nextCatalog != null && nextCatalog.competitions.isEmpty()
				? "No active bingo. Join one in Settings." : null;
			rebuild();
		});
	}

	void setBoard(BingoSidebarData.Board nextBoard, boolean animateCompletions)
	{
		runOnEdt(() ->
		{
			if (animateCompletions && board != null && nextBoard != null)
			{
				Map<String, Boolean> previous = new HashMap<>();
				for (BingoSidebarData.Tile tile : board.tiles) previous.put(tile.id, tile.done);
				long now = System.currentTimeMillis();
				for (BingoSidebarData.Tile tile : nextBoard.tiles)
					if (tile.done && Boolean.FALSE.equals(previous.get(tile.id)))
						completionTransitions.put(tile.id, now);
			}
			board = nextBoard;
			selectedCompetitionId = nextBoard == null || nextBoard.competition == null
				? selectedCompetitionId : nextBoard.competition.id;
			if (selectedTileId != null && tile(selectedTileId) == null) selectedTileId = null;
			loading = false;
			status = null;
			if (!completionTransitions.isEmpty() && !transitionTimer.isRunning()) transitionTimer.start();
			rebuild();
		});
	}

	/** Chat remains available on the website; incoming chat is intentionally not rendered here. */
	void setChat(BingoSidebarData.ChatPage nextChat)
	{
		// Compatibility no-op for older plugin glue.
	}

	void setAchievements(List<BingoSidebarData.Achievement> nextAchievements)
	{
		List<BingoSidebarData.Achievement> snapshot = nextAchievements == null
			? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(nextAchievements));
		runOnEdt(() ->
		{
			achievements = snapshot;
			rebuild();
		});
	}

	String getSelectedCompetitionId()
	{
		return selectedCompetitionId;
	}

	void clearJoinInput()
	{
		// Join controls moved to Settings.
	}

	void clearChatInput()
	{
		// Chat controls were removed from the RuneLite panel.
	}

	private void rebuild()
	{
		assert SwingUtilities.isEventDispatchThread();
		removeAll();
		add(buildBoardCard());
		if (connected && board != null)
		{
			add(Box.createVerticalStrut(7));
			add(buildAchievementsCard());
		}
		revalidate();
		repaint();
	}

	private JPanel buildBoardCard()
	{
		JPanel section = section("bingo-board-card");
		JPanel titleRow = new JPanel(new BorderLayout(4, 0));
		titleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		titleRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 28));

		JLabel title = label("Exodus Bingo", Color.WHITE);
		title.setName("bingo-title");
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		titleRow.add(title, BorderLayout.CENTER);

		JButton settings = new JButton("⚙");
		settings.setName("bingo-open-settings");
		settings.setToolTipText("Bingo settings");
		settings.setPreferredSize(new Dimension(26, 24));
		settings.setMinimumSize(new Dimension(26, 24));
		settings.setMaximumSize(new Dimension(26, 24));
		settings.setMargin(new Insets(0, 0, 0, 0));
		settings.setFont(settings.getFont().deriveFont(Font.PLAIN, 14f));
		settings.setFocusPainted(true);
		settings.setBorderPainted(false);
		settings.setContentAreaFilled(false);
		settings.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		settings.getAccessibleContext().setAccessibleName("Open bingo settings");
		settings.getAccessibleContext().setAccessibleDescription(
			"Pair a character, refresh or join a bingo, and review drop history.");
		settings.addActionListener(event -> settingsHandler.run());
		titleRow.add(settings, BorderLayout.EAST);
		section.add(titleRow);

		if (!connected)
		{
			section.add(Box.createVerticalStrut(5));
			section.add(label("Connect in Settings", ColorScheme.LIGHT_GRAY_COLOR));
			return section;
		}

		if (board == null)
		{
			section.add(Box.createVerticalStrut(5));
			String emptyState = loading ? "Updating…"
				: status == null ? "Choose or join a bingo in Settings." : status;
			JLabel statusLabel = label(wrapped(html(emptyState)),
				loading ? ColorScheme.LIGHT_GRAY_COLOR : new Color(0xE6A15F));
			statusLabel.setName("bingo-status");
			section.add(statusLabel);
			return section;
		}

		section.add(Box.createVerticalStrut(4));
		section.add(buildBoardMeta());
		section.add(Box.createVerticalStrut(5));
		section.add(buildBoardGrid());

		if (status != null && !loading)
		{
			JLabel statusLabel = label(wrapped(html(shorten(status, 96))), new Color(0xE6A15F));
			statusLabel.setName("bingo-status");
			statusLabel.setToolTipText(wrapped(html(status)));
			statusLabel.getAccessibleContext().setAccessibleName("Bingo update failed: " + status);
			section.add(Box.createVerticalStrut(4));
			section.add(statusLabel);
		}

		BingoSidebarData.Tile selected = tile(selectedTileId);
		if (selected != null)
		{
			section.add(Box.createVerticalStrut(6));
			section.add(buildTileDetails(selected));
		}
		return section;
	}

	private JPanel buildBoardMeta()
	{
		JPanel meta = new JPanel(new BorderLayout(5, 0));
		meta.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		meta.setAlignmentX(Component.LEFT_ALIGNMENT);
		meta.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 20));
		String competitionName = board.competition == null ? "Current bingo" : board.competition.name;
		JLabel name = label("<html>" + html(shorten(competitionName, 28)) + "</html>",
			ColorScheme.LIGHT_GRAY_COLOR);
		name.setName("bingo-board-name");
		name.setToolTipText(wrapped(html(competitionName)));
		meta.add(name, BorderLayout.CENTER);
		String count = board.competition == null ? ""
			: board.competition.completedCount + "/" + board.competition.tileCount;
		String countText = loading ? "Updating… " + count : count;
		JLabel completed = label(countText, loading ? PROGRESS_GOLD : COMPLETED_BORDER);
		completed.setName("bingo-board-count");
		completed.setHorizontalAlignment(SwingConstants.RIGHT);
		completed.setToolTipText(loading ? wrapped(html(first(status, "Updating bingo…"))) : null);
		completed.getAccessibleContext().setAccessibleName(loading
			? "Updating bingo, " + count + " tiles complete"
			: count + " tiles complete");
		meta.add(completed, BorderLayout.EAST);
		return meta;
	}

	private JPanel buildBoardGrid()
	{
		JPanel grid = new JPanel(new GridLayout(5, 5, 3, 3));
		grid.setName("bingo-grid");
		grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		grid.setPreferredSize(new Dimension(BOARD_WIDTH, BOARD_HEIGHT));
		grid.setMinimumSize(new Dimension(BOARD_WIDTH, BOARD_HEIGHT));
		grid.setMaximumSize(new Dimension(BOARD_WIDTH, BOARD_HEIGHT));
		Map<Integer, BingoSidebarData.Tile> byPosition = new HashMap<>();
		for (BingoSidebarData.Tile tile : board.tiles)
			if (tile != null && tile.position >= 1 && tile.position <= 25)
				byPosition.putIfAbsent(tile.position, tile);
		for (int position = 1; position <= 25; position++)
		{
			BingoSidebarData.Tile tile = byPosition.get(position);
			if (tile != null)
			{
				grid.add(buildTileButton(tile));
			}
			else
			{
				JPanel placeholder = new JPanel();
				placeholder.setName("bingo-placeholder-" + position);
				placeholder.setBackground(new Color(0x252525));
				placeholder.setBorder(new LineBorder(ColorScheme.BORDER_COLOR, 1, true));
				placeholder.getAccessibleContext().setAccessibleName("Empty tile " + position);
				grid.add(placeholder);
			}
		}
		return grid;
	}

	private JButton buildTileButton(BingoSidebarData.Tile tile)
	{
		double percent = tileProgressPercent(tile);
		boolean selected = tile.id.equals(selectedTileId);
		ProgressTileButton button = new ProgressTileButton(tile.position, tile.done, percent, selected);
		button.setName("bingo-tile-" + tile.id);
		button.putClientProperty("tileId", tile.id);
		button.putClientProperty("progressPercent", percent);
		button.putClientProperty("selectedTile", selected);
		button.setPreferredSize(new Dimension(30, 28));
		button.setMinimumSize(new Dimension(24, 24));
		button.setForeground(Color.WHITE);
		long now = System.currentTimeMillis();
		button.setTileAppearance(tileColor(tile, now), tileBorderColor(tile, now));
		String progress = tile.done ? "Complete"
			: tile.progress == null || tile.progress.label == null
				? compactNumber(percent) + "%" : tile.progress.label;
		button.setToolTipText(wrapped(html("#" + tile.position + " " + tile.title + " · " + progress)));
		button.getAccessibleContext().setAccessibleName(
			"Tile " + tile.position + ", " + tile.title + ", " + progress);
		button.getAccessibleContext().setAccessibleDescription(
			(selected ? "Selected. " : "") + "Press Enter for requirements and contributions.");
		button.addActionListener(event ->
		{
			boolean opening = !tile.id.equals(selectedTileId);
			selectedTileId = opening ? tile.id : null;
			rebuild();
			if (opening)
			{
				SwingUtilities.invokeLater(() ->
				{
					Component selectedButton = findNamed(this, "bingo-tile-" + tile.id);
					if (selectedButton != null) selectedButton.requestFocusInWindow();
				});
			}
		});
		button.getInputMap(JComponent.WHEN_FOCUSED).put(KeyStroke.getKeyStroke("ESCAPE"), "close-details");
		button.getActionMap().put("close-details", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent event)
			{
				if (selectedTileId != null)
				{
					selectedTileId = null;
					rebuild();
				}
			}
		});
		return button;
	}

	private JPanel buildTileDetails(BingoSidebarData.Tile tile)
	{
		JPanel details = new JPanel();
		details.setName("bingo-tile-details");
		details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
		details.setAlignmentX(Component.LEFT_ALIGNMENT);
		details.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		details.setBorder(BorderFactory.createCompoundBorder(
			new LineBorder(ColorScheme.BORDER_COLOR, 1, true), new EmptyBorder(6, 7, 6, 7)));
		details.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, Integer.MAX_VALUE));

		JPanel detailHeader = new JPanel(new BorderLayout(5, 0));
		detailHeader.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		detailHeader.setAlignmentX(Component.LEFT_ALIGNMENT);
		detailHeader.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 24));
		JLabel detailTitle = label("<html><b>#" + tile.position + " "
			+ html(shorten(tile.title, 34)) + "</b></html>", Color.WHITE);
		detailTitle.setToolTipText(wrapped(html(tile.title)));
		detailHeader.add(detailTitle, BorderLayout.CENTER);
		String stateText = tile.done ? "COMPLETE" : compactNumber(tileProgressPercent(tile)) + "%";
		JLabel state = label(stateText, tile.done ? COMPLETED_BORDER : PROGRESS_GOLD);
		state.setFont(state.getFont().deriveFont(Font.BOLD, 10f));
		state.setHorizontalAlignment(SwingConstants.RIGHT);
		detailHeader.add(state, BorderLayout.EAST);
		details.add(detailHeader);
		if (tile.description != null && !tile.description.trim().isEmpty())
		{
			JLabel description = label(wrapped(html(shorten(tile.description, 180))),
				ColorScheme.LIGHT_GRAY_COLOR);
			description.setToolTipText(wrapped(html(tile.description)));
			details.add(Box.createVerticalStrut(3));
			details.add(description);
		}

		List<BingoSidebarData.Requirement> displayedRequirements = displayedRequirements(tile);
		if (!displayedRequirements.isEmpty())
		{
			details.add(Box.createVerticalStrut(5));
			String requirementHeading = displayedRequirements.size() == 1 ? "Requirement"
				: "any".equals(tile.conditionLogic) ? "Complete any" : "Complete all";
			details.add(sectionLabel(requirementHeading));
			for (BingoSidebarData.Requirement requirement : displayedRequirements)
			{
				details.add(Box.createVerticalStrut(3));
				details.add(label(wrapped("<b>" + html(requirement.label) + "</b>"), Color.WHITE));
				String amount = requirement.target == null
					? compactNumber(requirement.current)
					: compactNumber(requirement.current) + " / " + compactNumber(requirement.target);
				if (requirement.unit != null && !requirement.unit.trim().isEmpty())
					amount += " " + requirement.unit.trim();
				List<String> qualifiers = new ArrayList<>();
				String aggregation = requirementAggregation(requirement.aggregation);
				if (aggregation != null) qualifiers.add(aggregation);
				if (!requirement.required && !requirement.supportingOnly) qualifiers.add("Optional");
				String meta = amount + (qualifiers.isEmpty() ? "" : "  ·  " + String.join(" · ", qualifiers));
				details.add(label(wrapped(html(meta)), ColorScheme.LIGHT_GRAY_COLOR));
			}
		}
		else if (tile.progress != null)
		{
			details.add(Box.createVerticalStrut(5));
			details.add(sectionLabel("Progress"));
			details.add(label(wrapped(html(progressLabel(tile.progress))), PROGRESS_GOLD));
		}

		List<BingoSidebarData.MemberProgress> contributions = new ArrayList<>();
		for (BingoSidebarData.MemberProgress progress : tile.memberProgress)
			if (progress.current > 0d) contributions.add(progress);
		if (!tile.memberProgress.isEmpty())
		{
			details.add(Box.createVerticalStrut(6));
			details.add(sectionLabel("Contributions"));
			if (contributions.isEmpty())
			{
				details.add(label("No contributions yet.", ColorScheme.LIGHT_GRAY_COLOR));
			}
			else
			{
				boolean showCondition = displayedRequirements.size() > 1;
				for (BingoSidebarData.MemberProgress progress : contributions)
				{
					String identity = contributionIdentity(progress);
					if (showCondition && progress.conditionLabel != null)
						identity += " · " + progress.conditionLabel;
					String amount = compactNumber(progress.current)
						+ (progress.unit == null ? "" : " " + progress.unit);
					details.add(compactRow(identity, amount));
				}
			}
		}

		if (tile.done)
		{
			String completedBy = tile.completedByTeam ? "Team"
				: first(tile.completedByCharacterName, tile.completedByName, "Team");
			details.add(Box.createVerticalStrut(6));
			details.add(label(wrapped("<b>Completed by " + html(completedBy) + "</b>"), COMPLETED_BORDER));
		}
		if (tile.proofCount > 0)
		{
			details.add(Box.createVerticalStrut(3));
			details.add(label(tile.proofCount + " evidence "
				+ (tile.proofCount == 1 ? "submission" : "submissions"),
				ColorScheme.LIGHT_GRAY_COLOR));
		}
		if (tile.requirements.isEmpty() && tile.progress == null && tile.memberProgress.isEmpty())
		{
			details.add(Box.createVerticalStrut(4));
			details.add(label("No tracked requirements.", ColorScheme.LIGHT_GRAY_COLOR));
		}
		return details;
	}

	private JPanel buildAchievementsCard()
	{
		JPanel section = section("bingo-achievements");
		section.setBorder(BorderFactory.createCompoundBorder(
			new MatteBorder(1, 0, 0, 0, ColorScheme.BORDER_COLOR), new EmptyBorder(7, 6, 4, 6)));
		JLabel heading = label("Recent achievements", Color.WHITE);
		heading.setFont(heading.getFont().deriveFont(Font.BOLD, 13f));
		section.add(heading);
		if (achievements.isEmpty())
		{
			section.add(Box.createVerticalStrut(3));
			section.add(label("Nothing new yet.", ColorScheme.LIGHT_GRAY_COLOR));
			return section;
		}
		for (int index = 0; index < Math.min(5, achievements.size()); index++)
		{
			BingoSidebarData.Achievement achievement = achievements.get(index);
			section.add(Box.createVerticalStrut(index == 0 ? 5 : 6));
			section.add(buildAchievementRow(achievement));
		}
		return section;
	}

	private JPanel buildAchievementRow(BingoSidebarData.Achievement achievement)
	{
		JPanel row = new JPanel();
		row.setName("bingo-achievement-" + achievement.id);
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 40));

		JLabel title = label("<html>" + html(shorten(achievement.title, 38)) + "</html>", Color.WHITE);
		title.setToolTipText(wrapped(html(achievement.title)));
		title.setFont(title.getFont().deriveFont(Font.BOLD));
		row.add(title);
		String who = first(achievement.characterName, achievement.participantName, "Team");
		String increment = achievementIncrement(achievement);
		JLabel summary = label("<html>" + html(shorten(who, 24)) + "  "
			+ html(increment) + "</html>",
			ColorScheme.LIGHT_GRAY_COLOR);
		summary.setName("bingo-achievement-summary");
		summary.setToolTipText(wrapped(html(who + " " + increment)));
		row.getAccessibleContext().setAccessibleName(
			achievement.title + ", " + who + " " + increment);
		row.add(summary);
		return row;
	}

	private static JPanel compactRow(String key, String value)
	{
		JPanel row = new JPanel(new BorderLayout(5, 0));
		row.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 21));
		JLabel keyLabel = label("<html>" + html(shorten(key, 31)) + "</html>",
			ColorScheme.LIGHT_GRAY_COLOR);
		keyLabel.setToolTipText(wrapped(html(key)));
		row.add(keyLabel, BorderLayout.CENTER);
		JLabel valueLabel = label("<html>" + html(value) + "</html>", Color.WHITE);
		valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(valueLabel, BorderLayout.EAST);
		return row;
	}

	private static JLabel sectionLabel(String value)
	{
		JLabel label = label(value.toUpperCase(Locale.ROOT), PROGRESS_GOLD);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 10f));
		return label;
	}

	private Color tileColor(BingoSidebarData.Tile tile, long now)
	{
		if (!tile.done) return UNSTARTED_RED;
		Long started = completionTransitions.get(tile.id);
		return started == null ? COMPLETED_GREEN : transitionColor(now - started);
	}

	private Color tileBorderColor(BingoSidebarData.Tile tile, long now)
	{
		if (!tile.done) return UNSTARTED_BORDER;
		Long started = completionTransitions.get(tile.id);
		return started == null ? COMPLETED_BORDER : transitionBorderColor(now - started);
	}

	private void updateTransitionColors()
	{
		if (!SwingUtilities.isEventDispatchThread()) return;
		long now = System.currentTimeMillis();
		List<String> finished = new ArrayList<>();
		for (Map.Entry<String, Long> transition : completionTransitions.entrySet())
		{
			Component component = findNamed(this, "bingo-tile-" + transition.getKey());
			if (component instanceof ProgressTileButton)
			{
				((ProgressTileButton) component).setTileAppearance(
					transitionColor(now - transition.getValue()),
					transitionBorderColor(now - transition.getValue()));
			}
			if (now - transition.getValue() >= TRANSITION_MILLIS) finished.add(transition.getKey());
		}
		for (String tileId : finished) completionTransitions.remove(tileId);
		if (completionTransitions.isEmpty()) transitionTimer.stop();
		repaint();
	}

	static Color transitionColor(long elapsedMillis)
	{
		return interpolate(UNSTARTED_RED, COMPLETED_GREEN, elapsedMillis);
	}

	static Color transitionBorderColor(long elapsedMillis)
	{
		return interpolate(UNSTARTED_BORDER, COMPLETED_BORDER, elapsedMillis);
	}

	private static Color interpolate(Color start, Color end, long elapsedMillis)
	{
		double ratio = Math.max(0d, Math.min(1d, (double) elapsedMillis / TRANSITION_MILLIS));
		double eased = ratio * ratio * (3d - (2d * ratio));
		return new Color(
			mix(start.getRed(), end.getRed(), eased),
			mix(start.getGreen(), end.getGreen(), eased),
			mix(start.getBlue(), end.getBlue(), eased));
	}

	private static int mix(int start, int end, double ratio)
	{
		return (int) Math.round(start + ((end - start) * ratio));
	}

	static double tileProgressPercent(BingoSidebarData.Tile tile)
	{
		if (tile == null) return 0d;
		if (tile.done) return 100d;
		if (tile.progress != null) return clampPercent(tile.progress.percent);
		List<Double> required = new ArrayList<>();
		for (BingoSidebarData.Requirement requirement : tile.requirements)
			if (requirement.required && !requirement.supportingOnly)
				required.add(clampPercent(requirement.percent));
		if (required.isEmpty()) return 0d;
		if ("any".equals(tile.conditionLogic)) return Collections.max(required);
		double total = 0d;
		for (double percent : required) total += percent;
		return total / required.size();
	}

	private static double clampPercent(double value)
	{
		if (!Double.isFinite(value)) return value == Double.POSITIVE_INFINITY ? 100d : 0d;
		return Math.max(0d, Math.min(100d, value));
	}

	static String achievementIncrement(BingoSidebarData.Achievement achievement)
	{
		if (achievement.value != null)
		{
			String unit = compactUnit(achievement.unit);
			return "+" + compactNumber(achievement.value) + (unit.isEmpty() ? "" : " " + unit);
		}
		if ("tile_completed".equals(achievement.type)) return "+1 completion";
		if ("required_drop".equals(achievement.type)) return "+1 drop";
		return "+1";
	}

	private static String compactUnit(String unit)
	{
		if (unit == null) return "";
		String normalized = unit.trim();
		if ("experience".equalsIgnoreCase(normalized)) return "XP";
		if ("killcount".equalsIgnoreCase(normalized)) return "KC";
		return normalized;
	}

	private BingoSidebarData.Tile tile(String tileId)
	{
		if (board == null || tileId == null) return null;
		for (BingoSidebarData.Tile tile : board.tiles) if (tileId.equals(tile.id)) return tile;
		return null;
	}

	private void clearCompetitionContent()
	{
		board = null;
		selectedTileId = null;
		achievements = Collections.emptyList();
		completionTransitions.clear();
		transitionTimer.stop();
	}

	private static boolean containsCompetition(BingoSidebarData.Catalog catalog, String id)
	{
		if (catalog == null || id == null) return false;
		for (BingoSidebarData.CompetitionSummary competition : catalog.competitions)
			if (id.equals(competition.id)) return true;
		return false;
	}

	private static JPanel section(String name)
	{
		JPanel section = new JPanel();
		section.setName(name);
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		section.setBorder(new EmptyBorder(6, 6, 6, 6));
		section.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, Integer.MAX_VALUE));
		return section;
	}

	private static JLabel label(String text, Color color)
	{
		JLabel label = new JLabel(text == null ? "" : text);
		label.setForeground(color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setVerticalAlignment(SwingConstants.TOP);
		label.setMaximumSize(new Dimension(WRAPPED_LABEL_WIDTH, Integer.MAX_VALUE));
		return label;
	}

	private static String requirementAggregation(String aggregation)
	{
		if ("team_sum".equals(aggregation)) return "Team total";
		if ("each_participant".equals(aggregation)) return "Each player";
		if ("any_participant".equals(aggregation)) return "Any player";
		return null;
	}

	private static String contributionIdentity(BingoSidebarData.MemberProgress progress)
	{
		String character = first(progress.characterName);
		String member = first(progress.memberName);
		if (character == null) return member == null ? "Team" : member;
		if (member == null || character.equalsIgnoreCase(member)) return character;
		return character + " (" + member + ")";
	}

	private static List<BingoSidebarData.Requirement> displayedRequirements(BingoSidebarData.Tile tile)
	{
		List<BingoSidebarData.Requirement> tracked = new ArrayList<>();
		for (BingoSidebarData.Requirement requirement : tile.requirements)
			if (!requirement.supportingOnly) tracked.add(requirement);
		return tracked.isEmpty() ? tile.requirements : tracked;
	}

	private static Component findNamed(Container root, String name)
	{
		for (Component component : root.getComponents())
		{
			if (name.equals(component.getName())) return component;
			if (component instanceof Container)
			{
				Component found = findNamed((Container) component, name);
				if (found != null) return found;
			}
		}
		return null;
	}

	private static String progressLabel(BingoSidebarData.Progress progress)
	{
		if (progress.label != null && !progress.label.trim().isEmpty()) return progress.label;
		return compactNumber(progress.current) + " / " + compactNumber(progress.target)
			+ (progress.unit == null ? "" : " " + progress.unit);
	}

	private static String compactNumber(double value)
	{
		double absolute = Math.abs(value);
		if (absolute >= 1_000_000d) return compactDecimal(value / 1_000_000d) + "M";
		if (absolute >= 1_000d) return compactDecimal(value / 1_000d) + "K";
		return compactDecimal(value);
	}

	private static String compactDecimal(double value)
	{
		if (Math.rint(value) == value) return Long.toString((long) value);
		return String.format(Locale.ROOT, "%.1f", value);
	}

	private static String first(String... values)
	{
		for (String value : values) if (value != null && !value.trim().isEmpty()) return value.trim();
		return null;
	}

	private static String shorten(String value, int maximumLength)
	{
		if (value == null) return "";
		String normalized = value.trim();
		return normalized.length() <= maximumLength
			? normalized : normalized.substring(0, Math.max(1, maximumLength - 1)) + "…";
	}

	private static String wrapped(String markup)
	{
		return "<html><div style='width:" + WRAPPED_LABEL_WIDTH + "px'>"
			+ (markup == null ? "" : markup) + "</div></html>";
	}

	private static String html(String value)
	{
		if (value == null) return "";
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
			.replace("\"", "&quot;").replace("'", "&#39;");
	}

	private static void runOnEdt(Runnable task)
	{
		if (SwingUtilities.isEventDispatchThread()) task.run();
		else SwingUtilities.invokeLater(task);
	}

	/** Square tile with a circular at-a-glance progress ring. */
	private static final class ProgressTileButton extends JButton
	{
		private final int position;
		private final boolean done;
		private final double percent;
		private final boolean selectedTile;

		private ProgressTileButton(int position, boolean done, double percent, boolean selectedTile)
		{
			this.position = position;
			this.done = done;
			this.percent = clampPercent(percent);
			this.selectedTile = selectedTile;
			setText(done ? "Completed" : compactNumber(percent) + "%");
			setMargin(new Insets(0, 0, 0, 0));
			setFont(getFont().deriveFont(Font.BOLD, 9f));
			setFocusPainted(false);
			setContentAreaFilled(false);
			setOpaque(false);
		}

		private void setTileAppearance(Color fill, Color border)
		{
			setBackground(fill);
			setBorder(new LineBorder(border, 2, true));
			repaint();
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D draw = (Graphics2D) graphics.create();
			try
			{
				draw.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				draw.setColor(getBackground());
				draw.fillRoundRect(1, 1, Math.max(0, getWidth() - 2), Math.max(0, getHeight() - 2), 7, 7);

				int ring = Math.max(15, Math.min(getWidth(), getHeight()) - 10);
				int x = (getWidth() - ring) / 2;
				int y = (getHeight() - ring) / 2;
				if (done)
				{
					draw.setColor(Color.WHITE);
					draw.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					draw.drawLine(x + ring / 5, y + ring / 2, x + (ring * 2) / 5, y + (ring * 3) / 4);
					draw.drawLine(x + (ring * 2) / 5, y + (ring * 3) / 4, x + (ring * 4) / 5, y + ring / 4);
				}
				else
				{
					draw.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					draw.setColor(new Color(255, 255, 255, 52));
					draw.drawOval(x, y, ring, ring);
					if (percent > 0d)
					{
						draw.setColor(PROGRESS_GOLD);
						draw.drawArc(x, y, ring, ring, 90, -(int) Math.round(percent * 3.6d));
					}

					String number = Integer.toString(position);
					draw.setFont(getFont());
					draw.setColor(Color.WHITE);
					int textX = (getWidth() - draw.getFontMetrics().stringWidth(number)) / 2;
					int textY = (getHeight() - draw.getFontMetrics().getHeight()) / 2
						+ draw.getFontMetrics().getAscent();
					draw.drawString(number, textX, textY);
				}

				if (selectedTile || isFocusOwner())
				{
					draw.setColor(selectedTile ? SELECTED_GOLD : Color.WHITE);
					draw.setStroke(new BasicStroke(selectedTile ? 2f : 1.2f));
					draw.drawRoundRect(3, 3, Math.max(0, getWidth() - 7),
						Math.max(0, getHeight() - 7), 6, 6);
				}
			}
			finally
			{
				draw.dispose();
			}
		}
	}
}

package com.raredropping;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/** Device-authenticated transport for the compact board/chat RuneLite sidebar. */
final class BingoSidebarClient implements AutoCloseable
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int MAX_ATTEMPTS = 3;
	private static final String ROOT_PATH = "api/v2/integrations/runelite/competitions";

	private final OkHttpClient http;
	private final ScheduledExecutorService scheduler;
	private final HttpUrl baseUrl;
	private final Set<Call> calls = Collections.synchronizedSet(new HashSet<>());
	private final Set<ScheduledFuture<?>> retries = Collections.synchronizedSet(new HashSet<>());
	private volatile boolean closed;

	BingoSidebarClient(OkHttpClient http, ScheduledExecutorService scheduler)
	{
		this(http, scheduler, RareDropPingConfig.PRODUCTION_BASE_URL);
	}

	/** Package-private fixed-origin override for loopback integration tests only. */
	BingoSidebarClient(OkHttpClient http, ScheduledExecutorService scheduler, String baseUrl)
	{
		if (http == null || scheduler == null || !RareDropWebhookClient.isAllowedBaseUrl(baseUrl))
			throw new IllegalArgumentException("Invalid sidebar client configuration");
		this.http = http.newBuilder().followRedirects(false).followSslRedirects(false).build();
		this.scheduler = scheduler;
		this.baseUrl = HttpUrl.parse(baseUrl);
	}

	void competitions(String deviceToken, Listener<BingoSidebarData.Catalog> listener)
	{
		execute(get(path()), deviceToken, BingoSidebarClient::parseCatalog, listener, 1);
	}

	void join(String deviceToken, String joinCode, Listener<BingoSidebarData.JoinResult> listener)
	{
		JsonObject body = new JsonObject();
		body.addProperty("joinCode", joinCode == null ? "" : joinCode.trim());
		execute(post(path("join"), body), deviceToken, BingoSidebarClient::parseJoin, listener, 1);
	}

	void board(String deviceToken, String competitionId, Listener<BingoSidebarData.Board> listener)
	{
		execute(get(path(competitionId, "board")), deviceToken, BingoSidebarClient::parseBoard, listener, 1);
	}

	void chat(String deviceToken, String competitionId, String after,
		Listener<BingoSidebarData.ChatPage> listener)
	{
		HttpUrl.Builder url = path(competitionId, "chat").newBuilder().addQueryParameter("limit", "50");
		if (after != null && !after.trim().isEmpty()) url.addQueryParameter("after", after.trim());
		execute(get(url.build()), deviceToken, BingoSidebarClient::parseChatPage, listener, 1);
	}

	void sendChat(String deviceToken, String competitionId, String body, String clientMessageId,
		Listener<BingoSidebarData.ChatMessage> listener)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("body", body == null ? "" : body.trim());
		if (clientMessageId != null && !clientMessageId.trim().isEmpty())
			payload.addProperty("clientMessageId", clientMessageId.trim());
		execute(post(path(competitionId, "chat"), payload), deviceToken,
			(statusCode, json) -> parseChatMessage(object(json, "message")), listener, 1);
	}

	void achievements(String deviceToken, String competitionId,
		Listener<List<BingoSidebarData.Achievement>> listener)
	{
		HttpUrl url = path(competitionId, "achievements").newBuilder()
			.addQueryParameter("limit", "20").build();
		execute(get(url), deviceToken, BingoSidebarClient::parseAchievements, listener, 1);
	}

	void revoke(String deviceToken, Listener<Boolean> listener)
	{
		HttpUrl url = baseUrl.newBuilder().encodedPath("/api/v2/integrations/runelite/device")
			.query(null).fragment(null).build();
		Request request = new Request.Builder().url(url).header("Accept", "application/json").delete().build();
		execute(request, deviceToken, (statusCode, json) -> Boolean.TRUE, listener, 1);
	}

	private Request get(HttpUrl url)
	{
		return new Request.Builder().url(url).header("Accept", "application/json").get().build();
	}

	private Request post(HttpUrl url, JsonObject body)
	{
		return new Request.Builder().url(url).header("Accept", "application/json")
			.post(RequestBody.create(JSON, body.toString())).build();
	}

	private HttpUrl path(String... segments)
	{
		HttpUrl.Builder builder = baseUrl.newBuilder().encodedPath("/").query(null).fragment(null);
		for (String segment : ROOT_PATH.split("/")) builder.addPathSegment(segment);
		for (String segment : segments)
		{
			if (segment == null || segment.trim().isEmpty())
				throw new IllegalArgumentException("A sidebar route segment is required");
			builder.addPathSegment(segment.trim());
		}
		return builder.build();
	}

	private <T> void execute(Request bareRequest, String token, Parser<T> parser,
		Listener<T> listener, int attempt)
	{
		if (closed)
		{
			deliver(listener, Result.failed(0, "Sidebar client is closed."));
			return;
		}
		Request request = bareRequest.newBuilder()
			.header("Authorization", "Bearer " + (token == null ? "" : token.trim()))
			.build();
		Call call = http.newCall(request);
		calls.add(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call failedCall, IOException exception)
			{
				calls.remove(failedCall);
				if (closed || failedCall.isCanceled()) return;
				if (attempt < MAX_ATTEMPTS && schedule(() -> execute(bareRequest, token, parser, listener, attempt + 1), attempt))
					return;
				deliver(listener, Result.failed(0, "The Exodus Bingo service is unavailable."));
			}

			@Override
			public void onResponse(Call completedCall, Response response)
			{
				calls.remove(completedCall);
				try (Response ignored = response)
				{
					int statusCode = response.code();
					if (retryable(statusCode) && attempt < MAX_ATTEMPTS
						&& schedule(() -> execute(bareRequest, token, parser, listener, attempt + 1), attempt))
						return;
					JsonObject json = readJson(response);
					if (statusCode < 200 || statusCode >= 300)
					{
						deliver(listener, Result.failed(statusCode, text(json, "error", "message")));
						return;
					}
					try
					{
						deliver(listener, Result.accepted(statusCode, parser.parse(statusCode, json)));
					}
					catch (RuntimeException exception)
					{
						deliver(listener, Result.failed(statusCode, "The sidebar response was invalid."));
					}
				}
				catch (IOException | RuntimeException exception)
				{
					deliver(listener, Result.failed(response.code(), "The sidebar response could not be read."));
				}
			}
		});
	}

	private boolean schedule(Runnable operation, int attempt)
	{
		if (closed) return false;
		try
		{
			final ScheduledFuture<?>[] holder = new ScheduledFuture<?>[1];
			holder[0] = scheduler.schedule(() ->
			{
				retries.remove(holder[0]);
				operation.run();
			}, 1L << Math.max(0, attempt - 1), TimeUnit.SECONDS);
			retries.add(holder[0]);
			return true;
		}
		catch (RejectedExecutionException exception)
		{
			return false;
		}
	}

	private static boolean retryable(int statusCode)
	{
		return statusCode == 408 || statusCode == 429 || statusCode >= 500;
	}

	private static JsonObject readJson(Response response) throws IOException
	{
		String body = BoundedHttpBody.readUtf8(response.body());
		if (body.trim().isEmpty()) return new JsonObject();
		JsonElement parsed = new JsonParser().parse(body);
		if (!parsed.isJsonObject()) throw new IOException("JSON object expected");
		return parsed.getAsJsonObject();
	}

	private static BingoSidebarData.Catalog parseCatalog(int statusCode, JsonObject json)
	{
		JsonObject character = object(json, "character", "viewerCharacter");
		List<BingoSidebarData.CompetitionSummary> competitions = new ArrayList<>();
		for (JsonElement value : array(json, "competitions"))
			if (value.isJsonObject()) competitions.add(parseCompetition(value.getAsJsonObject()));
		return new BingoSidebarData.Catalog(text(character, "name", "username"),
			text(character, "displayName", "name"), competitions,
			text(json, "defaultCompetitionId"));
	}

	private static BingoSidebarData.JoinResult parseJoin(int statusCode, JsonObject json)
	{
		boolean alreadyJoined = bool(json, false, "alreadyJoined", "duplicate");
		return new BingoSidebarData.JoinResult(requiredText(json, "competitionId"), true, alreadyJoined);
	}

	private static BingoSidebarData.Board parseBoard(int statusCode, JsonObject json)
	{
		BingoSidebarData.CompetitionSummary competition = parseCompetition(object(json, "competition"));
		JsonObject character = object(json, "character", "viewerCharacter");
		List<BingoSidebarData.Member> members = new ArrayList<>();
		for (JsonElement value : array(json, "members"))
		{
			if (!value.isJsonObject()) continue;
			JsonObject member = value.getAsJsonObject();
			members.add(new BingoSidebarData.Member(requiredText(member, "id"), requiredText(member, "name")));
		}
		List<BingoSidebarData.Tile> tiles = new ArrayList<>();
		for (JsonElement value : array(json, "tiles"))
			if (value.isJsonObject()) tiles.add(parseTile(value.getAsJsonObject()));
		return new BingoSidebarData.Board(competition, text(character, "claimId", "characterClaimId"),
			text(character, "name", "displayName"), members, tiles);
	}

	private static BingoSidebarData.CompetitionSummary parseCompetition(JsonObject json)
	{
		JsonObject progress = nullableObject(json, "progress");
		return new BingoSidebarData.CompetitionSummary(requiredText(json, "id"),
			requiredText(json, "name"), text(json, "teamName"), text(json, "startAt"),
			text(json, "endAt"), integer(json, integer(progress, 0, "completedTiles"), "completedCount"),
			integer(json, integer(progress, 25, "totalTiles"), "tileCount"), text(json, "characterClaimId"));
	}

	private static BingoSidebarData.Tile parseTile(JsonObject json)
	{
		List<BingoSidebarData.Requirement> requirements = new ArrayList<>();
		List<BingoSidebarData.MemberProgress> memberProgress = new ArrayList<>();
		for (JsonElement value : array(json, "requirements", "conditions"))
		{
			if (!value.isJsonObject()) continue;
			JsonObject requirement = value.getAsJsonObject();
			String requirementLabel = requiredText(requirement, "label");
			requirements.add(new BingoSidebarData.Requirement(
				requirementLabel, text(requirement, "kind"), numberOrNull(requirement, "target"),
				text(requirement, "unit"), text(requirement, "aggregation"),
				bool(requirement, true, "required"), bool(requirement, false, "supportingOnly"),
				number(requirement, 0d, "current"), number(requirement, 0d, "percent")));
			appendMemberProgress(memberProgress, array(requirement, "memberProgress"), requirementLabel);
		}
		appendMemberProgress(memberProgress, array(json, "memberProgress", "participants"), null);
		JsonObject progress = nullableObject(json, "progress");
		return new BingoSidebarData.Tile(requiredText(json, "id"), integer(json, 0, "position"),
			requiredText(json, "title"), text(json, "shortTitle"), text(json, "description"),
			text(json, "imageUrl"), text(json, "conditionLogic"), bool(json, false, "done"), text(json, "completedAt"),
			text(json, "completedByName"), text(json, "completedByCharacterName"),
			bool(json, false, "completedByTeam"), integer(json, 0, "proofCount"),
			progress == null ? null : new BingoSidebarData.Progress(text(progress, "source"),
				number(progress, 0d, "current"), number(progress, 0d, "target"), text(progress, "unit"),
				number(progress, 0d, "percent"), text(progress, "label")), requirements, memberProgress);
	}

	private static void appendMemberProgress(List<BingoSidebarData.MemberProgress> destination,
		JsonArray values, String conditionLabel)
	{
		for (JsonElement value : values)
		{
			if (!value.isJsonObject()) continue;
			JsonObject progress = value.getAsJsonObject();
			destination.add(new BingoSidebarData.MemberProgress(conditionLabel,
				text(progress, "memberId", "participantId"),
				requiredText(progress, "memberName", "participantName"), text(progress, "characterName"),
				number(progress, 0d, "current", "value", "count"), text(progress, "unit"),
				text(progress, "source")));
		}
	}

	private static BingoSidebarData.ChatPage parseChatPage(int statusCode, JsonObject json)
	{
		List<BingoSidebarData.ChatMessage> messages = new ArrayList<>();
		for (JsonElement value : array(json, "messages"))
			if (value.isJsonObject()) messages.add(parseChatMessage(value.getAsJsonObject()));
		return new BingoSidebarData.ChatPage(messages, text(json, "cursor"), bool(json, false, "readOnly"));
	}

	private static BingoSidebarData.ChatMessage parseChatMessage(JsonObject json)
	{
		JsonObject author = nullableObject(json, "author");
		JsonObject character = nullableObject(json, "character");
		JsonObject tile = nullableObject(json, "tile");
		return new BingoSidebarData.ChatMessage(requiredText(json, "id"), text(json, "kind"),
			requiredText(json, "body"), text(json, "createdAt"),
			author == null ? text(json, "authorName") : text(author, "name"),
			character == null ? text(json, "characterName") : text(character, "name"),
			tile == null ? integerOrNull(json, "tilePosition") : integerOrNull(tile, "position"),
			tile == null ? text(json, "tileTitle") : text(tile, "title"));
	}

	private static List<BingoSidebarData.Achievement> parseAchievements(int statusCode, JsonObject json)
	{
		List<BingoSidebarData.Achievement> achievements = new ArrayList<>();
		for (JsonElement value : array(json, "achievements"))
		{
			if (!value.isJsonObject()) continue;
			JsonObject achievement = value.getAsJsonObject();
			achievements.add(new BingoSidebarData.Achievement(requiredText(achievement, "id"),
				text(achievement, "type"), text(achievement, "occurredAt"),
				requiredText(achievement, "title"), text(achievement, "detail"),
				text(achievement, "participantName"), text(achievement, "characterName"),
				integerOrNull(achievement, "tilePosition"), text(achievement, "tileTitle"),
				numberOrNull(achievement, "value"), text(achievement, "unit")));
		}
		return achievements;
	}

	private static JsonArray array(JsonObject json, String... names)
	{
		for (String name : names)
		{
			JsonElement value = json == null ? null : json.get(name);
			if (value != null && value.isJsonArray()) return value.getAsJsonArray();
		}
		return new JsonArray();
	}

	private static JsonObject object(JsonObject json, String... names)
	{
		JsonObject value = nullableObject(json, names);
		if (value == null) throw new IllegalArgumentException("Missing JSON object");
		return value;
	}

	private static JsonObject nullableObject(JsonObject json, String... names)
	{
		for (String name : names)
		{
			JsonElement value = json == null ? null : json.get(name);
			if (value != null && value.isJsonObject()) return value.getAsJsonObject();
		}
		return null;
	}

	private static String requiredText(JsonObject json, String... names)
	{
		String value = text(json, names);
		if (value == null || value.trim().isEmpty()) throw new IllegalArgumentException("Missing JSON text");
		return value;
	}

	private static String text(JsonObject json, String... names)
	{
		for (String name : names)
		{
			JsonElement value = json == null ? null : json.get(name);
			try
			{
				if (value != null && !value.isJsonNull() && value.isJsonPrimitive()) return value.getAsString();
			}
			catch (RuntimeException ignored) { }
		}
		return null;
	}

	private static boolean bool(JsonObject json, boolean fallback, String... names)
	{
		for (String name : names)
		{
			try { if (json != null && json.has(name)) return json.get(name).getAsBoolean(); }
			catch (RuntimeException ignored) { }
		}
		return fallback;
	}

	private static int integer(JsonObject json, int fallback, String... names)
	{
		Integer value = integerOrNull(json, names);
		return value == null ? fallback : value;
	}

	private static Integer integerOrNull(JsonObject json, String... names)
	{
		for (String name : names)
		{
			try { if (json != null && json.has(name) && !json.get(name).isJsonNull()) return json.get(name).getAsInt(); }
			catch (RuntimeException ignored) { }
		}
		return null;
	}

	private static double number(JsonObject json, double fallback, String... names)
	{
		Double value = numberOrNull(json, names);
		return value == null ? fallback : value;
	}

	private static Double numberOrNull(JsonObject json, String... names)
	{
		for (String name : names)
		{
			try { if (json != null && json.has(name) && !json.get(name).isJsonNull()) return json.get(name).getAsDouble(); }
			catch (RuntimeException ignored) { }
		}
		return null;
	}

	private static <T> void deliver(Listener<T> listener, Result<T> result)
	{
		if (listener == null) return;
		try { listener.onResult(result); }
		catch (RuntimeException ignored) { }
	}

	@Override
	public void close()
	{
		closed = true;
		List<Call> activeCalls;
		synchronized (calls) { activeCalls = new ArrayList<>(calls); calls.clear(); }
		for (Call call : activeCalls) call.cancel();
		List<ScheduledFuture<?>> activeRetries;
		synchronized (retries) { activeRetries = new ArrayList<>(retries); retries.clear(); }
		for (ScheduledFuture<?> retry : activeRetries) retry.cancel(false);
	}

	interface Listener<T>
	{
		void onResult(Result<T> result);
	}

	private interface Parser<T>
	{
		T parse(int statusCode, JsonObject json);
	}

	static final class Result<T>
	{
		private final int statusCode;
		private final T value;
		private final String error;

		private Result(int statusCode, T value, String error)
		{
			this.statusCode = statusCode;
			this.value = value;
			this.error = error;
		}

		static <T> Result<T> accepted(int statusCode, T value)
		{
			return new Result<>(statusCode, value, null);
		}

		static <T> Result<T> failed(int statusCode, String error)
		{
			return new Result<>(statusCode, null,
				error == null || error.trim().isEmpty() ? "Request failed." : error);
		}

		boolean isAccepted() { return statusCode >= 200 && statusCode < 300 && value != null; }
		int getStatusCode() { return statusCode; }
		T getValue() { return value; }
		String getError() { return error; }
	}
}

