package com.raredropping;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import okhttp3.ResponseBody;

/** Reads small API responses without allowing an untrusted server to exhaust client memory. */
final class BoundedHttpBody
{
	static final int MAX_JSON_RESPONSE_BYTES = 1024 * 1024;

	private BoundedHttpBody()
	{
	}

	static String readUtf8(ResponseBody body) throws IOException
	{
		if (body == null) return "";
		long declaredLength = body.contentLength();
		if (declaredLength > MAX_JSON_RESPONSE_BYTES)
		{
			throw new IOException("The API response was too large");
		}

		int initialCapacity = declaredLength > 0
			? (int) Math.min(declaredLength, MAX_JSON_RESPONSE_BYTES)
			: 4096;
		ByteArrayOutputStream output = new ByteArrayOutputStream(initialCapacity);
		InputStream input = body.byteStream();
		byte[] buffer = new byte[8192];
		int total = 0;
		int count;
		while ((count = input.read(buffer)) != -1)
		{
			if (count == 0) continue;
			if (total > MAX_JSON_RESPONSE_BYTES - count)
			{
				throw new IOException("The API response was too large");
			}
			output.write(buffer, 0, count);
			total += count;
		}
		return new String(output.toByteArray(), StandardCharsets.UTF_8);
	}
}

package com.raredropping;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.StringJoiner;
import java.util.TreeSet;

/** Immutable, locally configured rules for deciding which reports reach Discord. */
final class DiscordDropFilter
{
	static final long DEFAULT_MINIMUM_STACK_VALUE = 1_000_000L;
	static final long MAXIMUM_STACK_VALUE = 9_007_199_254_740_991L;
	private static final String SERIALIZED_VERSION = "v1";

	private final boolean minimumValueEnabled;
	private final long minimumStackValue;
	private final boolean uniqueItemsEnabled;
	private final Set<Integer> uniqueItemIds;
	private final boolean petsEnabled;

	private DiscordDropFilter(
		boolean minimumValueEnabled,
		long minimumStackValue,
		boolean uniqueItemsEnabled,
		Set<Integer> uniqueItemIds,
		boolean petsEnabled)
	{
		this.minimumValueEnabled = minimumValueEnabled;
		this.minimumStackValue = minimumStackValue;
		this.uniqueItemsEnabled = uniqueItemsEnabled;
		this.uniqueItemIds = Collections.unmodifiableSet(new TreeSet<>(uniqueItemIds));
		this.petsEnabled = petsEnabled;
	}

	static DiscordDropFilter defaults()
	{
		return new DiscordDropFilter(true, DEFAULT_MINIMUM_STACK_VALUE, false,
			Collections.emptySet(), true);
	}

	private static DiscordDropFilter disabled()
	{
		return new DiscordDropFilter(false, DEFAULT_MINIMUM_STACK_VALUE, false,
			Collections.emptySet(), false);
	}

	static DiscordDropFilter of(
		boolean minimumValueEnabled,
		long minimumStackValue,
		boolean uniqueItemsEnabled,
		String uniqueItemIds,
		boolean petsEnabled)
	{
		if (minimumStackValue <= 0 || minimumStackValue > MAXIMUM_STACK_VALUE) return null;
		Set<Integer> parsedIds = parseUniqueItemIds(uniqueItemIds);
		if (parsedIds == null || (uniqueItemsEnabled && parsedIds.isEmpty())) return null;
		return new DiscordDropFilter(
			minimumValueEnabled,
			minimumStackValue,
			uniqueItemsEnabled,
			parsedIds,
			petsEnabled);
	}

	static DiscordDropFilter fromStoredValue(String value)
	{
		if (value == null || value.trim().isEmpty()) return defaults();
		String[] parts = value.split("\\|", -1);
		if (parts.length != 6 || !SERIALIZED_VERSION.equals(parts[0])) return disabled();
		Boolean minimumEnabled = parseBoolean(parts[1]);
		Boolean uniqueEnabled = parseBoolean(parts[3]);
		Boolean petsEnabled = parseBoolean(parts[4]);
		if (minimumEnabled == null || uniqueEnabled == null || petsEnabled == null) return disabled();
		try
		{
			long minimum = Long.parseLong(parts[2]);
			DiscordDropFilter parsed = of(
				minimumEnabled, minimum, uniqueEnabled, parts[5], petsEnabled);
			return parsed == null ? disabled() : parsed;
		}
		catch (NumberFormatException exception)
		{
			return disabled();
		}
	}

	String toStoredValue()
	{
		return SERIALIZED_VERSION + "|"
			+ minimumValueEnabled + "|"
			+ minimumStackValue + "|"
			+ uniqueItemsEnabled + "|"
			+ petsEnabled + "|"
			+ getUniqueItemIdsText().replace(" ", "");
	}

	boolean allows(RareDropReport report)
	{
		return filteredReport(report) != null;
	}

	RareDropReport filteredReport(RareDropReport report)
	{
		if (report == null) return null;
		if (report.isPet()) return petsEnabled ? report : null;

		List<RareDropItem> matchingItems = new ArrayList<>();
		for (RareDropItem item : report.getItems())
		{
			if (item == null) continue;
			boolean listedUnique = uniqueItemsEnabled && uniqueItemIds.contains(item.getItemId());
			boolean valuable = minimumValueEnabled && item.getStackGeValue() >= minimumStackValue;
			if (listedUnique || valuable) matchingItems.add(item);
		}
		return matchingItems.isEmpty() ? null : report.withItems(matchingItems);
	}

	boolean acceptsItemDrops()
	{
		return minimumValueEnabled || (uniqueItemsEnabled && !uniqueItemIds.isEmpty());
	}

	boolean isMinimumValueEnabled()
	{
		return minimumValueEnabled;
	}

	long getMinimumStackValue()
	{
		return minimumStackValue;
	}

	boolean isUniqueItemsEnabled()
	{
		return uniqueItemsEnabled;
	}

	String getUniqueItemIdsText()
	{
		StringJoiner values = new StringJoiner(", ");
		for (Integer itemId : uniqueItemIds) values.add(itemId.toString());
		return values.toString();
	}

	boolean isPetsEnabled()
	{
		return petsEnabled;
	}

	private static Set<Integer> parseUniqueItemIds(String value)
	{
		Set<Integer> itemIds = new TreeSet<>();
		String normalized = value == null ? "" : value.trim();
		if (normalized.isEmpty()) return itemIds;
		String[] parts = normalized.split("[,\\s]+", -1);
		for (String part : parts)
		{
			if (part.isEmpty()) return null;
			try
			{
				int itemId = Integer.parseInt(part);
				if (itemId <= 0) return null;
				itemIds.add(itemId);
			}
			catch (NumberFormatException exception)
			{
				return null;
			}
		}
		return itemIds;
	}

	private static Boolean parseBoolean(String value)
	{
		if ("true".equals(value)) return true;
		if ("false".equals(value)) return false;
		return null;
	}
}

package com.raredropping;

import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

/** Keeps Discord image work bounded and off RuneLite's shared scheduler. */
final class DiscordScreenshotQueue implements AutoCloseable
{
	static final int MAX_QUEUED_SCREENSHOTS = 4;
	private static final AtomicInteger THREAD_SEQUENCE = new AtomicInteger();

	private final ThreadPoolExecutor executor = new ThreadPoolExecutor(
		1,
		1,
		0L,
		TimeUnit.MILLISECONDS,
		new ArrayBlockingQueue<>(MAX_QUEUED_SCREENSHOTS),
		task ->
		{
			Thread thread = new Thread(task,
				"exodus-bingo-discord-image-" + THREAD_SEQUENCE.incrementAndGet());
			thread.setDaemon(true);
			return thread;
		},
		new ThreadPoolExecutor.AbortPolicy());

	boolean submit(Runnable task)
	{
		if (task == null) return false;
		try
		{
			executor.execute(task);
			return true;
		}
		catch (RejectedExecutionException ignored)
		{
			return false;
		}
	}

	void submitOrRunFallback(Runnable task, Runnable fallback)
	{
		if (!submit(task) && fallback != null) fallback.run();
	}

	@Override
	public void close()
	{
		executor.shutdownNow();
	}
}

