		OkHttpClient http,
		ScheduledExecutorService scheduler,
		Gson gson,
		HttpUrl webhookUrl)
	{
		if (http == null || scheduler == null || gson == null || webhookUrl == null)
		{
			throw new IllegalArgumentException("Invalid Discord webhook client configuration");
		}
		Dispatcher privateDispatcher = new Dispatcher();
		privateDispatcher.setMaxRequests(1);
		privateDispatcher.setMaxRequestsPerHost(1);
		this.dispatcher = privateDispatcher;
		this.http = http.newBuilder()
			.dispatcher(privateDispatcher)
			.followRedirects(false)
			.followSslRedirects(false)
			.retryOnConnectionFailure(false)
			.addNetworkInterceptor(chain ->
			{
				Response response = chain.proceed(chain.request());
				// OkHttp otherwise performs an implicit follow-up for a 503 with
				// Retry-After: 0, outside this client's bounded attempt counter.
				if (response.code() == 503 && "0".equals(response.header("Retry-After")))
				{
					return response.newBuilder()
						.header(PRESERVED_RETRY_AFTER, "0")
						.header("Retry-After", "1")
						.build();
				}
				return response;
			})
			.build();
		this.scheduler = scheduler;
		this.gson = gson;
		this.webhookUrl = webhookUrl;
	}

	/** Local HTTP exists only as a package-private integration-test seam. */
	static DiscordWebhookClient forLoopbackTests(
		OkHttpClient http,
		ScheduledExecutorService scheduler,
		Gson gson,
		String webhookUrl)
	{
		return new DiscordWebhookClient(http, scheduler, gson, parseLoopbackWebhookUrl(webhookUrl));
	}

	static String normalizeWebhookUrl(String value)
	{
		HttpUrl parsed = parseProductionWebhookUrl(value);
		return parsed == null ? null : parsed.toString();
	}

	static boolean isAllowedWebhookUrl(String value)
	{
		return parseProductionWebhookUrl(value) != null;
	}

	void send(RareDropReport report, RareDropScreenshot screenshot, ResultListener listener)
	{
		if (closed || report == null || (screenshot != null
			&& !"image/jpeg".equalsIgnoreCase(screenshot.getMediaType())))
		{
			notifyListener(listener, DeliveryResult.failed(report == null ? null : report.getEventId(), 0));
			return;
		}
		if (!deliverySlots.tryAcquire())
		{
			notifyListener(listener, DeliveryResult.failed(report.getEventId(), 0));
			return;
		}
		DeliveryContext delivery = new DeliveryContext(report.getEventId(), listener);
		activeDeliveries.add(delivery);
		if (closed)
		{
			delivery.complete(DeliveryResult.failed(report.getEventId(), 0));
			return;
		}

		Request request;
		try
		{
			String payload = payload(report, screenshot != null);
			if (payload.getBytes(StandardCharsets.UTF_8).length > MAX_PAYLOAD_BYTES)
			{
				throw new IllegalArgumentException("Discord payload is too large");
			}
			RequestBody body;
			if (screenshot == null)
			{
				body = RequestBody.create(JSON, payload);
			}
			else
			{
				body = new MultipartBody.Builder()
					.setType(MultipartBody.FORM)
					.addFormDataPart("payload_json", payload)
					.addFormDataPart("files[0]", "drop.jpg",
						RequestBody.create(JPEG, screenshot.copyData()))
					.build();
			}
			request = new Request.Builder()
				.url(webhookUrl)
				.header("Accept", "application/json")
				.post(body)
				.build();
		}
		catch (RuntimeException exception)
		{
			delivery.complete(DeliveryResult.failed(report.getEventId(), 0));
			return;
		}

		execute(request, delivery, 1);
	}

	private void execute(Request request, DeliveryContext delivery, int attempt)
	{
		if (closed || delivery.isComplete())
		{
			delivery.complete(DeliveryResult.failed(delivery.eventId, 0));
			return;
		}
		Call call = http.newCall(request);
		activeCalls.add(call);
		if (closed && activeCalls.remove(call))
		{
			call.cancel();
			delivery.complete(DeliveryResult.failed(delivery.eventId, 0));
			return;
		}
		try
		{
			call.enqueue(new Callback()
			{
				@Override public void onFailure(Call failedCall, IOException exception)
				{
					activeCalls.remove(failedCall);
					if (closed || failedCall.isCanceled())
					{
						delivery.complete(DeliveryResult.failed(delivery.eventId, 0));
						return;
					}
					if (attempt < MAX_ATTEMPTS
						&& scheduleRetry(request, delivery, attempt + 1, defaultRetryDelay(attempt)))
					{
						return;
					}
					delivery.complete(DeliveryResult.failed(delivery.eventId, 0));
				}

				@Override public void onResponse(Call completedCall, Response response)
				{
					activeCalls.remove(completedCall);
					try (Response ignored = response)
					{
						int statusCode = response.code();
						if (statusCode == 200 || statusCode == 204)
						{
							delivery.complete(DeliveryResult.accepted(delivery.eventId, statusCode));
							return;
						}
						if (isRetryable(statusCode) && attempt < MAX_ATTEMPTS)
						{
							long delay = retryDelay(response, attempt);
							if (delay >= 0 && scheduleRetry(
								request, delivery, attempt + 1, delay))
							{
								return;
							}
						}
						delivery.complete(DeliveryResult.failed(delivery.eventId, statusCode));
					}
					catch (RuntimeException exception)
					{
						delivery.complete(DeliveryResult.failed(delivery.eventId, response.code()));
					}
				}
			});
		}
		catch (RuntimeException exception)
		{
			activeCalls.remove(call);
			delivery.complete(DeliveryResult.failed(delivery.eventId, 0));
		}
	}

	private boolean scheduleRetry(
		Request request,
		DeliveryContext delivery,
		int nextAttempt,
		long delayMillis)
	{
		if (closed || nextAttempt > MAX_ATTEMPTS
			|| delayMillis < 0 || delayMillis > MAX_RETRY_DELAY_MILLIS)
		{
			return false;
		}
		try
		{
			RetryRegistration registration = new RetryRegistration();
			ScheduledFuture<?> retry = scheduler.schedule(() ->
			{
				synchronized (scheduledRetries)
				{
					registration.fired = true;
					if (registration.future != null)
					{
						scheduledRetries.remove(registration.future);
					}
				}
				if (!closed) execute(request, delivery, nextAttempt);
				else delivery.complete(DeliveryResult.failed(delivery.eventId, 0));
			}, delayMillis, TimeUnit.MILLISECONDS);
			synchronized (scheduledRetries)
			{
				registration.future = retry;
				if (registration.fired) return true;
				if (closed || delivery.isComplete())
				{
					retry.cancel(false);
					return false;
				}
				if (retry.isDone()) return false;
				scheduledRetries.add(retry);
			}
			return true;
		}
		catch (RejectedExecutionException exception)
		{
			return false;
		}
	}

	int pendingRetryCountForTests()
	{
		synchronized (scheduledRetries)
		{
			return scheduledRetries.size();
		}
	}

	private long retryDelay(Response response, int attempt)
	{
		String preserved = response.code() == 503 ? response.header(PRESERVED_RETRY_AFTER) : null;
		Long headerDelay = parseRetryAfter(preserved == null
			? response.header("Retry-After") : preserved);
		if (headerDelay == null)
		{
			headerDelay = parseSeconds(response.header("X-RateLimit-Reset-After"));
		}
		if (headerDelay == null && response.code() == 429)
		{
			headerDelay = retryAfterFromJson(response);
		}
		return headerDelay == null ? defaultRetryDelay(attempt) : headerDelay;
	}

	private Long retryAfterFromJson(Response response)
	{
		try
		{
			String body = BoundedHttpBody.readUtf8(response.body());
			if (body.trim().isEmpty()) return null;
			JsonElement parsed = new JsonParser().parse(body);
			if (!parsed.isJsonObject()) return null;
			JsonElement retryAfter = parsed.getAsJsonObject().get("retry_after");
			return retryAfter == null ? null : secondsToMillis(retryAfter.getAsDouble());
		}
		catch (IOException | RuntimeException exception)
		{
			return null;
		}
	}

	private static Long parseRetryAfter(String value)
	{
		Long seconds = parseSeconds(value);
		if (seconds != null) return seconds;
		if (value == null || value.trim().isEmpty()) return null;
		try
		{
			Instant retryAt = ZonedDateTime.parse(value.trim(), DateTimeFormatter.RFC_1123_DATE_TIME).toInstant();
			return Math.max(0, Duration.between(Instant.now(), retryAt).toMillis());
		}
		catch (DateTimeParseException exception)
		{
			return null;
		}
	}

	private static Long parseSeconds(String value)
	{
		if (value == null || value.trim().isEmpty()) return null;
		try
		{
			return secondsToMillis(Double.parseDouble(value.trim()));
		}
		catch (NumberFormatException exception)
		{
			return null;
		}
	}

	private static Long secondsToMillis(double seconds)
	{
		if (!Double.isFinite(seconds) || seconds < 0) return null;
		double milliseconds = Math.ceil(seconds * 1_000d);
		return milliseconds > Long.MAX_VALUE ? Long.MAX_VALUE : (long) milliseconds;
	}

	private static long defaultRetryDelay(int completedAttempt)
	{
		return 1_000L << Math.max(0, completedAttempt - 1);
	}

	private static boolean isRetryable(int statusCode)
	{
		return statusCode == 408 || statusCode == 429 || statusCode >= 500;
	}

	private String payload(RareDropReport report, boolean includeScreenshot)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("username", "Exodus Bingo");
		JsonObject allowedMentions = new JsonObject();
		allowedMentions.add("parse", new JsonArray());
		payload.add("allowed_mentions", allowedMentions);

		JsonObject embed = new JsonObject();
		embed.addProperty("title", report.isPet() ? "Pet obtained" : "RuneLite loot drop");
		embed.addProperty("color", 0x58C887);
		embed.addProperty("timestamp", report.getOccurredAt());
		JsonArray fields = new JsonArray();
		addField(fields, "Player", text(report.getUsername(), "Unknown"), true);
		addField(fields, "Source", text(report.getSourceNpc(), "Not reported"), true);
		addField(fields, "Event type", report.isPet() ? "Pet obtained" : "Item drop", true);
		if (report.isPet())
		{
			addField(fields, "Pet", text(report.getPetName(), "Name unavailable"), false);
			addField(fields, "Pet item ID",
				report.getPetItemId() == null ? "Not available" : report.getPetItemId().toString(), true);
			addField(fields, "Award type", text(report.getPetAwardType(), "Unknown"), true);
		}
		else
		{
			addItemFields(fields, report.getItems());
		}
		if (fields.size() > MAX_EMBED_FIELDS)
		{
			throw new IllegalArgumentException("Discord embed has too many fields");
		}
		embed.add("fields", fields);
		if (includeScreenshot)
		{
			JsonObject image = new JsonObject();
			image.addProperty("url", "attachment://drop.jpg");
			embed.add("image", image);
		}
		JsonObject footer = new JsonObject();
		footer.addProperty("text", "Captured by Exodus Bingo for RuneLite");
		embed.add("footer", footer);
		if (embedTextLength(embed) > MAX_EMBED_TEXT_LENGTH)
		{
			throw new IllegalArgumentException("Discord embed is too large");
		}
		JsonArray embeds = new JsonArray();
		embeds.add(embed);
		payload.add("embeds", embeds);
		return gson.toJson(payload);
	}

	private static void addItemFields(JsonArray fields, List<RareDropItem> items)
	{
		if (items == null || items.isEmpty())
		{
			throw new IllegalArgumentException("An item drop needs item details");
		}
		List<String> chunks = new ArrayList<>();
		StringBuilder chunk = new StringBuilder();
		for (RareDropItem item : items)
		{
			if (item == null) continue;
			String line = text(item.getName(), "Item " + item.getItemId())
				+ " (ID " + item.getItemId() + ")"
				+ " — quantity " + item.getQuantity()
				+ ", unit GE " + item.getUnitGePrice()
				+ ", stack GE " + item.getStackGeValue();
			if (line.length() > MAX_FIELD_VALUE_LENGTH)
			{
				throw new IllegalArgumentException("Discord item detail is too large");
			}
			int separatorLength = chunk.length() == 0 ? 0 : 1;
			if (chunk.length() + separatorLength + line.length() > MAX_FIELD_VALUE_LENGTH)
			{
				chunks.add(chunk.toString());
				chunk.setLength(0);
			}
			if (chunk.length() > 0) chunk.append('\n');
			chunk.append(line);
		}
		if (chunk.length() > 0) chunks.add(chunk.toString());
		if (chunks.isEmpty())
		{
			throw new IllegalArgumentException("An item drop needs item details");
		}
		for (int index = 0; index < chunks.size(); index++)
		{
			addField(fields, index == 0 ? "Drops" : "Drops (continued " + (index + 1) + ")",
				chunks.get(index), false);
		}
	}

	private static void addField(JsonArray fields, String name, String value, boolean inline)
	{
		if (name == null || name.isEmpty() || name.length() > 256
			|| value == null || value.isEmpty() || value.length() > MAX_FIELD_VALUE_LENGTH)
		{
			throw new IllegalArgumentException("Invalid Discord embed field");
		}
		JsonObject field = new JsonObject();
		field.addProperty("name", name);
		field.addProperty("value", value);
		field.addProperty("inline", inline);
		fields.add(field);
	}

	private static int embedTextLength(JsonObject embed)
	{
		int total = jsonStringLength(embed.get("title"))
			+ jsonStringLength(embed.get("description"));
		JsonElement footer = embed.get("footer");
		if (footer != null && footer.isJsonObject())
		{
			total += jsonStringLength(footer.getAsJsonObject().get("text"));
		}
		JsonElement fields = embed.get("fields");
		if (fields != null && fields.isJsonArray())
		{
			for (JsonElement field : fields.getAsJsonArray())
			{
				if (!field.isJsonObject()) continue;
				total += jsonStringLength(field.getAsJsonObject().get("name"));
				total += jsonStringLength(field.getAsJsonObject().get("value"));
			}
		}
		return total;
	}

	private static int jsonStringLength(JsonElement value)
	{
		return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()
			? value.getAsString().length() : 0;
	}

	private static String text(String value, String fallback)
	{
		return value == null || value.trim().isEmpty() ? fallback : value.trim();
	}

	private static HttpUrl parseProductionWebhookUrl(String value)
	{
		return parseWebhookUrl(value, false);
	}

	private static HttpUrl parseLoopbackWebhookUrl(String value)
	{
		return parseWebhookUrl(value, true);
	}

	private static HttpUrl parseWebhookUrl(String value, boolean loopbackOnly)
	{
		if (value == null || value.trim().isEmpty()) return null;
		HttpUrl url = HttpUrl.parse(value.trim());
		if (url == null || !url.username().isEmpty() || !url.password().isEmpty()
			|| url.query() != null || url.fragment() != null)
		{
			return null;
		}
		String host = url.host().toLowerCase(Locale.ROOT);
		if (loopbackOnly)
		{
			boolean loopback = "localhost".equals(host) || "127.0.0.1".equals(host) || "::1".equals(host);
			if (!loopback || !("http".equalsIgnoreCase(url.scheme())
				|| "https".equalsIgnoreCase(url.scheme()))) return null;
		}
		else if (!"https".equalsIgnoreCase(url.scheme()) || url.port() != 443
			|| !DISCORD_HOSTS.contains(host))
		{
			return null;
		}

		List<String> segments = url.pathSegments();
		if (segments.size() != 4 || !"api".equals(segments.get(0))
			|| !"webhooks".equals(segments.get(1))
			|| !WEBHOOK_ID.matcher(segments.get(2)).matches()
			|| !WEBHOOK_TOKEN.matcher(segments.get(3)).matches())
		{
			return null;
		}
		String expectedPath = "/api/webhooks/" + segments.get(2) + "/" + segments.get(3);
		if (!expectedPath.equals(url.encodedPath())) return null;
		return url;
	}

	private static void notifyListener(ResultListener listener, DeliveryResult result)
	{
		if (listener == null) return;
		try
		{
			listener.onResult(result);
		}
		catch (RuntimeException ignored)
		{
			// A UI callback must not escape an OkHttp or scheduler thread.
		}
	}

	@Override public void close()
	{
		closed = true;
		List<Call> calls;
		synchronized (activeCalls)
		{
			calls = new ArrayList<>(activeCalls);
			activeCalls.clear();
		}
		for (Call call : calls) call.cancel();
		List<ScheduledFuture<?>> retries;
		synchronized (scheduledRetries)
		{
			retries = new ArrayList<>(scheduledRetries);
			scheduledRetries.clear();
		}
		for (ScheduledFuture<?> retry : retries) retry.cancel(false);
		List<DeliveryContext> deliveries;
		synchronized (activeDeliveries)
		{
			deliveries = new ArrayList<>(activeDeliveries);
		}
		for (DeliveryContext delivery : deliveries)
		{
			delivery.complete(DeliveryResult.failed(delivery.eventId, 0));
		}
		dispatcher.executorService().shutdownNow();
	}

	private final class DeliveryContext
	{
		private final String eventId;
		private final ResultListener listener;
		private final AtomicBoolean complete = new AtomicBoolean();

		private DeliveryContext(String eventId, ResultListener listener)
		{
			this.eventId = eventId;
			this.listener = listener;
		}

		private boolean isComplete()
		{
			return complete.get();
		}

		private void complete(DeliveryResult result)
		{
			if (!complete.compareAndSet(false, true)) return;
			activeDeliveries.remove(this);
			deliverySlots.release();
			notifyListener(listener, result);
		}
	}

	private static final class RetryRegistration
	{
		private ScheduledFuture<?> future;
		private boolean fired;
	}

	interface ResultListener
	{
		void onResult(DeliveryResult result);
	}

	static final class DeliveryResult
	{
		private final String eventId;
		private final boolean accepted;
		private final int statusCode;

		private DeliveryResult(String eventId, boolean accepted, int statusCode)
		{
			this.eventId = eventId;
			this.accepted = accepted;
			this.statusCode = statusCode;
		}

		private static DeliveryResult accepted(String eventId, int statusCode)
		{
			return new DeliveryResult(eventId, true, statusCode);
		}

		private static DeliveryResult failed(String eventId, int statusCode)
		{
			return new DeliveryResult(eventId, false, statusCode);
		}

		String getEventId()
		{
			return eventId;
		}

		boolean isAccepted()
		{
			return accepted;
		}

		int getStatusCode()
		{
			return statusCode;
		}
	}
}

package com.raredropping;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.PosixFilePermission;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.EnumSet;
import java.util.Set;

/** Minimal local secret store for one normalized Discord incoming-webhook URL. */
final class DiscordWebhookSettingsStore
{
	static final int MAX_FILE_BYTES = 512;
	private static final Set<PosixFilePermission> OWNER_FILE_PERMISSIONS = EnumSet.of(
		PosixFilePermission.OWNER_READ,
		PosixFilePermission.OWNER_WRITE);
	private static final Set<PosixFilePermission> OWNER_DIRECTORY_PERMISSIONS = EnumSet.of(
		PosixFilePermission.OWNER_READ,
		PosixFilePermission.OWNER_WRITE,
		PosixFilePermission.OWNER_EXECUTE);

	private final Path file;
	private final Path parent;
	private final String temporaryPrefix;

	DiscordWebhookSettingsStore(Path file)
	{
		if (file == null)
		{
			throw new IllegalArgumentException("A Discord webhook settings file is required");
		}
		Path normalized = file.toAbsolutePath().normalize();
		Path normalizedParent = normalized.getParent();
		if (normalizedParent == null || normalized.getFileName() == null)
		{
			throw new IllegalArgumentException("A Discord webhook settings file is required");
		}
		this.file = normalized;
		this.parent = normalizedParent;
		String fileName = normalized.getFileName().toString();
		this.temporaryPrefix = "." + (fileName.length() < 3 ? "webhook" : fileName) + ".";
	}

	synchronized String load() throws IOException
	{
		cleanupStaleTemporaryFiles();
		if (!Files.exists(file, LinkOption.NOFOLLOW_LINKS)
			|| !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS))
		{
			return null;
		}
		byte[] content = readBounded(file);
		if (content == null || content.length == 0) return null;
		String raw = decodeUtf8(content);
		if (raw == null) return null;
		String normalized = DiscordWebhookClient.normalizeWebhookUrl(raw);
		// The on-disk format contains the canonical URL and nothing else. This
		// also rejects trailing newlines and whitespace added by another tool.
		return normalized != null && normalized.equals(raw) ? normalized : null;
	}

	synchronized boolean save(String value) throws IOException
	{
		String normalized = DiscordWebhookClient.normalizeWebhookUrl(value);
		if (normalized == null) return false;
		byte[] content = normalized.getBytes(StandardCharsets.UTF_8);
		if (content.length == 0 || content.length > MAX_FILE_BYTES) return false;

		createParentDirectory();
		cleanupStaleTemporaryFiles();
		Path temporary = createTemporaryFile();
		boolean moved = false;
		try
		{
			writeAndSync(temporary, content);
			applyOwnerOnlyPermissions(temporary);
			try
			{
				Files.move(temporary, file,
					StandardCopyOption.ATOMIC_MOVE,
					StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException exception)
			{
				Files.move(temporary, file, StandardCopyOption.REPLACE_EXISTING);
			}
			moved = true;
			applyOwnerOnlyPermissions(file);
			return true;
		}
		finally
		{
			if (!moved) Files.deleteIfExists(temporary);
		}
	}

	synchronized boolean clear() throws IOException
	{
		cleanupStaleTemporaryFiles();
		if (!Files.exists(file, LinkOption.NOFOLLOW_LINKS)) return false;
		if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)
			&& !Files.isSymbolicLink(file))
		{
			return false;
		}
		Files.delete(file);
		return true;
	}

	Path getFile()
	{
		return file;
	}

	private void createParentDirectory() throws IOException
	{
		if (Files.exists(parent, LinkOption.NOFOLLOW_LINKS))
		{
			if (!Files.isDirectory(parent))
			{
				throw new IOException("The Discord webhook settings parent is not a directory");
			}
			return;
		}
		try
		{
			Files.createDirectories(parent,
				PosixFilePermissions.asFileAttribute(OWNER_DIRECTORY_PERMISSIONS));
		}
		catch (UnsupportedOperationException exception)
		{
			Files.createDirectories(parent);
		}
	}

	private Path createTemporaryFile() throws IOException
	{
		try
		{
			return Files.createTempFile(parent, temporaryPrefix, ".tmp",
				PosixFilePermissions.asFileAttribute(OWNER_FILE_PERMISSIONS));
		}
		catch (UnsupportedOperationException exception)
		{
			Path temporary = Files.createTempFile(parent, temporaryPrefix, ".tmp");
			applyOwnerOnlyPermissions(temporary);
			return temporary;
		}
	}

	private void cleanupStaleTemporaryFiles() throws IOException
	{
		if (!Files.isDirectory(parent, LinkOption.NOFOLLOW_LINKS)) return;
		try (DirectoryStream<Path> entries = Files.newDirectoryStream(parent))
		{
			for (Path entry : entries)
			{
				String name = entry.getFileName().toString();
				if (!name.startsWith(temporaryPrefix) || !name.endsWith(".tmp")) continue;
				if (Files.isRegularFile(entry, LinkOption.NOFOLLOW_LINKS)
					|| Files.isSymbolicLink(entry))
				{
					Files.deleteIfExists(entry);
				}
			}
		}
	}

	private static void writeAndSync(Path path, byte[] content) throws IOException
	{
		try (FileChannel channel = FileChannel.open(path,
			StandardOpenOption.WRITE,
			StandardOpenOption.TRUNCATE_EXISTING,
			LinkOption.NOFOLLOW_LINKS))
		{
			ByteBuffer buffer = ByteBuffer.wrap(content);
			while (buffer.hasRemaining()) channel.write(buffer);
			channel.force(true);
		}
	}

	private static byte[] readBounded(Path path) throws IOException
	{
		try (InputStream input = Files.newInputStream(path,
			StandardOpenOption.READ,
			LinkOption.NOFOLLOW_LINKS))
		{
			ByteArrayOutputStream output = new ByteArrayOutputStream(MAX_FILE_BYTES);
			byte[] buffer = new byte[128];
			int total = 0;
			int count;
			while ((count = input.read(buffer)) != -1)
			{
				if (count == 0) continue;
				if (total > MAX_FILE_BYTES - count) return null;
				output.write(buffer, 0, count);
				total += count;
			}
			return output.toByteArray();
		}
	}

	private static String decodeUtf8(byte[] content)
	{
		try
		{
			return StandardCharsets.UTF_8.newDecoder()
				.onMalformedInput(CodingErrorAction.REPORT)
				.onUnmappableCharacter(CodingErrorAction.REPORT)
				.decode(ByteBuffer.wrap(content))
				.toString();
		}
		catch (CharacterCodingException exception)
		{
			return null;
		}
	}

	private static void applyOwnerOnlyPermissions(Path path)
	{
		try
		{
			Files.setPosixFilePermissions(path, OWNER_FILE_PERMISSIONS);
			return;
		}
		catch (IOException | UnsupportedOperationException | SecurityException ignored)
		{
			// Fall through to the platform File API where POSIX permissions are unavailable.
		}

		try
		{
			File localFile = path.toFile();
			localFile.setReadable(false, false);
			localFile.setWritable(false, false);
			localFile.setExecutable(false, false);
			localFile.setReadable(true, true);
			localFile.setWritable(true, true);
		}
		catch (RuntimeException ignored)
		{
			// Permissions are best-effort on filesystems without owner-only controls.
		}
	}
}

package com.raredropping;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

final class RareDropCaptureArea
{
	private static final int LOGICAL_PADDING = 24;

	private final int canvasWidth;
	private final int canvasHeight;
	private final int viewportX;
	private final int viewportY;
	private final int viewportWidth;
	private final int viewportHeight;

	RareDropCaptureArea(
		int canvasWidth,
		int canvasHeight,
		int viewportX,
		int viewportY,
		int viewportWidth,
		int viewportHeight)
	{
		this.canvasWidth = canvasWidth;
		this.canvasHeight = canvasHeight;
		this.viewportX = viewportX;
		this.viewportY = viewportY;
		this.viewportWidth = viewportWidth;
		this.viewportHeight = viewportHeight;
	}

	BufferedImage crop(BufferedImage source)
	{
		if (source == null)
		{
			throw new IllegalArgumentException("Source image is required");
		}
		if (canvasWidth <= 0 || canvasHeight <= 0 || viewportWidth <= 0 || viewportHeight <= 0)
		{
			return copy(source, 0, 0, source.getWidth(), source.getHeight());
		}

		double horizontalScale = (double) source.getWidth() / canvasWidth;
		double verticalScale = (double) source.getHeight() / canvasHeight;
		int left = clamp(
			(int) Math.floor((viewportX - LOGICAL_PADDING) * horizontalScale),
			0,
			source.getWidth() - 1);
		int top = clamp(
			(int) Math.floor((viewportY - LOGICAL_PADDING) * verticalScale),
			0,
			source.getHeight() - 1);
		int right = clamp(
			(int) Math.ceil((viewportX + viewportWidth + LOGICAL_PADDING) * horizontalScale),
			left + 1,
			source.getWidth());
		int bottom = clamp(
			(int) Math.ceil((viewportY + viewportHeight + LOGICAL_PADDING) * verticalScale),
			top + 1,
			source.getHeight());
		return copy(source, left, top, right - left, bottom - top);
	}

	private static BufferedImage copy(BufferedImage source, int x, int y, int width, int height)
	{
		BufferedImage cropped = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = cropped.createGraphics();
		graphics.drawImage(source, 0, 0, width, height, x, y, x + width, y + height, null);
		graphics.dispose();
		return cropped;
	}

	private static int clamp(int value, int minimum, int maximum)
	{
		return Math.max(minimum, Math.min(maximum, value));
	}
}

package com.raredropping;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

/** Converts complete RuneLite loot records to raw canonical item metadata. */
final class RareDropEvaluator
{
	private static final long MAX_SAFE_JSON_INTEGER = 9_007_199_254_740_991L;
	private final ItemData itemData;

	RareDropEvaluator(ItemManager itemManager)
	{
		this(new RuneLiteItemData(itemManager));
	}

	RareDropEvaluator(ItemData itemData)
	{
		this.itemData = itemData;
	}

	List<RareDropItem> collectItems(Collection<ItemStack> itemStacks)
	{
		if (itemStacks == null || itemStacks.isEmpty()) return Collections.emptyList();
		Map<Integer, Long> quantities = new LinkedHashMap<>();
		for (ItemStack itemStack : itemStacks)
		{
			if (itemStack == null || itemStack.getQuantity() <= 0) continue;
			int itemId = itemData.canonicalize(itemStack.getId());
			quantities.merge(itemId, (long) itemStack.getQuantity(), RareDropEvaluator::saturatedAdd);
		}

		List<RareDropItem> items = new ArrayList<>(quantities.size());
		for (Map.Entry<Integer, Long> entry : quantities.entrySet())
		{
			int itemId = entry.getKey();
			long quantity = entry.getValue();
			int unitPrice = Math.max(0, itemData.getPrice(itemId));
			String name = itemData.getName(itemId);
			items.add(new RareDropItem(
				itemId,
				name == null || name.trim().isEmpty() ? "Item " + itemId : name.trim(),
				quantity,
				unitPrice,
				saturatedMultiply(unitPrice, quantity)));
		}
		return Collections.unmodifiableList(items);
	}

	private static long saturatedAdd(long first, long second)
	{
		return second > 0 && first > Integer.MAX_VALUE - second ? Integer.MAX_VALUE : first + second;
	}

	private static long saturatedMultiply(long first, long second)
	{
		if (first == 0 || second == 0) return 0;
		return first > MAX_SAFE_JSON_INTEGER / second ? MAX_SAFE_JSON_INTEGER : first * second;
	}

	interface ItemData
	{
		int canonicalize(int itemId);
		int getPrice(int itemId);
		String getName(int itemId);
	}

	private static final class RuneLiteItemData implements ItemData
	{
		private final ItemManager itemManager;
		private RuneLiteItemData(ItemManager itemManager) { this.itemManager = itemManager; }
		@Override public int canonicalize(int itemId) { return itemManager.canonicalize(itemId); }
		@Override public int getPrice(int itemId) { return itemManager.getItemPrice(itemId); }
		@Override public String getName(int itemId) { return itemManager.getItemComposition(itemId).getName(); }
	}
}

package com.raredropping;

import java.util.Locale;

/**
 * Stable wire values used to distinguish RuneLite capture mechanisms.
 */
enum RareDropEventType
{
	ITEM_DROP("item_drop", "Loot drop"),
	PET_OBTAINED("pet_obtained", "Pet obtained");

	private final String wireValue;
	private final String displayName;

	RareDropEventType(String wireValue, String displayName)
	{
		this.wireValue = wireValue;
		this.displayName = displayName;
	}

	String getWireValue()
	{
		return wireValue;
	}

	String getDisplayName()
	{
		return displayName;
	}

	static RareDropEventType fromWireValue(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return null;
		}
		String normalized = value.trim().toLowerCase(Locale.ROOT);
		for (RareDropEventType type : values())
		{
			if (type.wireValue.equals(normalized))
			{
				return type;
			}
		}
		throw new IllegalArgumentException("Unknown rare-drop event type");
	}
}

package com.raredropping;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

final class RareDropEvidenceRenderer
{
	private static final int PADDING = 10;
	private static final int BANNER_HEIGHT = 64;

	private RareDropEvidenceRenderer()
	{
	}

	static BufferedImage render(BufferedImage source, RareDropReport report)
	{
		return render(source, report, report != null && report.isPet() ? "PET DROP" : "RARE DROP");
	}

	static BufferedImage renderDiscord(BufferedImage source, RareDropReport report)
	{
		return render(source, report, report != null && report.isPet() ? "PET DROP" : "LOOT DROP");
	}

	private static BufferedImage render(BufferedImage source, RareDropReport report, String title)
	{
		if (source == null || report == null)
		{
			throw new IllegalArgumentException("Source image and report are required");
		}

		BufferedImage rendered = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = rendered.createGraphics();
		try
		{
			graphics.drawImage(source, 0, 0, null);
			graphics.setComposite(AlphaComposite.SrcOver.derive(0.82f));
			graphics.setColor(Color.BLACK);
			graphics.fillRect(0, 0, rendered.getWidth(), Math.min(BANNER_HEIGHT, rendered.getHeight()));
			graphics.setComposite(AlphaComposite.SrcOver);
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			Font titleFont = new Font(Font.SANS_SERIF, Font.BOLD, 16);
			graphics.setFont(titleFont);
			graphics.setColor(new Color(255, 190, 0));
			graphics.drawString(title, PADDING, 22);

			Font detailFont = new Font(Font.SANS_SERIF, Font.PLAIN, 14);
			graphics.setFont(detailFont);
			graphics.setColor(Color.WHITE);
			String details = report.isPet() ? petDetails(report) : itemDetails(report.getItems());
			graphics.drawString(fit(details, graphics.getFontMetrics(), rendered.getWidth() - (PADDING * 2)), PADDING, 43);

			graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
			graphics.setColor(new Color(210, 210, 210));
			String timestamp = "Captured for event at " + report.getOccurredAt();
			graphics.drawString(fit(timestamp, graphics.getFontMetrics(), rendered.getWidth() - (PADDING * 2)), PADDING, 58);
		}
		finally
		{
			graphics.dispose();
		}
		return rendered;
	}

	private static String petDetails(RareDropReport report)
	{
		return report.getPetName() + " - untradeable (0 GE value)";
	}

	private static String itemDetails(List<RareDropItem> items)
	{
		long totalValue = 0;
		for (RareDropItem item : items)
		{
			long value = item.getStackGeValue();
			totalValue = Long.MAX_VALUE - totalValue < value ? Long.MAX_VALUE : totalValue + value;
		}

		String names = items.stream()
			.limit(3)
			.map(item -> item.getName() + (item.getQuantity() > 1 ? " x" + item.getQuantity() : ""))
			.collect(Collectors.joining(", "));
		if (items.size() > 3)
		{
			names += ", +" + (items.size() - 3) + " more";
		}
		return names + " - " + String.format(Locale.US, "%,d gp", totalValue);
	}

	private static String fit(String text, FontMetrics metrics, int maximumWidth)
	{
		if (maximumWidth <= 0 || metrics.stringWidth(text) <= maximumWidth)
		{
			return text;
		}

		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end) + ellipsis) > maximumWidth)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.raredropping;

import java.time.Instant;
import java.util.Objects;

/** Immutable persisted event metadata plus a small mutable delivery state. */
final class RareDropHistoryEntry
{
	enum State
	{
		PENDING,
		SENT,
		IGNORED
	}

	private final String storageId;
	private final String eventId;
	private final String occurredAt;
	private final String savedAt;
	private final String username;
	private final String itemDrop;
	private final String eventType;
	private final String sourceNpc;
	private final int tilePosition;
	private final boolean markComplete;
	private final String endpoint;
	private final String tokenFingerprint;
	private final String screenshotMediaType;
	private final int screenshotWidth;
	private final int screenshotHeight;
	private final int screenshotByteLength;
	private final String screenshotSha256;
	private final State state;
	private final String deliveredAt;
	private final int lastStatusCode;
	private final String rawEventJson;

	RareDropHistoryEntry(
		String storageId, String eventId, String occurredAt, String savedAt,
		String username, String itemDrop, int tilePosition, boolean markComplete,
		String endpoint, String tokenFingerprint, String screenshotMediaType,
		int screenshotWidth, int screenshotHeight, int screenshotByteLength,
		String screenshotSha256, State state, String deliveredAt, int lastStatusCode)
	{
		this(storageId, eventId, occurredAt, savedAt, username, itemDrop,
			RareDropEventType.ITEM_DROP.getWireValue(), null, tilePosition, markComplete,
			endpoint, tokenFingerprint, screenshotMediaType, screenshotWidth, screenshotHeight,
			screenshotByteLength, screenshotSha256, state, deliveredAt, lastStatusCode, null);
	}

	RareDropHistoryEntry(
		String storageId, String eventId, String occurredAt, String savedAt,
		String username, String itemDrop, String eventType, String sourceNpc,
		int tilePosition, boolean markComplete, String endpoint, String tokenFingerprint,
		String screenshotMediaType, int screenshotWidth, int screenshotHeight,
		int screenshotByteLength, String screenshotSha256, State state,
		String deliveredAt, int lastStatusCode)
	{
		this(storageId, eventId, occurredAt, savedAt, username, itemDrop, eventType,
			sourceNpc, tilePosition, markComplete, endpoint, tokenFingerprint,
			screenshotMediaType, screenshotWidth, screenshotHeight, screenshotByteLength,
			screenshotSha256, state, deliveredAt, lastStatusCode, null);
	}

	RareDropHistoryEntry(
		String storageId, String eventId, String occurredAt, String savedAt,
		String username, String itemDrop, String eventType, String sourceNpc,
		int tilePosition, boolean markComplete, String endpoint, String tokenFingerprint,
		String screenshotMediaType, int screenshotWidth, int screenshotHeight,
		int screenshotByteLength, String screenshotSha256, State state,
		String deliveredAt, int lastStatusCode, String rawEventJson)
	{
		String normalizedEventType = normalizeEventType(eventType);
		String normalizedSourceNpc = normalizeSourceNpc(sourceNpc);
		boolean resolved = state != null && state != State.PENDING;
		if (storageId == null || !storageId.matches("[a-f0-9]{64}")
			|| eventId == null || eventId.trim().isEmpty() || eventId.length() > 180
			|| !isInstant(occurredAt) || !isInstant(savedAt)
			|| username == null || username.trim().isEmpty()
			|| itemDrop == null || itemDrop.trim().isEmpty()
			|| itemDrop.length() > RareDropSubmission.MAX_ITEM_DROP_LENGTH
			|| tilePosition < 0 || tilePosition > 25
			|| (tilePosition == 0 && (rawEventJson == null || rawEventJson.trim().isEmpty()))
			|| endpoint == null || endpoint.trim().isEmpty() || endpoint.length() > 2_048
			|| tokenFingerprint == null || !tokenFingerprint.matches("[a-f0-9]{64}")
			|| screenshotMediaType == null || screenshotMediaType.trim().isEmpty()
			|| screenshotWidth <= 0 || screenshotHeight <= 0
			|| screenshotByteLength <= 0
			|| screenshotByteLength > RareDropScreenshotEncoder.MAX_SCREENSHOT_BYTES
			|| screenshotSha256 == null || !screenshotSha256.matches("[a-f0-9]{64}")
			|| state == null
			|| (deliveredAt != null && !isInstant(deliveredAt))
			|| (resolved && deliveredAt == null)
			|| (!resolved && deliveredAt != null)
			|| lastStatusCode < 0 || lastStatusCode > 599
			|| (resolved && lastStatusCode != 200 && lastStatusCode != 201)
			|| (!resolved && (lastStatusCode == 200 || lastStatusCode == 201))
			|| (rawEventJson != null && (rawEventJson.trim().isEmpty()
				|| rawEventJson.length() > RareDropRawEventCodec.MAX_JSON_LENGTH)))
		{
			throw new IllegalArgumentException("Invalid rare-drop history entry");
		}
		this.storageId = storageId;
		this.eventId = eventId;
		this.occurredAt = occurredAt;
		this.savedAt = savedAt;
		this.username = username;
		this.itemDrop = itemDrop;
		this.eventType = normalizedEventType;
		this.sourceNpc = normalizedSourceNpc;
		this.tilePosition = tilePosition;
		this.markComplete = markComplete;
		this.endpoint = endpoint;
		this.tokenFingerprint = tokenFingerprint;
		this.screenshotMediaType = screenshotMediaType;
		this.screenshotWidth = screenshotWidth;
		this.screenshotHeight = screenshotHeight;
		this.screenshotByteLength = screenshotByteLength;
		this.screenshotSha256 = screenshotSha256;
		this.state = state;
		this.deliveredAt = deliveredAt;
		this.lastStatusCode = lastStatusCode;
		this.rawEventJson = rawEventJson;
	}

	String getStorageId() { return storageId; }
	String getEventId() { return eventId; }
	String getOccurredAt() { return occurredAt; }
	String getSavedAt() { return savedAt; }
	String getUsername() { return username; }
	String getItemDrop() { return itemDrop; }
	String getEventType() { return eventType; }
	String getSourceNpc() { return sourceNpc; }
	int getTilePosition() { return tilePosition; }
	boolean isMarkComplete() { return markComplete; }
	String getEndpoint() { return endpoint; }
	String getTokenFingerprint() { return tokenFingerprint; }
	String getScreenshotMediaType() { return screenshotMediaType; }
	int getScreenshotWidth() { return screenshotWidth; }
	int getScreenshotHeight() { return screenshotHeight; }
	int getScreenshotByteLength() { return screenshotByteLength; }
	String getScreenshotSha256() { return screenshotSha256; }
	State getState() { return state; }
	boolean isSent() { return state == State.SENT; }
	boolean isIgnored() { return state == State.IGNORED; }
	boolean isResolved() { return state != State.PENDING; }
	boolean isAwaitingPreflight() { return state == State.PENDING && tilePosition == 0 && rawEventJson != null; }
	String getDeliveredAt() { return deliveredAt; }
	int getLastStatusCode() { return lastStatusCode; }
	String getRawEventJson() { return rawEventJson; }

	RareDropHistoryEntry asSent(Instant acceptedAt, int statusCode)
	{
		if (isSent()) return this;
		if (state != State.PENDING || acceptedAt == null || (statusCode != 200 && statusCode != 201))
			throw new IllegalArgumentException("Only an accepted delivery can be marked sent");
		return copy(tilePosition, State.SENT, acceptedAt.toString(), statusCode, tokenFingerprint);
	}

	RareDropHistoryEntry asIgnored(Instant resolvedAt, int statusCode)
	{
		if (isIgnored()) return this;
		if (state != State.PENDING || resolvedAt == null || (statusCode != 200 && statusCode != 201))
			throw new IllegalArgumentException("Only a successful no-match check can be ignored");
		return copy(tilePosition, State.IGNORED, resolvedAt.toString(), statusCode, tokenFingerprint);
	}

	RareDropHistoryEntry withPendingStatus(int statusCode)
	{
		if (isResolved()) return this;
		if (statusCode < 0 || statusCode > 599 || statusCode == 200 || statusCode == 201)
			throw new IllegalArgumentException("Invalid pending delivery status");
		return copy(tilePosition, State.PENDING, null, statusCode, tokenFingerprint);
	}

	RareDropHistoryEntry withTokenFingerprint(String nextTokenFingerprint)
	{
		return copy(tilePosition, state, deliveredAt, lastStatusCode, nextTokenFingerprint);
	}

	RareDropHistoryEntry withTilePosition(int nextTilePosition)
	{
		if (state != State.PENDING || rawEventJson == null || nextTilePosition < 1 || nextTilePosition > 25)
			throw new IllegalStateException("Only a pending raw event can bind to a matched tile");
		return copy(nextTilePosition, state, deliveredAt, lastStatusCode, tokenFingerprint);
	}

	boolean hasSameImmutableRequest(RareDropHistoryEntry other)
	{
		return other != null
			&& eventId.equals(other.eventId)
			&& occurredAt.equals(other.occurredAt)
			&& username.equals(other.username)
			&& itemDrop.equals(other.itemDrop)
			&& Objects.equals(eventType, other.eventType)
			&& Objects.equals(sourceNpc, other.sourceNpc)
			&& markComplete == other.markComplete
			&& Objects.equals(rawEventJson, other.rawEventJson)
			&& endpoint.equals(other.endpoint)
			&& tokenFingerprint.equals(other.tokenFingerprint)
			&& screenshotMediaType.equals(other.screenshotMediaType)
			&& screenshotWidth == other.screenshotWidth
			&& screenshotHeight == other.screenshotHeight
			&& screenshotByteLength == other.screenshotByteLength
			&& screenshotSha256.equals(other.screenshotSha256);
	}

	private RareDropHistoryEntry copy(int nextTilePosition, State nextState, String nextDeliveredAt,
		int nextStatusCode, String nextTokenFingerprint)
	{
		return new RareDropHistoryEntry(storageId, eventId, occurredAt, savedAt, username,
			itemDrop, eventType, sourceNpc, nextTilePosition, markComplete, endpoint,
			nextTokenFingerprint, screenshotMediaType, screenshotWidth, screenshotHeight,
			screenshotByteLength, screenshotSha256, nextState, nextDeliveredAt,
			nextStatusCode, rawEventJson);
	}

	private static boolean isInstant(String value)
	{
		try { if (value == null) return false; Instant.parse(value); return true; }
		catch (RuntimeException ignored) { return false; }
	}

	private static String normalizeEventType(String value)
	{
		RareDropEventType type = RareDropEventType.fromWireValue(value);
		return type == null ? null : type.getWireValue();
	}

	private static String normalizeSourceNpc(String value)
	{
		if (value == null || value.trim().isEmpty()) return null;
		String normalized = value.trim();
		if (normalized.length() > RareDropSubmission.MAX_SOURCE_NPC_LENGTH)
			throw new IllegalArgumentException("Invalid rare-drop NPC source");
		return normalized;
	}
}

