	/** Updates the controls from a validated, locally persisted configuration snapshot. */
	void setDiscordWebhookState(boolean enabled, String webhookUrl)
	{
		String value = webhookUrl == null ? "" : webhookUrl.trim();
		runOnEdt(() ->
		{
			updatingDiscordControls = true;
			try
			{
				discordWebhookSaved = !value.isEmpty();
				discordEnabledInput.setSelected(enabled && discordWebhookSaved);
				discordWebhookInput.setText(value);
			}
			finally
			{
				updatingDiscordControls = false;
			}
			if (discordWebhookSaved) showDiscordWebhookSavedStatus();
			else showDiscordWebhookEmptyStatus();
			if (settingsOpen && !discordSectionExpanded) rebuild();
		});
	}

