	void setEntries(List<RareDropHistoryEntry> entries)
	{
		setEntries(entries, entries == null ? 0 : entries.size());
	}

	void setEntries(List<RareDropHistoryEntry> entries, int totalCount)
	{
		List<RareDropHistoryEntry> snapshot = entries == null
			? Collections.emptyList()
			: new ArrayList<>(entries);
		List<RowModel> rowModels = new ArrayList<>(snapshot.size());
		for (RareDropHistoryEntry entry : snapshot)
		{
			if (entry != null)
			{
				rowModels.add(RowModel.from(entry));
			}
		}
		rowModels.sort(RareDropHistoryPanel::latestFirst);
		List<RowModel> immutableRows = Collections.unmodifiableList(rowModels);
		int safeTotalCount = Math.max(immutableRows.size(), totalCount);

		runOnEdt(() ->
		{
			rows = immutableRows;
			this.totalCount = safeTotalCount;
			Set<String> visibleIds = new HashSet<>();
			for (RowModel row : rows)
			{
				visibleIds.add(row.eventId);
				if (row.sent || row.ignored)
				{
					attempts.remove(row.eventId);
				}
			}
			attempts.keySet().retainAll(visibleIds);
			thumbnails.keySet().retainAll(visibleIds);
			rebuild();
		});
	}

	void clearTransientState()
	{
		runOnEdt(() ->
		{
