			rebuild();
		});
	}

	void setThumbnail(String eventId, RareDropScreenshot screenshot)
	{
		if (eventId == null || eventId.trim().isEmpty())
		{
			return;
		}
		BufferedImage decodedThumbnail = thumbnail(screenshot);
		runOnEdt(() ->
		{
			if (rows.stream().noneMatch(row -> row.eventId.equals(eventId)))
			{
				return;
			}
			if (decodedThumbnail == null)
			{
				thumbnails.remove(eventId);
			}
			else
			{
				thumbnails.put(eventId, decodedThumbnail);
			}
			applyThumbnail(eventId, decodedThumbnail);
		});
	}

	void markSending(String eventId)
	{
		updateAttempt(eventId, Attempt.sending());
	}

	void markFailed(String eventId, int statusCode)
	{
		updateAttempt(eventId, Attempt.failed(statusCode));
	}

	void resetAttempt(String eventId)
	{
		if (eventId == null)
		{
			return;
		}
		runOnEdt(() ->
		{
			attempts.remove(eventId);
			rebuild();
		});
	}

	private void updateAttempt(String eventId, Attempt attempt)
	{
		if (eventId == null || eventId.trim().isEmpty())
		{
			return;
		}
		runOnEdt(() ->
		{
			attempts.put(eventId, attempt);
			rebuild();
		});
	}

	private void rebuild()
	{
		assert SwingUtilities.isEventDispatchThread();
		removeAll();
		if (!settingsOpen)
		{
			add(dashboardPanel);
		}
		else
		{
			rebuildingSettings = true;
			try
			{
				add(buildSettingsHeader());
				add(Box.createVerticalStrut(6));
				add(buildPairingCard());
				add(Box.createVerticalStrut(6));
				add(buildDiscordWebhookCard());
				add(Box.createVerticalStrut(6));
				add(buildBingoSettingsCard());
				add(Box.createVerticalStrut(8));
				add(buildHeader());
				if (historySectionExpanded && rows.isEmpty())
				{
					add(buildEmptyState());
				}
				else if (historySectionExpanded)
				{
					for (int index = 0; index < rows.size(); index++)
					{
						if (index > 0) add(Box.createVerticalStrut(5));
						add(buildRow(rows.get(index)));
					}
				}
			}
			finally
			{
				rebuildingSettings = false;
			}
		}
		revalidate();
		repaint();
	}

