		back.setName("bingo-settings-back");
		back.setToolTipText("Back to event board");
		back.setText("Back");
		back.setPreferredSize(new Dimension(45, 24));
		back.setMinimumSize(new Dimension(45, 24));
		back.setMaximumSize(new Dimension(45, 24));
		back.setMargin(new java.awt.Insets(0, 4, 0, 4));
