	private JPanel buildAccordionHeader(
		String buttonName,
		String heading,
		boolean expanded,
		Runnable toggleHandler,
		Component trailing)
	{
		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 25));

		JButton toggle = new JButton((expanded ? "▾ " : "▸ ") + heading);
		toggle.setName(buttonName);
		toggle.setHorizontalAlignment(SwingConstants.LEFT);
		toggle.setMargin(new java.awt.Insets(0, 0, 0, 0));
		toggle.setContentAreaFilled(false);
		toggle.setBorderPainted(false);
		toggle.setFocusPainted(true);
		toggle.setForeground(Color.WHITE);
		toggle.setFont(toggle.getFont().deriveFont(Font.BOLD));
		toggle.putClientProperty("expanded", expanded);
		toggle.setToolTipText((expanded ? "Collapse " : "Expand ") + heading);
		toggle.getAccessibleContext().setAccessibleName(heading + " section");
		toggle.getAccessibleContext().setAccessibleDescription(
			(expanded ? "Expanded. Activate to collapse the " : "Collapsed. Activate to expand the ")
				+ heading + " section.");
		toggle.addActionListener(event ->
		{
			toggleHandler.run();
			rebuild();
		});
		header.add(toggle, BorderLayout.WEST);
		if (trailing != null) header.add(trailing, BorderLayout.EAST);
		return header;
	}

	private JPanel buildDiscordWebhookCard()
	{
		JPanel card = new JPanel();
		card.setName("discord-webhook-settings");
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR),
			new EmptyBorder(7, 7, 7, 7)));
		card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, Integer.MAX_VALUE));

		JLabel collapsedSaved = null;
		if (!discordSectionExpanded && discordWebhookSaved)
		{
			collapsedSaved = new JLabel("✓");
			collapsedSaved.setName("settings-discord-collapsed-saved");
			collapsedSaved.setForeground(READY_GREEN);
			collapsedSaved.setToolTipText("Discord webhook saved");
			collapsedSaved.getAccessibleContext().setAccessibleName("Discord webhook saved");
		}
		card.add(buildAccordionHeader(
			"settings-discord-toggle",
			"Discord Webhook",
			discordSectionExpanded,
			() -> discordSectionExpanded = !discordSectionExpanded,
			collapsedSaved));
		if (!discordSectionExpanded) return card;
		card.add(Box.createVerticalStrut(4));
		card.add(discordEnabledInput);
		card.add(Box.createVerticalStrut(5));

		JLabel webhookLabel = new JLabel("Webhook URL");
		webhookLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		webhookLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		webhookLabel.setLabelFor(discordWebhookInput);
		card.add(webhookLabel);
		card.add(Box.createVerticalStrut(2));
		discordWebhookInput.setAlignmentX(Component.LEFT_ALIGNMENT);
		discordWebhookInput.setMaximumSize(new Dimension(THUMBNAIL_WIDTH, 26));
		card.add(discordWebhookInput);
		card.add(Box.createVerticalStrut(3));
		card.add(discordWebhookStatus);

		String disclosure = "Discord receives your IP address, character name, and metadata for matching "
			+ "filtered drops. It also receives an annotated game-view screenshot when capture succeeds; "
			+ "otherwise the message contains metadata only. Enabled rules are OR: any match sends the drop.";
		JLabel privacy = new JLabel("<html><div style='width:160px'>"
			+ html(disclosure) + "</div></html>");
		privacy.setName("settings-discord-disclosure");
		privacy.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		privacy.setAlignmentX(Component.LEFT_ALIGNMENT);
