	private void scheduleDiscordWebhookSave()
	{
		assert SwingUtilities.isEventDispatchThread();
		if (updatingDiscordControls || discordWebhookSaveScheduled) return;
		discordWebhookSaveScheduled = true;
		SwingUtilities.invokeLater(() ->
		{
			discordWebhookSaveScheduled = false;
			if (!updatingDiscordControls) saveDiscordWebhook();
		});
	}

	private void saveDiscordWebhook()
	{
		assert SwingUtilities.isEventDispatchThread();
		String value = new String(discordWebhookInput.getPassword()).trim();
		boolean persisted = false;
		try
		{
			// The handler also receives blank or invalid drafts so it can clear any older URL.
			persisted = discordWebhookHandler.test(value);
		}
		catch (RuntimeException ignored)
		{
			// The status below keeps a failed local persistence attempt visible and inactive.
		}
		if (!value.isEmpty() && persisted)
		{
			discordWebhookSaved = true;
			if (!value.equals(new String(discordWebhookInput.getPassword())))
			{
				updatingDiscordControls = true;
				try { discordWebhookInput.setText(value); }
				finally { updatingDiscordControls = false; }
			}
			showDiscordWebhookSavedStatus();
			return;
		}

		discordWebhookSaved = false;
		disableDiscordWebhook();
		if (value.isEmpty()) showDiscordWebhookEmptyStatus();
		else showDiscordWebhookInvalidStatus();
	}

	private void updateDiscordEnabled()
	{
		assert SwingUtilities.isEventDispatchThread();
		if (updatingDiscordControls) return;
		if (discordEnabledInput.isSelected() && !discordWebhookSaved)
		{
			disableDiscordWebhook();
			showDiscordWebhookNeedsSavedStatus();
			return;
		}
		if (discordEnabledInput.isSelected())
		{
			boolean confirmed = false;
			try { confirmed = discordEnableConfirmationHandler.confirm(this); }
			catch (RuntimeException ignored) { }
			if (!confirmed)
			{
				updatingDiscordControls = true;
				try { discordEnabledInput.setSelected(false); }
				finally { updatingDiscordControls = false; }
				return;
			}
		}
		discordEnabledHandler.accept(discordEnabledInput.isSelected());
	}

	private void disableDiscordWebhook()
	{
		assert SwingUtilities.isEventDispatchThread();
		updatingDiscordControls = true;
		try { discordEnabledInput.setSelected(false); }
		finally { updatingDiscordControls = false; }
		discordEnabledHandler.accept(false);
	}

