	private void scheduleDiscordFilterSave()
	{
		assert SwingUtilities.isEventDispatchThread();
		if (updatingDiscordFilterControls || discordFilterSaveScheduled) return;
		discordFilterSaveScheduled = true;
		SwingUtilities.invokeLater(() ->
		{
			discordFilterSaveScheduled = false;
			if (!updatingDiscordFilterControls) saveDiscordFilter();
		});
	}

	private void saveDiscordFilter()
	{
		assert SwingUtilities.isEventDispatchThread();
		DiscordDropFilter filter = currentDiscordFilter();
		if (filter == null)
		{
			showDiscordFilterValidationStatus();
			return;
		}

		boolean saved = false;
		try { saved = discordFilterHandler.test(filter); }
		catch (RuntimeException ignored) { }
		if (!saved)
		{
			setDiscordFilterStatus("Rules not saved", WARNING_AMBER, "Rules not saved");
			return;
		}

		applyDiscordFilterControls(filter);
		showDiscordFilterSavedStatus();
	}

	private DiscordDropFilter currentDiscordFilter()
	{
		String minimumText = discordMinimumValueInput.getText() == null
			? "" : discordMinimumValueInput.getText().trim();
		long minimumValue;
		try
		{
			minimumValue = minimumText.isEmpty() ? 0L : Long.parseLong(minimumText);
		}
		catch (NumberFormatException exception)
		{
			return null;
		}
		try
		{
			return DiscordDropFilter.of(
				discordMinimumValueEnabledInput.isSelected(),
				minimumValue,
				discordUniqueItemsEnabledInput.isSelected(),
				discordUniqueItemIdsInput.getText(),
				discordPetsEnabledInput.isSelected());
		}
		catch (RuntimeException exception)
		{
			return null;
		}
	}

	private void applyDiscordFilterControls(DiscordDropFilter filter)
	{
		assert SwingUtilities.isEventDispatchThread();
		updatingDiscordFilterControls = true;
		try
		{
			discordMinimumValueEnabledInput.setSelected(filter.isMinimumValueEnabled());
			discordMinimumValueInput.setText(Long.toString(filter.getMinimumStackValue()));
			discordUniqueItemsEnabledInput.setSelected(filter.isUniqueItemsEnabled());
			discordUniqueItemIdsInput.setText(filter.getUniqueItemIdsText());
			discordPetsEnabledInput.setSelected(filter.isPetsEnabled());
		}
		finally
		{
			updatingDiscordFilterControls = false;
		}
	}

