			? "Untitled event" : competition.name.trim();
		String teamName = competition.teamName == null || competition.teamName.trim().isEmpty()
			? "Team" : competition.teamName.trim();
		boolean active = competition.id != null && competition.id.equals(selectedCompetitionId);

		JPanel row = new JPanel(new BorderLayout(5, 0));
		row.setName("settings-event-row-" + competition.id);
