		select.setName("settings-event-select-" + competition.id);
		select.setOpaque(false);
		select.setSelected(active);
		select.setEnabled(!bingoLoading);
		select.setToolTipText(active ? "Active board" : "Select this event's board");
		select.getAccessibleContext().setAccessibleName(
			active ? "Active board: " + eventName : "Select " + eventName + " as the active board");
