		eventSelection.add(select);
		row.add(select, BorderLayout.WEST);

		JLabel details = new JLabel("<html><div style='width:150px'><b>" + html(eventName)
			+ "</b><br><font color='#a8a8a8'>" + html(teamName) + " &middot; "
			+ competition.completedCount + "/" + competition.tileCount + " tiles</font></div></html>");
		details.setName("settings-event-details-" + competition.id);
		details.setForeground(Color.WHITE);
		details.getAccessibleContext().setAccessibleName(eventName + ", " + teamName + ", "
			+ competition.completedCount + " of " + competition.tileCount + " tiles complete");
		row.add(details, BorderLayout.CENTER);
		return row;
	}

	private void selectEventCompetition(BingoSidebarData.CompetitionSummary selected)
	{
		assert SwingUtilities.isEventDispatchThread();
		if (rebuildingSettings || selected == null || selected.id == null
			|| selected.id.equals(selectedCompetitionId)) return;
		selectedCompetitionId = selected.id;
		bingoLoading = true;
		bingoStatus = "Loading selected event…";
		dashboardPanel.setCatalog(bingoCatalog, selected.id);
		rebuild();
		selectCompetitionHandler.accept(selected.id);
	}

	private void submitJoinCode()
	{
		assert SwingUtilities.isEventDispatchThread();
		String code = normalizeJoinCode(joinCodeInput.getText());
		if (code.length() < MIN_JOIN_CODE_LENGTH || code.length() > MAX_JOIN_CODE_LENGTH)
		{
			bingoLoading = false;
			bingoStatus = "Join codes use 4–16 letters or numbers.";
			rebuild();
			return;
		}
		joinCodeInput.setText(code);
		bingoLoading = true;
		bingoStatus = "Joining event…";
		rebuild();
		joinBingoHandler.accept(code);
	}

