			JButton pair = new JButton("Pair this character");
			pair.setName("pair-start");
			pair.setEnabled(pairingState != PairingState.STARTING);
			pair.addActionListener(event -> pairHandler.run());
			pair.setToolTipText("Pair the currently logged-in RuneScape character");
			actions.add(pair);
		}
		card.add(actions);
		return card;
