		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR),
			new EmptyBorder(7, 7, 7, 7)));
		header.setMaximumSize(new Dimension(
			PluginPanel.PANEL_WIDTH, historySectionExpanded ? 72 : 42));

		JLabel count = new JLabel(rows.size() + "/" + totalCount);
		count.setName("settings-history-count");
		count.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		count.getAccessibleContext().setAccessibleName(
			rows.size() + " of " + totalCount + " drop history events loaded");
		header.add(buildAccordionHeader(
			"settings-history-toggle",
			"Drop history",
			historySectionExpanded,
			() -> historySectionExpanded = !historySectionExpanded,
			count));
		if (!historySectionExpanded) return header;

		JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
		actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		actions.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));
		int remaining = Math.max(0, totalCount - rows.size());
		if (remaining > 0)
		{
			JButton olderButton = new JButton("More (" + remaining + ")");
			olderButton.setName("load-older");
			olderButton.setToolTipText("Load up to 25 older local drops");
			olderButton.getAccessibleContext().setAccessibleName(
				"Load older drop history, " + remaining + " remaining");
			olderButton.addActionListener(event -> loadOlderHandler.run());
			actions.add(olderButton);
		}

		long resolvedCount = rows.stream().filter(row -> row.sent || row.ignored).count();
		JButton clearButton = new JButton(resolvedCount == 0 ? "Clear" : "Clear (" + resolvedCount + ")");
		clearButton.setName("clear-sent");
		clearButton.setEnabled(resolvedCount > 0);
		clearButton.setToolTipText("Remove delivered and no-longer-needed events from local history");
		clearButton.getAccessibleContext().setAccessibleName(
			"Clear " + resolvedCount + " resolved drop history events");
		clearButton.addActionListener(event ->
		{
			if (confirmationHandler.confirm(this))
			{
				clearSentHandler.run();
			}
		});
		actions.add(clearButton);
		header.add(actions);
		return header;
	}

