		JLabel status = new JLabel(statusText(row, state, attempt));
		status.setName("history-status-" + row.eventId);
		status.setForeground(statusColor(state));
		status.getAccessibleContext().setAccessibleName("Upload status: " + status.getText());
		footer.add(status, BorderLayout.CENTER);

		JButton pushButton = new JButton(buttonText(state));
		pushButton.setName("history-push-" + row.eventId);
		pushButton.setToolTipText(buttonTooltip(row, state, attempt));
