	private void applyThumbnail(String eventId, BufferedImage image)
	{
		assert SwingUtilities.isEventDispatchThread();
		Component component = findNamed(this, "history-thumbnail-" + eventId);
		if (!(component instanceof JLabel))
		{
			return;
		}
		JLabel label = (JLabel) component;
		label.setText(image == null ? "Screenshot unavailable" : null);
		label.setIcon(image == null ? null : new ImageIcon(image));
		label.setToolTipText(image == null ? null : "Captured evidence screenshot");
		label.revalidate();
		label.repaint();
	}

	private static Component findNamed(Container container, String name)
	{
		for (Component component : container.getComponents())
		{
			if (name.equals(component.getName()))
			{
				return component;
			}
			if (component instanceof Container)
			{
				Component found = findNamed((Container) component, name);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private void push(String eventId)
	{
		assert SwingUtilities.isEventDispatchThread();
		attempts.put(eventId, Attempt.sending());
		rebuild();
		try
		{
			pushHandler.accept(eventId);
		}
		catch (RuntimeException exception)
		{
			attempts.put(eventId, Attempt.failed(0));
			rebuild();
		}
	}

	private static DisplayState displayState(RowModel row, Attempt attempt)
	{
		if (row.sent)
		{
			return DisplayState.SENT;
		}
		if (row.ignored)
		{
			return DisplayState.IGNORED;
		}
		if (attempt != null)
		{
			return attempt.sending ? DisplayState.SENDING : DisplayState.FAILED;
		}
		return row.lastStatusCode > 0 ? DisplayState.FAILED : DisplayState.PENDING;
	}

	private static String statusText(RowModel row, DisplayState state, Attempt attempt)
	{
		switch (state)
		{
			case SENT:
				return row.lastStatusCode > 0 ? "Sent · HTTP " + row.lastStatusCode : "Sent";
			case IGNORED:
				return "Checked · no matching tile";
			case SENDING:
				return "Sending…";
			case FAILED:
				int statusCode = attempt != null ? attempt.statusCode : row.lastStatusCode;
				return statusCode > 0 ? "Failed · HTTP " + statusCode : "Failed · retry available";
			case PENDING:
			default:
				return row.awaitingPreflight ? "Saved during outage · Push to check" : "Pending upload";
		}
	}

	private static Color statusColor(DisplayState state)
	{
		switch (state)
		{
			case SENT:
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
			case IGNORED:
				return ColorScheme.LIGHT_GRAY_COLOR;
			case FAILED:
				return GOLD;
			case SENDING:
			case PENDING:
			default:
				return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}

	private static String buttonText(DisplayState state)
	{
		switch (state)
		{
			case SENT:
				return "✓";
			case IGNORED:
				return "—";
			case SENDING:
				return "Sending…";
			case FAILED:
			case PENDING:
			default:
				return "Push";
		}
	}

	private static String buttonTooltip(RowModel row, DisplayState state, Attempt attempt)
	{
		switch (state)
		{
			case SENT:
				return "Server accepted event " + row.eventId;
			case IGNORED:
				return "The server confirmed that no active bingo tile needs this event";
			case SENDING:
				return "Upload is in progress";
			case FAILED:
				int statusCode = attempt != null ? attempt.statusCode : row.lastStatusCode;
				return statusCode > 0
					? "Retry event " + row.eventId + " after HTTP " + statusCode
					: "Retry event " + row.eventId;
			case PENDING:
			default:
				return "Push event " + row.eventId + " to Exodus Bingo";
		}
	}

	private static void styleButton(JButton button, DisplayState state)
	{
		button.setFocusPainted(false);
		button.setOpaque(true);
		switch (state)
		{
			case SENT:
				button.setEnabled(false);
				button.setBackground(ColorScheme.PROGRESS_COMPLETE_COLOR);
				button.setForeground(Color.WHITE);
				break;
			case IGNORED:
				button.setEnabled(false);
				button.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
				button.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				break;
			case SENDING:
				button.setEnabled(false);
				button.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
				button.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				break;
			case FAILED:
			case PENDING:
			default:
				button.setEnabled(true);
				button.setBackground(GOLD);
				button.setForeground(Color.BLACK);
				break;
		}
	}

	private static int latestFirst(RowModel left, RowModel right)
	{
		if (left.sortTime == null && right.sortTime == null)
		{
			return right.eventId.compareTo(left.eventId);
		}
		if (left.sortTime == null)
		{
			return 1;
		}
		if (right.sortTime == null)
		{
			return -1;
		}
		int compared = right.sortTime.compareTo(left.sortTime);
		return compared == 0 ? right.eventId.compareTo(left.eventId) : compared;
	}

	private static BufferedImage thumbnail(RareDropScreenshot screenshot)
	{
		if (screenshot == null)
		{
			return null;
		}
		BufferedImage source;
		try (ByteArrayInputStream input = new ByteArrayInputStream(screenshot.copyData()))
		{
			source = ImageIO.read(input);
		}
		catch (IOException | RuntimeException exception)
		{
			return null;
		}
		if (source == null || source.getWidth() <= 0 || source.getHeight() <= 0)
		{
			return null;
		}

		double scale = Math.min(
			(double) THUMBNAIL_WIDTH / source.getWidth(),
			(double) THUMBNAIL_HEIGHT / source.getHeight());
		int width = Math.max(1, (int) Math.round(source.getWidth() * scale));
		int height = Math.max(1, (int) Math.round(source.getHeight() * scale));
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = scaled.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			graphics.drawImage(source, 0, 0, width, height, null);
		}
		finally
		{
			graphics.dispose();
		}
		return scaled;
	}

	private static Instant parseInstant(String value)
	{
		try
		{
			return value == null ? null : Instant.parse(value);
		}
		catch (DateTimeParseException ignored)
		{
			return null;
		}
	}

	private static String displayTime(String value)
	{
		Instant instant = parseInstant(value);
		return instant == null ? (value == null ? "Time unavailable" : value) : DISPLAY_TIME.format(instant);
	}

	private static String eventTypeDisplay(String value)
	{
		try
		{
			RareDropEventType type = RareDropEventType.fromWireValue(value);
			return type == null ? "Legacy drop" : type.getDisplayName();
		}
		catch (IllegalArgumentException ignored)
		{
			return "Drop event";
		}
	}

	private static String resolveCompetitionId(BingoSidebarData.Catalog catalog, String preferred)
	{
		if (containsCompetition(catalog, preferred)) return preferred;
		if (catalog != null && containsCompetition(catalog, catalog.defaultCompetitionId))
			return catalog.defaultCompetitionId;
		return catalog == null || catalog.competitions.isEmpty() ? null : catalog.competitions.get(0).id;
	}

	private static boolean containsCompetition(BingoSidebarData.Catalog catalog, String competitionId)
	{
		if (catalog == null || competitionId == null) return false;
		for (BingoSidebarData.CompetitionSummary competition : catalog.competitions)
		{
			if (competitionId.equals(competition.id)) return true;
		}
		return false;
	}

	private static String normalizeJoinCode(String value)
	{
		return value == null ? "" : value.trim().toUpperCase(java.util.Locale.ROOT)
			.replaceAll("[^A-Z0-9]", "");
	}

	private static String shorten(String value, int maximumLength)
	{
		if (value == null) return "";
		String normalized = value.trim();
		return normalized.length() <= maximumLength
			? normalized : normalized.substring(0, Math.max(1, maximumLength - 1)) + "…";
	}

