/**
 * Durable filesystem outbox for immutable RuneLite bingo submissions.
 *
 * <p>Screenshot bytes are stored separately from the small mutable metadata so
 * marking a delivery successful never rewrites or re-encodes its evidence.</p>
 */
final class RareDropHistoryStore
{
	private static final String SCHEMA_VERSION = "2";
	private static final String LEGACY_SCHEMA_VERSION = "1";
	private static final String METADATA_SUFFIX = ".properties";
	private static final String SCREENSHOT_SUFFIX = ".jpg";
	private static final int MAX_METADATA_BYTES = 64 * 1024;
	static final int MAX_PENDING_ENTRIES = 100;
	static final long MAX_PENDING_SCREENSHOT_BYTES = 64L * 1024L * 1024L;
	static final Duration MAX_PENDING_AGE = Duration.ofDays(30);
	static final long CLEANUP_GRACE_MILLIS = Duration.ofMinutes(10).toMillis();
	private static final String LOCK_FILE_NAME = ".history.lock";
	private static final ConcurrentMap<Path, ReentrantLock> JVM_ROOT_LOCKS = new ConcurrentHashMap<>();
	private static final ThreadLocal<Set<Path>> HELD_ROOTS = ThreadLocal.withInitial(HashSet::new);

	private final Path root;
	private final int maximumPendingEntries;
	private final long maximumPendingScreenshotBytes;
	private final Duration maximumPendingAge;

	RareDropHistoryStore(Path root) throws IOException
	{
		this(root, MAX_PENDING_ENTRIES, MAX_PENDING_SCREENSHOT_BYTES, MAX_PENDING_AGE);
	}

	RareDropHistoryStore(
		Path root,
		int maximumPendingEntries,
		long maximumPendingScreenshotBytes,
		Duration maximumPendingAge) throws IOException
	{
		if (root == null)
		{
			throw new IllegalArgumentException("A history directory is required");
		}
		if (maximumPendingEntries <= 0)
		{
			throw new IllegalArgumentException("The pending-history count limit must be positive");
		}
		if (maximumPendingScreenshotBytes <= 0)
		{
			throw new IllegalArgumentException("The pending-history byte limit must be positive");
		}
		if (maximumPendingAge == null || maximumPendingAge.isZero() || maximumPendingAge.isNegative())
		{
			throw new IllegalArgumentException("The pending-history age limit must be positive");
		}
		this.root = root.toAbsolutePath().normalize();
		this.maximumPendingEntries = maximumPendingEntries;
		this.maximumPendingScreenshotBytes = maximumPendingScreenshotBytes;
		this.maximumPendingAge = maximumPendingAge;
		Files.createDirectories(this.root);
		if (!Files.isDirectory(this.root, LinkOption.NOFOLLOW_LINKS))
		{
			throw new IOException("The rare-drop history path is not a directory");
		}
		withRootLock(() ->
		{
			cleanupOrphansAndTemporaryFiles();
			enforcePendingRetentionLocked(Instant.now());
			return null;
		});
	}

	synchronized RareDropHistoryEntry savePending(
		String endpoint,
		String bearerToken,
		RareDropSubmission submission) throws IOException
	{
		return withRootLock(() -> savePendingLocked(endpoint, bearerToken, submission));
	}

	private RareDropHistoryEntry savePendingLocked(
		String endpoint,
		String bearerToken,
		RareDropSubmission submission) throws IOException
	{
		if (submission == null)
		{
			throw new IllegalArgumentException("A bingo drop submission is required");
		}
		if (submission.getScreenshot().getByteLength() > maximumPendingScreenshotBytes)
		{
			throw new IOException("The screenshot is larger than the offline evidence queue limit");
		}
		enforcePendingRetentionLocked(Instant.now());
		String normalizedEndpoint = requireText(endpoint, "endpoint", 2_048);
		String fingerprint = tokenFingerprint(bearerToken);
		String storageId = sha256(submission.getEventId().getBytes(StandardCharsets.UTF_8));
		Path metadataPath = metadataPath(storageId);
		Path screenshotPath = screenshotPath(storageId);

		if (Files.exists(metadataPath, LinkOption.NOFOLLOW_LINKS))
		{
			RareDropHistoryEntry existing = readEntry(metadataPath);
			if (existing == null)
			{
				throw new IOException("Existing rare-drop history metadata is invalid");
			}
			RareDropHistoryEntry candidate = pendingEntry(
				storageId,
				normalizedEndpoint,
				fingerprint,
				submission,
				existing.getSavedAt());
			if (!existing.hasSameImmutableRequest(candidate))
			{
				throw new IOException("That rare-drop event ID is already stored with different data");
			}
			// Verify that a same-length local modification has not silently changed
			// the immutable evidence before treating this as an exact duplicate.
			loadScreenshot(existing.getEventId());
			return existing;
		}

		RareDropHistoryEntry entry = pendingEntry(
			storageId,
			normalizedEndpoint,
			fingerprint,
			submission,
			Instant.now().toString());
		writeBytesAtomically(screenshotPath, submission.getScreenshot().copyData());
		try
		{
			writeMetadataAtomically(entry);
		}
		catch (IOException exception)
		{
			// A screenshot without metadata is never loaded or uploaded. Best-effort
			// cleanup avoids leaving a large orphan after a metadata failure.
			Files.deleteIfExists(screenshotPath);
			throw exception;
		}
		enforcePendingRetentionLocked(Instant.now());
		return entry;
	}

	synchronized List<RareDropHistoryEntry> list() throws IOException
	{
		return withRootLock(this::listLocked);
	}

	private List<RareDropHistoryEntry> listLocked() throws IOException
	{
		List<RareDropHistoryEntry> entries = new ArrayList<>();
		try (DirectoryStream<Path> stream = Files.newDirectoryStream(root, "*" + METADATA_SUFFIX))
		{
			for (Path metadataPath : stream)
			{
				RareDropHistoryEntry entry = readEntry(metadataPath);
				if (entry != null)
				{
					entries.add(entry);
				}
			}
		}
		entries.sort(Comparator
			.comparing((RareDropHistoryEntry entry) -> Instant.parse(entry.getSavedAt()))
			.reversed()
			.thenComparing(RareDropHistoryEntry::getEventId));
		return entries;
	}

	synchronized List<RareDropHistoryEntry> listLatest() throws IOException
	{
		return withRootLock(this::listLocked);
	}

	synchronized Optional<RareDropHistoryEntry> find(String eventId) throws IOException
	{
		return withRootLock(() -> findLocked(eventId));
	}

	private Optional<RareDropHistoryEntry> findLocked(String eventId) throws IOException
	{
		String normalizedEventId = requireText(eventId, "event ID", 180);
		String storageId = sha256(normalizedEventId.getBytes(StandardCharsets.UTF_8));
		RareDropHistoryEntry entry = readEntry(metadataPath(storageId));
		if (entry == null || !normalizedEventId.equals(entry.getEventId()))
		{
			return Optional.empty();
		}
		return Optional.of(entry);
	}

	synchronized RareDropScreenshot loadScreenshot(String eventId) throws IOException
	{
		return withRootLock(() -> loadScreenshotLocked(eventId));
	}

	private RareDropScreenshot loadScreenshotLocked(String eventId) throws IOException
	{
		RareDropHistoryEntry entry = requireEntryLocked(eventId);
		Path screenshotPath = screenshotPath(entry.getStorageId());
		if (!Files.isRegularFile(screenshotPath, LinkOption.NOFOLLOW_LINKS)
			|| Files.size(screenshotPath) != entry.getScreenshotByteLength())
		{
			throw new IOException("Rare-drop screenshot is missing or has changed");
		}
		byte[] screenshotBytes = Files.readAllBytes(screenshotPath);
		if (!entry.getScreenshotSha256().equals(sha256(screenshotBytes)))
		{
			throw new IOException("Rare-drop screenshot integrity check failed");
		}
		return new RareDropScreenshot(
			entry.getScreenshotMediaType(),
			screenshotBytes,
			entry.getScreenshotWidth(),
			entry.getScreenshotHeight());
	}

	synchronized RareDropSubmission loadSubmission(String eventId) throws IOException
	{
		return withRootLock(() -> loadSubmissionLocked(eventId));
	}

	private RareDropSubmission loadSubmissionLocked(String eventId) throws IOException
	{
		RareDropHistoryEntry entry = requireEntryLocked(eventId);
		RareDropReport rawReport = entry.getRawEventJson() == null
			? null
			: decodeRawReport(entry);
		return new RareDropSubmission(
			entry.getEventId(),
			entry.getOccurredAt(),
			entry.getUsername(),
			entry.getItemDrop(),
			entry.getEventType(),
			entry.getSourceNpc(),
			entry.getTilePosition(),
			entry.isMarkComplete(),
			loadScreenshotLocked(eventId),
			rawReport);
	}

	synchronized RareDropReport loadRawReport(String eventId) throws IOException
	{
		return withRootLock(() -> decodeRawReport(requireEntryLocked(eventId)));
	}

	private RareDropReport decodeRawReport(RareDropHistoryEntry entry) throws IOException
	{
		try
		{
			RareDropReport report = RareDropRawEventCodec.decode(entry.getRawEventJson());
			if (!entry.getEventId().equals(report.getEventId()))
				throw new IOException("Saved raw event ID does not match its history entry");
			return report;
		}
		catch (IllegalArgumentException exception)
		{
			throw new IOException("Saved raw event metadata is invalid", exception);
		}
	}

	synchronized RareDropHistoryEntry markSent(
		String eventId,
		Instant deliveredAt,
		int statusCode) throws IOException
	{
		return withRootLock(() -> markSentLocked(eventId, deliveredAt, statusCode));
	}

	private RareDropHistoryEntry markSentLocked(
		String eventId,
		Instant deliveredAt,
		int statusCode) throws IOException
	{
		RareDropHistoryEntry existing = requireEntryLocked(eventId);
		RareDropHistoryEntry sent = existing.asSent(deliveredAt, statusCode);
		if (sent != existing)
		{
			writeMetadataAtomically(sent);
		}
		return sent;
	}

	synchronized RareDropHistoryEntry markIgnored(
		String eventId,
		Instant resolvedAt,
		int statusCode) throws IOException
	{
		return withRootLock(() ->
		{
			RareDropHistoryEntry ignored = requireEntryLocked(eventId).asIgnored(resolvedAt, statusCode);
			writeMetadataAtomically(ignored);
			return ignored;
		});
	}

	synchronized RareDropHistoryEntry bindMatch(String eventId, int tilePosition) throws IOException
	{
		return withRootLock(() ->
		{
			RareDropHistoryEntry existing = requireEntryLocked(eventId);
			RareDropHistoryEntry matched = existing.withTilePosition(tilePosition);
			writeMetadataAtomically(matched);
			return matched;
		});
	}

	synchronized RareDropHistoryEntry markPendingAttempt(String eventId, int statusCode) throws IOException
	{
		return withRootLock(() -> markPendingAttemptLocked(eventId, statusCode));
	}

	private RareDropHistoryEntry markPendingAttemptLocked(String eventId, int statusCode) throws IOException
	{
		RareDropHistoryEntry existing = requireEntryLocked(eventId);
		RareDropHistoryEntry pending = existing.withPendingStatus(statusCode);
		if (pending != existing && pending.getLastStatusCode() != existing.getLastStatusCode())
		{
			writeMetadataAtomically(pending);
		}
		return pending;
	}

	synchronized RareDropHistoryEntry markFailure(String eventId, int statusCode) throws IOException
	{
		return withRootLock(() -> markPendingAttemptLocked(eventId, statusCode));
	}

	synchronized RareDropHistoryEntry rebindRejectedToken(String eventId, String newBearerToken) throws IOException
	{
		return rebindDeviceToken(eventId, newBearerToken);
	}

	/** A device may be re-paired without changing an immutable raw event. */
	synchronized RareDropHistoryEntry rebindDeviceToken(String eventId, String newBearerToken) throws IOException
	{
		return withRootLock(() ->
		{
			RareDropHistoryEntry existing = requireEntryLocked(eventId);
			if (existing.isResolved() || existing.getState() != RareDropHistoryEntry.State.PENDING)
			{
				throw new IllegalStateException("Only a pending drop can change device credentials");
			}
			String nextFingerprint = tokenFingerprint(newBearerToken);
			if (nextFingerprint.equals(existing.getTokenFingerprint()))
			{
				return existing;
			}
			RareDropHistoryEntry rebound = existing.withTokenFingerprint(nextFingerprint);
			writeMetadataAtomically(rebound);
			return rebound;
		});
	}

	synchronized int clearSent() throws IOException
	{
		return withRootLock(this::clearSentLocked);
	}

	private int clearSentLocked() throws IOException
	{
		int removed = 0;
		for (RareDropHistoryEntry entry : listLocked())
		{
			if (entry.isResolved())
			{
				deleteEntry(entry);
				removed++;
			}
		}
		return removed;
	}

	synchronized int pruneOldestSent(int maximumSentEntries) throws IOException
	{
		return withRootLock(() -> pruneOldestSentLocked(maximumSentEntries));
	}

	private int pruneOldestSentLocked(int maximumSentEntries) throws IOException
	{
		if (maximumSentEntries < 0)
		{
			throw new IllegalArgumentException("The sent-history limit cannot be negative");
		}

		List<RareDropHistoryEntry> sentEntries = new ArrayList<>();
		for (RareDropHistoryEntry entry : listLocked())
		{
			if (entry.isResolved())
			{
				sentEntries.add(entry);
			}
		}
		sentEntries.sort(Comparator
			.comparing((RareDropHistoryEntry entry) -> Instant.parse(entry.getDeliveredAt()))
			.thenComparing(entry -> Instant.parse(entry.getSavedAt()))
			.thenComparing(RareDropHistoryEntry::getEventId));

		int removeCount = Math.max(0, sentEntries.size() - maximumSentEntries);
		for (int index = 0; index < removeCount; index++)
		{
			deleteEntry(sentEntries.get(index));
		}
		return removeCount;
	}

	/**
	 * Keeps only a bounded unresolved outbox. Resolved history is intentionally
	 * excluded because it has a separate user-visible retention policy.
	 */
	private void enforcePendingRetentionLocked(Instant now) throws IOException
	{
		List<RareDropHistoryEntry> pendingEntries = new ArrayList<>();
		long pendingScreenshotBytes = 0L;
		for (RareDropHistoryEntry entry : listLocked())
		{
			if (entry.getState() == RareDropHistoryEntry.State.PENDING)
			{
				pendingEntries.add(entry);
				pendingScreenshotBytes += entry.getScreenshotByteLength();
			}
		}

		pendingEntries.sort(Comparator
			.comparing((RareDropHistoryEntry entry) -> Instant.parse(entry.getSavedAt()))
			.thenComparing(RareDropHistoryEntry::getEventId));
		Instant oldestAllowed = now.minus(maximumPendingAge);
		int pendingCount = pendingEntries.size();
		for (RareDropHistoryEntry entry : pendingEntries)
		{
			boolean expired = !Instant.parse(entry.getSavedAt()).isAfter(oldestAllowed);
			boolean overCapacity = pendingCount > maximumPendingEntries
				|| pendingScreenshotBytes > maximumPendingScreenshotBytes;
			if (!expired && !overCapacity)
			{
				break;
			}

			deleteEntry(entry);
			pendingCount--;
			pendingScreenshotBytes -= entry.getScreenshotByteLength();
		}
	}

	static String tokenFingerprint(String bearerToken)
	{
		String token = requireText(bearerToken == null ? null : bearerToken.trim(), "bearer token", 4_096);
		return sha256(token.getBytes(StandardCharsets.UTF_8));
	}

	private <T> T withRootLock(LockedOperation<T> operation) throws IOException
	{
		Set<Path> heldRoots = HELD_ROOTS.get();
		if (heldRoots.contains(root))
		{
			return operation.run();
		}

		ReentrantLock jvmLock = JVM_ROOT_LOCKS.computeIfAbsent(root, ignored -> new ReentrantLock(true));
		jvmLock.lock();
		try
		{
			Path lockPath = root.resolve(LOCK_FILE_NAME).normalize();
			if (!lockPath.getParent().equals(root) || Files.isSymbolicLink(lockPath))
			{
				throw new IOException("Unsafe rare-drop history lock path");
			}
			try (FileChannel channel = FileChannel.open(
				lockPath,
				StandardOpenOption.CREATE,
				StandardOpenOption.WRITE);
				FileLock ignored = channel.lock())
			{
				heldRoots.add(root);
				try
				{
					return operation.run();
				}
				finally
				{
					heldRoots.remove(root);
					if (heldRoots.isEmpty())
					{
						HELD_ROOTS.remove();
					}
				}
			}
		}
		finally
		{
			if (heldRoots.isEmpty())
			{
				HELD_ROOTS.remove();
			}
			jvmLock.unlock();
		}
	}

	private void cleanupOrphansAndTemporaryFiles() throws IOException
	{
		long cutoff = System.currentTimeMillis() - CLEANUP_GRACE_MILLIS;
		boolean removedAny = false;
		try (DirectoryStream<Path> stream = Files.newDirectoryStream(root))
		{
			for (Path candidate : stream)
			{
				String fileName = candidate.getFileName().toString();
				boolean temporary = fileName.matches("\\.rare-drop-.+\\.tmp");
				boolean screenshot = fileName.matches("[a-f0-9]{64}\\.jpg");
				if ((!temporary && !screenshot)
					|| !Files.isRegularFile(candidate, LinkOption.NOFOLLOW_LINKS))
				{
					continue;
				}

				try
				{
					FileTime modified = Files.getLastModifiedTime(candidate, LinkOption.NOFOLLOW_LINKS);
					if (modified.toMillis() > cutoff)
					{
						continue;
					}
					if (screenshot)
					{
						String storageId = fileName.substring(0, 64);
						if (readEntry(metadataPath(storageId)) != null)
						{
							continue;
						}
					}
					Files.deleteIfExists(candidate);
					removedAny = true;
				}
				catch (IOException ignored)
				{
					// Cleanup is best-effort; an inaccessible file must not prevent
					// the remaining durable queue from opening.
				}
			}
		}
		if (removedAny)
		{
			forceRootDirectoryBestEffort();
		}
	}

	private RareDropHistoryEntry pendingEntry(
		String storageId,
		String endpoint,
		String fingerprint,
		RareDropSubmission submission,
		String savedAt)
	{
		RareDropScreenshot screenshot = submission.getScreenshot();
		String rawEventJson = RareDropRawEventCodec.encode(submission.getRawReport());
		return new RareDropHistoryEntry(
			storageId,
			submission.getEventId(),
			submission.getOccurredAt(),
			savedAt,
			submission.getUsername(),
			submission.getItemDrop(),
			submission.getEventType(),
			submission.getSourceNpc(),
			submission.getTilePosition(),
			submission.isMarkComplete(),
			endpoint,
			fingerprint,
			screenshot.getMediaType(),
			screenshot.getWidth(),
			screenshot.getHeight(),
			screenshot.getByteLength(),
			sha256(screenshot.copyData()),
			RareDropHistoryEntry.State.PENDING,
			null,
			0,
			rawEventJson);
	}

	private RareDropHistoryEntry requireEntryLocked(String eventId) throws IOException
	{
		return findLocked(eventId).orElseThrow(() -> new IOException("Rare-drop history entry was not found"));
	}

	private RareDropHistoryEntry readEntry(Path metadataPath)
	{
		try
		{
			if (metadataPath == null
				|| !metadataPath.toAbsolutePath().normalize().getParent().equals(root)
				|| !Files.isRegularFile(metadataPath, LinkOption.NOFOLLOW_LINKS)
				|| Files.size(metadataPath) <= 0
				|| Files.size(metadataPath) > MAX_METADATA_BYTES)
			{
				return null;
			}

			String fileName = metadataPath.getFileName().toString();
			if (!fileName.matches("[a-f0-9]{64}\\.properties"))
			{
				return null;
			}
			String storageId = fileName.substring(0, 64);
			Properties properties = new Properties();
			try (InputStream input = Files.newInputStream(metadataPath, StandardOpenOption.READ))
			{
				properties.load(input);
			}
			String schemaVersion = properties.getProperty("schemaVersion");
			if ((!SCHEMA_VERSION.equals(schemaVersion) && !LEGACY_SCHEMA_VERSION.equals(schemaVersion))
				|| !storageId.equals(properties.getProperty("storageId")))
			{
				return null;
			}

			String eventId = property(properties, "eventId");
			if (!storageId.equals(sha256(eventId.getBytes(StandardCharsets.UTF_8))))
			{
				return null;
			}
			String expectedScreenshotName = storageId + SCREENSHOT_SUFFIX;
			if (!expectedScreenshotName.equals(properties.getProperty("screenshotFile")))
			{
				return null;
			}
			Path screenshotPath = screenshotPath(storageId);
			if (!Files.isRegularFile(screenshotPath, LinkOption.NOFOLLOW_LINKS))
			{
				return null;
			}
			long screenshotLength = Files.size(screenshotPath);
			int expectedScreenshotLength = positiveInt(properties, "screenshotByteLength");
			if (screenshotLength <= 0
				|| screenshotLength > RareDropScreenshotEncoder.MAX_SCREENSHOT_BYTES
				|| screenshotLength != expectedScreenshotLength)
			{
				return null;
			}
			String screenshotSha256 = property(properties, "screenshotSha256");
			String deliveredAt = optionalProperty(properties, "deliveredAt");
			return new RareDropHistoryEntry(
				storageId,
				eventId,
				property(properties, "occurredAt"),
				property(properties, "savedAt"),
				property(properties, "username"),
				property(properties, "itemDrop"),
				optionalProperty(properties, "eventType"),
				optionalProperty(properties, "sourceNpc"),
				SCHEMA_VERSION.equals(schemaVersion)
					? nonNegativeInt(properties, "tilePosition")
					: positiveInt(properties, "tilePosition"),
				strictBoolean(properties, "markComplete"),
				property(properties, "endpoint"),
				property(properties, "tokenFingerprint"),
				property(properties, "mediaType"),
				positiveInt(properties, "screenshotWidth"),
				positiveInt(properties, "screenshotHeight"),
				expectedScreenshotLength,
				screenshotSha256,
				RareDropHistoryEntry.State.valueOf(property(properties, "state").toUpperCase(Locale.ROOT)),
				deliveredAt,
				nonNegativeInt(properties, "lastStatusCode"),
				SCHEMA_VERSION.equals(schemaVersion)
					? optionalProperty(properties, "rawEventJson")
					: null);
		}
		catch (IOException | RuntimeException ignored)
		{
			return null;
		}
	}

	private void writeMetadataAtomically(RareDropHistoryEntry entry) throws IOException
	{
		Properties properties = new Properties();
		properties.setProperty("schemaVersion", SCHEMA_VERSION);
		properties.setProperty("storageId", entry.getStorageId());
		properties.setProperty("eventId", entry.getEventId());
		properties.setProperty("occurredAt", entry.getOccurredAt());
		properties.setProperty("savedAt", entry.getSavedAt());
		properties.setProperty("username", entry.getUsername());
		properties.setProperty("itemDrop", entry.getItemDrop());
		if (entry.getEventType() != null)
		{
			properties.setProperty("eventType", entry.getEventType());
		}
		if (entry.getSourceNpc() != null)
		{
			properties.setProperty("sourceNpc", entry.getSourceNpc());
		}
		if (entry.getRawEventJson() != null)
		{
			properties.setProperty("rawEventJson", entry.getRawEventJson());
		}
		properties.setProperty("tilePosition", Integer.toString(entry.getTilePosition()));
		properties.setProperty("markComplete", Boolean.toString(entry.isMarkComplete()));
		properties.setProperty("endpoint", entry.getEndpoint());
		properties.setProperty("tokenFingerprint", entry.getTokenFingerprint());
		properties.setProperty("mediaType", entry.getScreenshotMediaType());
		properties.setProperty("screenshotFile", entry.getStorageId() + SCREENSHOT_SUFFIX);
		properties.setProperty("screenshotWidth", Integer.toString(entry.getScreenshotWidth()));
		properties.setProperty("screenshotHeight", Integer.toString(entry.getScreenshotHeight()));
		properties.setProperty("screenshotByteLength", Integer.toString(entry.getScreenshotByteLength()));
		properties.setProperty("screenshotSha256", entry.getScreenshotSha256());
		properties.setProperty("state", entry.getState().name());
		properties.setProperty("lastStatusCode", Integer.toString(entry.getLastStatusCode()));
		if (entry.getDeliveredAt() != null)
		{
			properties.setProperty("deliveredAt", entry.getDeliveredAt());
		}

		writeAtomically(metadataPath(entry.getStorageId()), output ->
			properties.store(output, "Exodus Bingo drop history v2"));
	}

	private void writeBytesAtomically(Path target, byte[] data) throws IOException
	{
		writeAtomically(target, output -> output.write(data));
	}

	private void writeAtomically(Path target, OutputWriter writer) throws IOException
	{
		if (!target.toAbsolutePath().normalize().getParent().equals(root))
		{
			throw new IOException("Unsafe rare-drop history path");
		}
		if (Files.isSymbolicLink(target))
		{
			throw new IOException("Refusing to replace a symbolic link in rare-drop history");
		}

		Path temporary = Files.createTempFile(root, ".rare-drop-", ".tmp");
		try
		{
			try (FileChannel channel = FileChannel.open(
				temporary,
				StandardOpenOption.WRITE,
				StandardOpenOption.TRUNCATE_EXISTING))
			{
				OutputStream output = Channels.newOutputStream(channel);
				writer.write(output);
				output.flush();
				channel.force(true);
			}
			try
			{
				Files.move(
					temporary,
					target,
					StandardCopyOption.ATOMIC_MOVE,
					StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException ignored)
			{
				Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
			}
			forceRootDirectoryBestEffort();
		}
		finally
		{
			Files.deleteIfExists(temporary);
		}
	}

	private void deleteEntry(RareDropHistoryEntry entry) throws IOException
	{
		Path metadata = metadataPath(entry.getStorageId());
		Path screenshot = screenshotPath(entry.getStorageId());
		if (Files.isSymbolicLink(metadata) || Files.isSymbolicLink(screenshot))
		{
			throw new IOException("Refusing to delete a symbolic link from rare-drop history");
		}
		// Metadata first: a crash can leave only an ignored orphan image, never a
		// visible history entry whose evidence has disappeared.
		Files.deleteIfExists(metadata);
		Files.deleteIfExists(screenshot);
		forceRootDirectoryBestEffort();
	}

	private void forceRootDirectoryBestEffort()
	{
		try (FileChannel directory = FileChannel.open(root, StandardOpenOption.READ))
		{
			directory.force(true);
		}
		catch (IOException | RuntimeException ignored)
		{
			// Windows and some filesystems do not allow opening a directory as a
			// channel. The individual file was still forced before its atomic move.
		}
	}

	private Path metadataPath(String storageId)
	{
		return safeChild(storageId + METADATA_SUFFIX);
	}

	private Path screenshotPath(String storageId)
	{
		return safeChild(storageId + SCREENSHOT_SUFFIX);
	}

	private Path safeChild(String fileName)
	{
		if (fileName == null || !fileName.matches("[a-f0-9]{64}\\.(?:properties|jpg)"))
		{
			throw new IllegalArgumentException("Invalid rare-drop history filename");
		}
		Path child = root.resolve(fileName).normalize();
		if (!child.getParent().equals(root))
		{
			throw new IllegalArgumentException("Unsafe rare-drop history path");
		}
		return child;
	}

	private static String property(Properties properties, String key)
	{
		String value = properties.getProperty(key);
		if (value == null || value.isEmpty())
		{
			throw new IllegalArgumentException("Missing history property: " + key);
		}
		return value;
	}

	private static String optionalProperty(Properties properties, String key)
	{
		String value = properties.getProperty(key);
		return value == null || value.isEmpty() ? null : value;
	}

	private static int positiveInt(Properties properties, String key)
	{
		int value = Integer.parseInt(property(properties, key));
		if (value <= 0)
		{
			throw new IllegalArgumentException("History property must be positive: " + key);
		}
		return value;
	}

	private static int nonNegativeInt(Properties properties, String key)
	{
		int value = Integer.parseInt(property(properties, key));
		if (value < 0)
		{
			throw new IllegalArgumentException("History property cannot be negative: " + key);
		}
		return value;
	}

	private static boolean strictBoolean(Properties properties, String key)
	{
		String value = property(properties, key);
		if (!"true".equalsIgnoreCase(value) && !"false".equalsIgnoreCase(value))
		{
			throw new IllegalArgumentException("History property must be a boolean: " + key);
		}
		return Boolean.parseBoolean(value);
	}

	private static String requireText(String value, String name, int maximumLength)
	{
		if (value == null || value.trim().isEmpty() || value.length() > maximumLength)
		{
			throw new IllegalArgumentException("A valid " + name + " is required");
		}
		return value.trim();
	}

	private static String sha256(byte[] value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(value);
			StringBuilder hex = new StringBuilder(digest.length * 2);
			for (byte part : digest)
			{
				hex.append(String.format(Locale.ROOT, "%02x", part & 0xff));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException impossible)
		{
			throw new IllegalStateException("SHA-256 is unavailable", impossible);
		}
	}

	@FunctionalInterface
	private interface OutputWriter
	{
		void write(OutputStream output) throws IOException;
	}

	@FunctionalInterface
	private interface LockedOperation<T>
	{
		T run() throws IOException;
	}
}

