package com.raredropping;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Keeps a small client-thread-only window of nearby NPC lifecycle activity for
 * best-effort pet source attribution. It never records player names.
 */
final class RareDropNpcSourceTracker
{
	private static final int MAX_OBSERVATIONS = 32;
	private static final int MAX_SOURCE_AGE_TICKS = 4;

	private final Deque<Observation> observations = new ArrayDeque<>();

	void recordSpawn(int npcId, String name, int combatLevel, int tick, boolean interactingWithLocalPlayer)
	{
		record(npcId, name, combatLevel, tick, interactingWithLocalPlayer, false);
	}

	void recordDespawn(int npcId, String name, int combatLevel, int tick, boolean interactingWithLocalPlayer)
	{
		record(npcId, name, combatLevel, tick, interactingWithLocalPlayer, true);
	}

	String findBestSource(int currentTick)
	{
		Observation best = null;
		for (Observation observation : observations)
		{
			int age = currentTick - observation.tick;
			if (age < 0 || age > MAX_SOURCE_AGE_TICKS)
			{
				continue;
			}
			if (best == null || observation.isBetterThan(best))
			{
				best = observation;
			}
		}
		prune(currentTick);
		return best == null ? null : best.name;
	}

	void reset()
	{
		observations.clear();
	}

	private void record(
		int npcId,
		String name,
		int combatLevel,
		int tick,
		boolean interactingWithLocalPlayer,
		boolean despawn)
	{
		String normalizedName = normalize(name);
		if (npcId < 0 || normalizedName == null)
		{
			return;
		}
		prune(tick);
		observations.addLast(new Observation(
			npcId,
			normalizedName,
			Math.max(0, combatLevel),
			tick,
			interactingWithLocalPlayer,
			despawn));
		while (observations.size() > MAX_OBSERVATIONS)
		{
			observations.removeFirst();
		}
	}

	private void prune(int currentTick)
	{
		while (!observations.isEmpty())
		{
			int age = currentTick - observations.peekFirst().tick;
			if (age >= 0 && age <= MAX_SOURCE_AGE_TICKS)
			{
				break;
			}
			observations.removeFirst();
		}
	}

	private static String normalize(String value)
	{
		if (value == null)
		{
			return null;
		}
		String trimmed = value.trim();
		return trimmed.isEmpty() ? null : trimmed;
	}

	private static final class Observation
	{
		private final int npcId;
		private final String name;
		private final int combatLevel;
		private final int tick;
		private final boolean interactingWithLocalPlayer;
		private final boolean despawn;

		private Observation(
			int npcId,
			String name,
			int combatLevel,
			int tick,
			boolean interactingWithLocalPlayer,
			boolean despawn)
		{
			this.npcId = npcId;
			this.name = name;
			this.combatLevel = combatLevel;
			this.tick = tick;
			this.interactingWithLocalPlayer = interactingWithLocalPlayer;
			this.despawn = despawn;
		}

		private boolean isBetterThan(Observation other)
		{
			if (interactingWithLocalPlayer != other.interactingWithLocalPlayer)
			{
				return interactingWithLocalPlayer;
			}
			if (despawn != other.despawn)
			{
				return despawn;
			}
			if ((combatLevel > 0) != (other.combatLevel > 0))
			{
				return combatLevel > 0;
			}
			if (tick != other.tick)
			{
				return tick > other.tick;
			}
			if (combatLevel != other.combatLevel)
			{
				return combatLevel > other.combatLevel;
			}
			return npcId < other.npcId;
		}
	}
}

package com.raredropping;

import java.io.IOException;
import java.time.Instant;
import java.util.Collections;
import java.util.List;

/** Replays one durable raw event through preflight and, only on a match, proof. */
final class RareDropOutageRetry
{
	enum Disposition
	{
		SENT,
		IGNORED,
		PREFLIGHT_FAILED,
		PROOF_FAILED,
		LOCAL_FAILURE
	}

	private final RareDropHistoryStore store;
	private final RareDropWebhookClient client;
	private final String token;
	private final String eventId;

	RareDropOutageRetry(
		RareDropHistoryStore store,
		RareDropWebhookClient client,
		String token,
		String eventId)
	{
		this.store = store;
		this.client = client;
		this.token = token;
		this.eventId = eventId;
	}

	void start(Listener listener)
	{
		try
		{
			RareDropHistoryEntry entry = store.find(eventId)
				.orElseThrow(() -> new IOException("Saved outage event was not found"));
			if (!entry.isAwaitingPreflight())
				throw new IOException("Saved event is not waiting for preflight");
			RareDropReport report = store.loadRawReport(eventId);
			RareDropScreenshot screenshot = store.loadScreenshot(eventId);
			client.preflight(token, report, result -> onPreflight(screenshot, result, listener));
		}
		catch (IOException | RuntimeException exception)
		{
			notify(listener, new Result(Disposition.LOCAL_FAILURE, eventId, 0,
				Collections.emptyList(), exception));
		}
	}

	private void onPreflight(
		RareDropScreenshot screenshot,
		RareDropWebhookClient.PreflightResult result,
		Listener listener)
	{
		if (result == null || !result.isAccepted())
		{
			int statusCode = result == null ? 0 : result.getStatusCode();
			try { store.markFailure(eventId, statusCode); }
			catch (IOException | RuntimeException exception)
			{
				notify(listener, new Result(Disposition.LOCAL_FAILURE, eventId, statusCode,
					Collections.emptyList(), exception));
				return;
			}
			notify(listener, new Result(Disposition.PREFLIGHT_FAILED, eventId, statusCode,
				Collections.emptyList(), null));
			return;
		}

		if (result.getMatches().isEmpty())
		{
			try
			{
				store.markIgnored(eventId, Instant.now(), acceptedStatus(result.getStatusCode()));
				notify(listener, new Result(Disposition.IGNORED, eventId,
					acceptedStatus(result.getStatusCode()), result.getMatches(), null));
			}
			catch (IOException | RuntimeException exception)
			{
				notify(listener, new Result(Disposition.LOCAL_FAILURE, eventId,
					result.getStatusCode(), result.getMatches(), exception));
			}
			return;
		}

		try
		{
			store.bindMatch(eventId, result.getMatches().get(0).getTilePosition());
			client.sendProof(token, eventId, screenshot,
				proof -> onProof(proof, result.getMatches(), listener));
		}
		catch (IOException | RuntimeException exception)
		{
			notify(listener, new Result(Disposition.LOCAL_FAILURE, eventId,
				result.getStatusCode(), result.getMatches(), exception));
		}
	}

	private void onProof(
		RareDropWebhookClient.ProofResult proof,
		List<RareDropWebhookClient.TileMatch> preflightMatches,
		Listener listener)
	{
		if (proof == null || !proof.isAccepted())
		{
			int statusCode = proof == null ? 0 : proof.getStatusCode();
			try { store.markFailure(eventId, statusCode); }
			catch (IOException | RuntimeException exception)
			{
				notify(listener, new Result(Disposition.LOCAL_FAILURE, eventId, statusCode,
					preflightMatches, exception));
				return;
			}
			notify(listener, new Result(Disposition.PROOF_FAILED, eventId, statusCode,
				preflightMatches, null));
			return;
		}
		try
		{
			store.markSent(eventId, Instant.now(), acceptedStatus(proof.getStatusCode()));
			List<RareDropWebhookClient.TileMatch> matches = proof.getMatches().isEmpty()
				? preflightMatches
				: proof.getMatches();
			notify(listener, new Result(Disposition.SENT, eventId,
				acceptedStatus(proof.getStatusCode()), matches, null));
		}
		catch (IOException | RuntimeException exception)
		{
			notify(listener, new Result(Disposition.LOCAL_FAILURE, eventId,
				proof.getStatusCode(), preflightMatches, exception));
		}
	}

	private static int acceptedStatus(int statusCode)
	{
		return statusCode == 201 ? 201 : 200;
	}

	private static void notify(Listener listener, Result result)
	{
		if (listener != null) listener.onResult(result);
	}

	interface Listener
	{
		void onResult(Result result);
	}

	static final class Result
	{
		private final Disposition disposition;
		private final String eventId;
		private final int statusCode;
		private final List<RareDropWebhookClient.TileMatch> matches;
		private final Throwable failure;
		private Result(Disposition disposition, String eventId, int statusCode,
			List<RareDropWebhookClient.TileMatch> matches, Throwable failure)
		{
			this.disposition = disposition;
			this.eventId = eventId;
			this.statusCode = statusCode;
			this.matches = matches == null ? Collections.emptyList() : matches;
			this.failure = failure;
		}
		Disposition getDisposition() { return disposition; }
		String getEventId() { return eventId; }
		int getStatusCode() { return statusCode; }
		List<RareDropWebhookClient.TileMatch> getMatches() { return matches; }
		Throwable getFailure() { return failure; }
	}
}

package com.raredropping;

import net.runelite.client.util.Text;

final class RareDropPetDetector
{
	private static final String FOLLOWING_MESSAGE = "You have a funny feeling like you're being followed";
	private static final String BACKPACK_MESSAGE = "You feel something weird sneaking into your backpack";
	private static final String DUPLICATE_MESSAGE = "You have a funny feeling like you would have been followed";

	private RareDropPetDetector()
	{
	}

	static boolean isPetDropMessage(String message)
	{
		return awardType(message) != null;
	}

	static PetAwardType awardType(String message)
	{
		if (message == null)
		{
			return null;
		}

		String plainText = Text.removeTags(message);
		if (plainText.contains(FOLLOWING_MESSAGE))
		{
			return PetAwardType.FOLLOWER;
		}
		if (plainText.contains(BACKPACK_MESSAGE))
		{
			return PetAwardType.BACKPACK;
		}
		if (plainText.contains(DUPLICATE_MESSAGE))
		{
			return PetAwardType.DUPLICATE;
		}
		return null;
	}

	enum PetAwardType
	{
		FOLLOWER,
		BACKPACK,
		DUPLICATE
	}
}

