		discordWebhookSettingsStore = null;
		discordDropFilter = DiscordDropFilter.defaults();
		if (historyNavigation != null)
		{
			clientToolbar.removeNavigation(historyNavigation);
			historyNavigation = null;
		}
		historyStore = null;
		evaluator = null;
		petCatalog.clear();
		petCatalogLoaded = false;
		recentPetIdentity = null;
		resetCaptureState();
		lootTrackerWarningShown = false;
		pairingWarningShown = false;
		discordDeliveryWarningShown.set(false);
		lootTrackerActive = false;
		sidebarCompetitionId = null;
		sidebarGeneration.incrementAndGet();
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event == null || evaluator == null || !hasEnabledDropDestination()) return;
		if (event.getType() == LootRecordType.PLAYER)
		{
			// Never submit another player's character name or PvP loot to either service.
			return;
		}
		List<RareDropItem> items = evaluator.collectItems(event.getItems());
		if (items.isEmpty()) return;
		Player localPlayer = client.getLocalPlayer();
		String username = localPlayer == null ? null : localPlayer.getName();
		if (!canCollectForDiscord(username) && !canCollectForBingo(username)) return;
		RareDropReport report = RareDropReport.pending(
			newEventId(),
			username,
			Instant.now(),
			items,
			event.getType() == LootRecordType.NPC ? event.getName() : null);
		dispatchReport(report);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event == null) return;
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM) return;
		recordCollectionLogPet(event.getMessage());
		if (!hasEnabledDropDestination()) return;
		RareDropPetDetector.PetAwardType awardType = RareDropPetDetector.awardType(event.getMessage());
		if (awardType == null) return;
		Player localPlayer = client.getLocalPlayer();
		String username = localPlayer == null ? null : localPlayer.getName();
		if (!canCollectForDiscord(username) && !canCollectForBingo(username)) return;
		RareDropReport report = RareDropReport.pendingPet(
			newEventId(),
			username,
			"Pet (name unavailable)",
			awardType,
			Instant.now(),
			npcSourceTracker.findBestSource(client.getTickCount()));
		dispatchReport(resolvePetIdentity(report));
	}

	@Subscribe public void onNpcSpawned(NpcSpawned event) { recordNpcLifecycle(event == null ? null : event.getNpc(), false); }
	@Subscribe public void onNpcDespawned(NpcDespawned event) { recordNpcLifecycle(event == null ? null : event.getNpc(), true); }

	private void dispatchReport(RareDropReport report)
	{
		RareDropWebhookClient bingoClientSnapshot = webhookClient;
		boolean sendToBingo = config.sendPings() && bingoClientSnapshot != null
			&& canCollectForBingo(report.getUsername());
		String token = sendToBingo ? deviceToken() : "";
		if (sendToBingo && token.isEmpty())
		{
			warnPairingOnce();
			sendToBingo = false;
		}

		String discordUrl = activeDiscordWebhookUrl();
		DiscordWebhookClient discordClientSnapshot = discordWebhookClient;
		RareDropReport discordReport = discordDropFilter.filteredReport(report);
		boolean sendToDiscord = discordClientSnapshot != null && discordUrl != null
			&& canCollectForDiscord(report.getUsername()) && discordReport != null;
		if (!sendToBingo && !sendToDiscord) return;

		long generation = captureGeneration.get();
		CompletableFuture<CapturedFrame> frame = requestFrame(report.getUsername(), generation);
		if (sendToBingo)
		{
			bingoClientSnapshot.preflight(token, report,
				result -> handlePreflight(report, token, bingoClientSnapshot, generation, frame, result));
		}
		if (sendToDiscord)
		{
			deliverDiscordWhenFrameArrives(
				discordReport, discordUrl, discordClientSnapshot, generation, frame);
		}
	}

	private CompletableFuture<CapturedFrame> requestFrame(
		String username,
		long generation)
	{
		CompletableFuture<CapturedFrame> result = new CompletableFuture<>();
		if (pendingFrames.incrementAndGet() > MAX_PENDING_FRAMES)
		{
			pendingFrames.decrementAndGet();
			result.complete(null);
			return result;
		}
		AtomicBoolean active = new AtomicBoolean(true);
		ScheduledFuture<?> timeout;
		try
		{
			timeout = scheduler.schedule(() ->
			{
				if (active.compareAndSet(true, false))
				{
					pendingFrames.decrementAndGet();
					result.complete(null);
				}
			}, FRAME_CAPTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
		catch (RejectedExecutionException exception)
		{
			pendingFrames.decrementAndGet();
			result.complete(null);
			return result;
		}

		try
		{
			drawManager.requestNextFrameListener(image ->
			{
				if (!active.compareAndSet(true, false)) return;
				timeout.cancel(false);
				pendingFrames.decrementAndGet();
				if (!canCaptureCurrentFrame(username, generation))
				{
					result.complete(null);
					return;
				}
				result.complete(new CapturedFrame(image, new RareDropCaptureArea(
					client.getCanvasWidth(), client.getCanvasHeight(),
					client.getViewportXOffset(), client.getViewportYOffset(),
					client.getViewportWidth(), client.getViewportHeight())));
			});
		}
		catch (RuntimeException exception)
		{
			if (active.compareAndSet(true, false))
			{
				timeout.cancel(false);
				pendingFrames.decrementAndGet();
				result.complete(null);
			}
		}
		return result;
	}

	private void handlePreflight(
		RareDropReport report,
		String token,
		RareDropWebhookClient clientSnapshot,
		long generation,
		CompletableFuture<CapturedFrame> frame,
		RareDropWebhookClient.PreflightResult result)
	{
		if (!isCaptureCurrent(clientSnapshot, generation)) return;
		if (result == null)
		{
			persistOutageEventWhenFrameArrives(report, token, clientSnapshot, generation, frame);
			return;
		}
		if (result.getStatusCode() == 401)
		{
			invalidateDeviceCredential("Your RuneLite connection expired. Pair this character again in Settings.");
			return;
		}
		if (!result.isAccepted())
		{
			if (isTransientFailure(result.getStatusCode()))
			{
				persistOutageEventWhenFrameArrives(report, token, clientSnapshot, generation, frame);
			}
			else if (result.getStatusCode() > 0)
			{
				showLocalMessage("Exodus Bingo: event check was rejected with HTTP "
					+ result.getStatusCode() + ".");
			}
			return;
		}
		if (result.getMatches().isEmpty())
		{
			// The service, not the plugin, has decided this event is unrelated.
			return;
		}
		frame.whenComplete((capturedFrame, failure) ->
		{
			if (failure != null || capturedFrame == null)
			{
				showLocalMessage("Exodus Bingo: a matching drop was found, but its screenshot could not be captured.");
				return;
			}
			try
			{
				scheduler.execute(() -> encodeMatchedEvent(
					report, token, clientSnapshot, generation, capturedFrame, result.getMatches()));
			}
			catch (RejectedExecutionException exception)
			{
				showLocalMessage("Exodus Bingo: the screenshot queue is unavailable.");
			}
		});
	}

	private void persistOutageEventWhenFrameArrives(
		RareDropReport report,
		String token,
		RareDropWebhookClient clientSnapshot,
		long generation,
		CompletableFuture<CapturedFrame> frame)
	{
		frame.whenComplete((capturedFrame, failure) ->
		{
			if (failure != null || capturedFrame == null)
			{
				showLocalMessage("Exodus Bingo: the service was unavailable and the event frame could not be saved.");
				return;
			}
			try
			{
				scheduler.execute(() -> encodeOutageEvent(
					report, token, clientSnapshot, generation, capturedFrame));
			}
			catch (RejectedExecutionException exception)
			{
				showLocalMessage("Exodus Bingo: the local outage queue is unavailable.");
			}
		});
	}

	private void deliverDiscordWhenFrameArrives(
		RareDropReport report,
		String discordUrl,
		DiscordWebhookClient clientSnapshot,
		long generation,
		CompletableFuture<CapturedFrame> frame)
	{
		frame.whenComplete((capturedFrame, failure) ->
		{
			if (!isDiscordTransportCurrent(clientSnapshot, discordUrl)) return;
			if (failure != null || capturedFrame == null
				|| !isDiscordScreenshotCurrent(clientSnapshot, discordUrl, generation))
			{
				sendDiscordReport(report, null, discordUrl, clientSnapshot);
				return;
			}
			DiscordScreenshotQueue screenshotQueue = discordScreenshotQueue;
			Runnable metadataFallback = () ->
				sendDiscordReport(report, null, discordUrl, clientSnapshot);
			if (screenshotQueue == null)
			{
				metadataFallback.run();
				return;
			}
			screenshotQueue.submitOrRunFallback(
				() -> encodeAndSendDiscord(
					report, discordUrl, clientSnapshot, generation, capturedFrame),
				metadataFallback);
		});
	}

	private void encodeAndSendDiscord(
		RareDropReport report,
		String discordUrl,
		DiscordWebhookClient clientSnapshot,
		long generation,
		CapturedFrame frame)
	{
		if (!isDiscordTransportCurrent(clientSnapshot, discordUrl)) return;
		if (!isDiscordScreenshotCurrent(clientSnapshot, discordUrl, generation))
		{
			sendDiscordReport(report, null, discordUrl, clientSnapshot);
			return;
		}
		try
		{
			BufferedImage source = ImageUtil.bufferedImageFromImage(frame.image);
			BufferedImage evidence = RareDropEvidenceRenderer.renderDiscord(
				frame.captureArea.crop(source), report);
			RareDropScreenshot screenshot = screenshotEncoder.encode(evidence);
			if (isDiscordScreenshotCurrent(clientSnapshot, discordUrl, generation))
			{
				sendDiscordReport(report, screenshot, discordUrl, clientSnapshot);
			}
			else
			{
				sendDiscordReport(report, null, discordUrl, clientSnapshot);
			}
		}
		catch (IOException | RuntimeException exception)
		{
			log.debug("Discord drop screenshot processing failed ({})",
				exception.getClass().getSimpleName());
			sendDiscordReport(report, null, discordUrl, clientSnapshot);
		}
	}

	private void sendDiscordReport(
		RareDropReport report,
		RareDropScreenshot screenshot,
		String discordUrl,
		DiscordWebhookClient clientSnapshot)
	{
		if (!isDiscordTransportCurrent(clientSnapshot, discordUrl)) return;
		clientSnapshot.send(report, screenshot, result ->
		{
			if (!isDiscordTransportCurrent(clientSnapshot, discordUrl)) return;
			if (result != null && result.isAccepted())
			{
				discordDeliveryWarningShown.set(false);
				return;
			}
			int statusCode = result == null ? 0 : result.getStatusCode();
			warnDiscordDeliveryOnce(statusCode > 0
				? "Discord rejected it with HTTP " + statusCode + ". Check the webhook in Settings."
				: "delivery failed. Check the webhook in Settings.");
		});
	}

	private void encodeOutageEvent(
		RareDropReport report,
		String token,
		RareDropWebhookClient clientSnapshot,
		long generation,
		CapturedFrame frame)
	{
		if (!isCaptureCurrent(clientSnapshot, generation)) return;
		try
		{
			BufferedImage source = ImageUtil.bufferedImageFromImage(frame.image);
			BufferedImage evidence = RareDropEvidenceRenderer.render(frame.captureArea.crop(source), report);
			RareDropScreenshot screenshot = screenshotEncoder.encode(evidence);
			RareDropHistoryStore store = awaitHistoryStore();
			RareDropSubmission submission = RareDropSubmission.forPendingPreflight(report, screenshot);
			RareDropHistoryEntry saved = store.savePending(PROOF_ENDPOINT, token, submission);
			publishHistory(store, false);
			thumbnailEventIds.add(saved.getEventId());
			historyPanel.setThumbnail(saved.getEventId(), screenshot);
			showLocalMessage("Exodus Bingo: the service is unavailable. This event is saved in Settings > Drop history; press Push later.");
		}
		catch (IOException | RuntimeException exception)
		{
			log.warn("Outage event could not be saved", exception);
			showLocalMessage("Exodus Bingo: the service was unavailable and the event could not be saved locally.");
		}
	}

	private static boolean isTransientFailure(int statusCode)
	{
		return statusCode == 0 || statusCode == 408 || statusCode == 429 || statusCode >= 500;
	}

	private void encodeMatchedEvent(
		RareDropReport report,
		String token,
		RareDropWebhookClient clientSnapshot,
		long generation,
		CapturedFrame frame,
		List<RareDropWebhookClient.TileMatch> matches)
	{
		if (!isCaptureCurrent(clientSnapshot, generation) || matches.isEmpty()) return;
		try
		{
			BufferedImage source = ImageUtil.bufferedImageFromImage(frame.image);
			BufferedImage evidence = RareDropEvidenceRenderer.render(frame.captureArea.crop(source), report);
			RareDropScreenshot screenshot = screenshotEncoder.encode(evidence);
			RareDropHistoryStore store = awaitHistoryStore();
			RareDropSubmission submission = RareDropSubmission.forServerMatch(report, screenshot, matches.get(0));
			RareDropHistoryEntry saved = store.savePending(PROOF_ENDPOINT, token, submission);
			publishHistory(store, false);
			thumbnailEventIds.add(saved.getEventId());
			historyPanel.setThumbnail(saved.getEventId(), screenshot);
			if (!saved.isSent()) queueStoredDelivery(saved.getEventId(), clientSnapshot);
		}
		catch (IOException | RuntimeException exception)
		{
			log.warn("Matching bingo evidence could not be saved", exception);
			showLocalMessage("Exodus Bingo: matching evidence could not be saved locally, so it was not uploaded.");
		}
	}

	private void beginPairing()
	{
		clientThread.invokeLater(() ->
		{
			beginPairingOnClientThread();
			return true;
		});
	}

	private void beginPairingOnClientThread()
	{
		if (!running || webhookClient == null) return;
		Player localPlayer = client.getLocalPlayer();
		String character = localPlayer == null ? null : localPlayer.getName();
		if (client.getGameState() != GameState.LOGGED_IN || character == null || character.trim().isEmpty())
		{
			historyPanel.showDisconnected("Log into the character you want to pair, then try again.");
			return;
		}
		cancelPairingPoll();
		historyPanel.showPairingStarting(character);
		RareDropWebhookClient clientSnapshot = webhookClient;
		clientSnapshot.startPairing(character, "Exodus Bingo for RuneLite", result ->
		{
			if (!running || webhookClient != clientSnapshot) return;
			if (result == null || !result.isAccepted())
			{
				historyPanel.showDisconnected("Pairing could not start"
					+ (result != null && result.getStatusCode() > 0 ? " (HTTP " + result.getStatusCode() + ")." : "."));
				return;
			}
			PairingSession session = new PairingSession(
				result.getDeviceCode(), character, result.getVerificationUrl(),
				System.currentTimeMillis() + Math.max(30, result.getExpiresInSeconds()) * 1000L,
				result.getPollIntervalSeconds());
			pairingSession = session;
			historyPanel.showPairing(character, result.getUserCode(), result.getVerificationUrl());
			LinkBrowser.browse(result.getVerificationUrl());
			schedulePairingPoll(session, 0);
		});
	}

	private void schedulePairingPoll(PairingSession session, int delaySeconds)
	{
		if (!running || pairingSession != session) return;
		try
		{
			pairingPoll = scheduler.schedule(() -> pollPairing(session), Math.max(0, delaySeconds), TimeUnit.SECONDS);
		}
		catch (RejectedExecutionException exception)
		{
			historyPanel.showDisconnected("The pairing poll could not be scheduled. Try again.");
		}
	}

	private void pollPairing(PairingSession session)
	{
		if (!running || pairingSession != session || webhookClient == null) return;
		if (System.currentTimeMillis() >= session.expiresAtMillis)
		{
			pairingSession = null;
			historyPanel.showDisconnected("That pairing code expired. Request a new one.");
			return;
		}
		RareDropWebhookClient clientSnapshot = webhookClient;
		clientSnapshot.pollPairing(session.deviceCode, result ->
		{
			if (!running || pairingSession != session || webhookClient != clientSnapshot) return;
			if (result != null && result.isApproved())
			{
				String character = result.getCharacterName() == null ? session.character : result.getCharacterName();
				configManager.setConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.DEVICE_TOKEN_KEY, result.getDeviceToken());
				configManager.setConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.PAIRED_CHARACTER_KEY, character);
				pairingSession = null;
				pairingWarningShown = false;
				historyPanel.showConnected(character);
				refreshSidebar();
				showLocalMessage("Exodus Bingo: RuneLite connected successfully.");
				return;
			}
			if (result == null || result.isPending() || result.getStatusCode() == 0 || result.getStatusCode() == 429)
			{
				schedulePairingPoll(session, session.pollIntervalSeconds);
				return;
			}
			if (result.isTerminal())
			{
				pairingSession = null;
				historyPanel.showDisconnected("Pairing ended (" + result.getStatus() + "). Request a new code.");
			}
		});
	}

	private void disconnectDevice()
	{
		cancelPairingPoll();
		String token = deviceToken();
		BingoSidebarClient clientSnapshot = sidebarClient;
		AtomicBoolean finished = new AtomicBoolean();
		if (token.isEmpty() || clientSnapshot == null)
		{
			finishDisconnect(finished, token.isEmpty());
			return;
		}
		clientSnapshot.revoke(token, result -> finishDisconnect(
			finished, result != null && result.isAccepted()));
		try
		{
			scheduler.schedule(() -> finishDisconnect(finished, false), 5, TimeUnit.SECONDS);
		}
		catch (RejectedExecutionException exception)
		{
			finishDisconnect(finished, false);
		}
	}

	private void finishDisconnect(AtomicBoolean finished, boolean remoteConfirmed)
	{
		if (!finished.compareAndSet(false, true)) return;
		sidebarGeneration.incrementAndGet();
		configManager.unsetConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.DEVICE_TOKEN_KEY);
		configManager.unsetConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.PAIRED_CHARACTER_KEY);
		configManager.unsetConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.SELECTED_COMPETITION_KEY);
		pairingWarningShown = false;
		sidebarCompetitionId = null;
		String detail = remoteConfirmed
			? "Disconnected. Pair again to use this RuneLite client."
			: "Disconnected locally; remote revocation could not be confirmed.";
		historyPanel.showDisconnected(detail);
		if (!remoteConfirmed)
			showLocalMessage("Exodus Bingo: remote device revocation could not be confirmed, but this client was disconnected locally.");
	}

	private void invalidateDeviceCredential(String detail)
	{
		sidebarGeneration.incrementAndGet();
		configManager.unsetConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.DEVICE_TOKEN_KEY);
		configManager.unsetConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.PAIRED_CHARACTER_KEY);
		configManager.unsetConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.SELECTED_COMPETITION_KEY);
		pairingWarningShown = false;
		sidebarCompetitionId = null;
		historyPanel.showDisconnected(detail);
		showLocalMessage("Exodus Bingo: " + detail);
	}

	private void cancelPairingPoll()
	{
		pairingSession = null;
		ScheduledFuture<?> poll = pairingPoll;
		pairingPoll = null;
		if (poll != null) poll.cancel(false);
	}

	private String deviceToken()
	{
		String value = configManager.getConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.DEVICE_TOKEN_KEY);
		return value == null ? "" : value.trim();
	}

	private String storedSelectedCompetitionId()
	{
		String value = configManager.getConfiguration(
			RareDropPingConfig.GROUP, RareDropPingConfig.SELECTED_COMPETITION_KEY);
		return value == null || value.trim().isEmpty() ? null : value.trim();
	}

	private void storeSelectedCompetitionId(String competitionId)
	{
		if (competitionId == null || competitionId.trim().isEmpty())
		{
			configManager.unsetConfiguration(
				RareDropPingConfig.GROUP, RareDropPingConfig.SELECTED_COMPETITION_KEY);
			return;
		}
		configManager.setConfiguration(RareDropPingConfig.GROUP,
			RareDropPingConfig.SELECTED_COMPETITION_KEY, competitionId.trim());
	}

	private void clearLegacyConfiguration()
	{
		String[] retiredKeys = {
			"endpoint",
			"apiToken",
			"tileRoutingRules",
			"minimumStackValue",
			"alwaysPingItemIds",
			"inventoryDiffSafetyNet",
			"discordWebhookUrl"
		};
		for (String key : retiredKeys)
		{
			configManager.unsetConfiguration(RareDropPingConfig.GROUP, key);
		}
	}

	private void refreshPairingUi()
	{
		String token = deviceToken();
		String character = configManager.getConfiguration(RareDropPingConfig.GROUP, RareDropPingConfig.PAIRED_CHARACTER_KEY);
		Player localPlayer = client.getLocalPlayer();
		String detected = client.getGameState() == GameState.LOGGED_IN && localPlayer != null
			? localPlayer.getName() : null;
		historyPanel.setCaptureReadiness(config.sendPings(), lootTrackerActive,
			!token.isEmpty() && sameCharacter(character, detected));
		if (token.isEmpty()) historyPanel.showDisconnected("Pair once to send matching bingo evidence.");
		else historyPanel.showConnected(character == null || character.trim().isEmpty() ? "RuneLite" : character.trim());
	}

	private void refreshSidebar()
	{
		String token = deviceToken();
		BingoSidebarClient clientSnapshot = sidebarClient;
		if (!running || token.isEmpty() || clientSnapshot == null) return;
		long generation = sidebarGeneration.incrementAndGet();
		String preferred = sidebarCompetitionId == null ? storedSelectedCompetitionId() : sidebarCompetitionId;
		historyPanel.showBingoLoading("Refreshing board and achievements…");
		clientSnapshot.competitions(token, result ->
		{
			if (!isSidebarCurrent(clientSnapshot, generation)) return;
			if (result == null || !result.isAccepted())
			{
				handleSidebarFailure(result);
				return;
			}
			BingoSidebarData.Catalog catalog = result.getValue();
			String serverCharacter = catalog.characterName == null || catalog.characterName.trim().isEmpty()
				? catalog.characterDisplayName : catalog.characterName;
			String storedCharacter = configManager.getConfiguration(
				RareDropPingConfig.GROUP, RareDropPingConfig.PAIRED_CHARACTER_KEY);
			if (serverCharacter != null && !serverCharacter.trim().isEmpty()
				&& !sameCharacter(storedCharacter, serverCharacter))
			{
				configManager.setConfiguration(RareDropPingConfig.GROUP,
					RareDropPingConfig.PAIRED_CHARACTER_KEY, serverCharacter.trim());
				historyPanel.showConnected(serverCharacter.trim());
			}
			String competitionId = chooseCompetition(catalog, preferred);
			sidebarCompetitionId = competitionId;
			storeSelectedCompetitionId(competitionId);
			historyPanel.setBingoCatalog(catalog, competitionId);
			if (competitionId != null) loadSidebarCompetition(clientSnapshot, token, competitionId, generation, true);
		});
	}

	private void selectSidebarCompetition(String competitionId)
	{
		String token = deviceToken();
		BingoSidebarClient clientSnapshot = sidebarClient;
		if (!running || token.isEmpty() || clientSnapshot == null
			|| competitionId == null || competitionId.trim().isEmpty()) return;
		sidebarCompetitionId = competitionId.trim();
		storeSelectedCompetitionId(sidebarCompetitionId);
		long generation = sidebarGeneration.incrementAndGet();
		historyPanel.showBingoLoading("Loading selected bingo…");
		loadSidebarCompetition(clientSnapshot, token, sidebarCompetitionId, generation, false);
	}

	private void loadSidebarCompetition(BingoSidebarClient clientSnapshot, String token,
		String competitionId, long generation, boolean animateCompletions)
	{
		clientSnapshot.board(token, competitionId, result ->
		{
			if (!isSidebarCurrent(clientSnapshot, generation) || !competitionId.equals(sidebarCompetitionId)) return;
			if (result == null || !result.isAccepted())
			{
				handleSidebarFailure(result);
				return;
			}
			historyPanel.setBingoBoard(result.getValue(), animateCompletions);
		});
		clientSnapshot.achievements(token, competitionId, result ->
		{
			if (!isSidebarCurrent(clientSnapshot, generation) || !competitionId.equals(sidebarCompetitionId)) return;
			if (result != null && result.isAccepted()) historyPanel.setBingoAchievements(result.getValue());
			else handleSidebarFailure(result);
		});
	}

	private void joinSidebarCompetition(String joinCode)
	{
		clientThread.invokeLater(() ->
		{
			String paired = configManager.getConfiguration(
				RareDropPingConfig.GROUP, RareDropPingConfig.PAIRED_CHARACTER_KEY);
			Player localPlayer = client.getLocalPlayer();
			String detected = localPlayer == null ? null : localPlayer.getName();
			if (client.getGameState() != GameState.LOGGED_IN || !sameCharacter(paired, detected))
			{
				historyPanel.showBingoError("Log into the paired character "
					+ (paired == null ? "before joining." : paired + " before joining."));
				return true;
			}
			joinSidebarCompetitionForDetectedCharacter(joinCode);
			return true;
		});
	}

	private void joinSidebarCompetitionForDetectedCharacter(String joinCode)
	{
		String token = deviceToken();
		BingoSidebarClient clientSnapshot = sidebarClient;
		if (!running || token.isEmpty() || clientSnapshot == null) return;
		historyPanel.showBingoLoading("Joining bingo with the paired RuneLite character…");
		clientSnapshot.join(token, joinCode, result ->
		{
			if (!running || sidebarClient != clientSnapshot) return;
			if (result == null || !result.isAccepted())
			{
				handleSidebarFailure(result);
				return;
			}
			sidebarCompetitionId = result.getValue().competitionId;
			storeSelectedCompetitionId(sidebarCompetitionId);
			historyPanel.clearBingoJoinInput();
			showLocalMessage(result.getValue().duplicate
				? "Exodus Bingo: this character was already in that bingo."
				: "Exodus Bingo: character joined the bingo.");
			refreshSidebar();
		});
	}


	private void handleSidebarFailure(BingoSidebarClient.Result<?> result)
	{
		int statusCode = result == null ? 0 : result.getStatusCode();
		if (statusCode == 401)
		{
			invalidateDeviceCredential("Your RuneLite connection expired. Pair this character again.");
			return;
		}
		String message = result == null ? null : result.getError();
		if (message == null || message.trim().isEmpty())
			message = statusCode > 0 ? "Bingo request failed with HTTP " + statusCode + "."
				: "The Exodus Bingo service is unavailable.";
		historyPanel.showBingoError(message);
	}

	private boolean isSidebarCurrent(BingoSidebarClient clientSnapshot, long generation)
	{
		return running && sidebarClient == clientSnapshot && sidebarGeneration.get() == generation;
	}

	private static String chooseCompetition(BingoSidebarData.Catalog catalog, String preferred)
	{
		if (catalog == null || catalog.competitions.isEmpty()) return null;
		for (BingoSidebarData.CompetitionSummary competition : catalog.competitions)
			if (competition.id.equals(preferred)) return competition.id;
		for (BingoSidebarData.CompetitionSummary competition : catalog.competitions)
			if (competition.id.equals(catalog.defaultCompetitionId)) return competition.id;
		return catalog.competitions.get(0).id;
	}

	static boolean sameCharacter(String paired, String detected)
	{
		if (paired == null || detected == null) return false;
		return paired.replace('_', ' ').trim().replaceAll("\\s+", " ").equalsIgnoreCase(
			detected.replace('_', ' ').trim().replaceAll("\\s+", " "));
	}

