	private boolean saveDiscordWebhookUrl(String value)
	{
		String normalized = DiscordWebhookClient.normalizeWebhookUrl(value);
		boolean blank = value == null || value.trim().isEmpty();
		boolean previouslySaved = discordWebhookUrl != null;
		DiscordWebhookSettingsStore store = discordWebhookSettingsStore;
		if (store == null)
		{
			discordWebhookUrl = null;
			resetDiscordWebhookClient();
			return false;
		}
		try
		{
			if (normalized == null)
			{
				store.clear();
				discordWebhookUrl = null;
				resetDiscordWebhookClient();
				return blank;
			}
			if (!store.save(normalized) || !normalized.equals(store.load()))
			{
				discordWebhookUrl = null;
				resetDiscordWebhookClient();
				return false;
			}
			discordWebhookUrl = normalized;
			if (!previouslySaved && discordWebhookEnabled()) setDiscordWebhookEnabled(false);
			resetDiscordWebhookClient();
			return true;
		}
		catch (IOException | RuntimeException exception)
		{
			discordWebhookUrl = null;
			resetDiscordWebhookClient();
			log.warn("Discord webhook secret could not be saved locally ({})",
				exception.getClass().getSimpleName());
			return false;
		}
	}

	private void refreshDiscordWebhookUi()
	{
