	private RareDropHistoryStore awaitHistoryStore() throws IOException
	{
		RareDropHistoryStore store = historyStore;
		if (store != null) return store;
		try
		{
			return historyStoreReady.get(FRAME_CAPTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
		catch (InterruptedException exception)
		{
			throw new IOException("Interrupted while opening drop history", exception);
		}
		catch (ExecutionException | TimeoutException exception)
		{
			throw new IOException("Drop history is unavailable", exception);
		}
	}

	private void initializeHistoryStore(CompletableFuture<RareDropHistoryStore> ready, long generation)
	{
		try
		{
			RareDropHistoryStore store = new RareDropHistoryStore(
				new java.io.File(RuneLite.RUNELITE_DIR, HISTORY_DIRECTORY).toPath());
			store.pruneOldestSent(config.maxSentHistory());
			if (!running || lifecycleGeneration.get() != generation || historyStoreReady != ready)
			{
				ready.completeExceptionally(new IOException("Plugin stopped before history loaded"));
				return;
			}
			historyStore = store;
			ready.complete(store);
			publishHistory(store, true);
		}
		catch (IOException | RuntimeException exception)
		{
			log.warn("Unable to initialize durable bingo event history", exception);
			ready.completeExceptionally(exception);
			showLocalMessage("Exodus Bingo: local drop history could not be opened; uploads are paused.");
		}
	}

	private void publishHistory(RareDropHistoryStore store, boolean loadThumbnails)
	{
		if (!running || store == null || historyStore != store) return;
		try
		{
			List<RareDropHistoryEntry> allEntries = store.listLatest();
			int visibleCount = Math.min(historyDisplayLimit, allEntries.size());
			List<RareDropHistoryEntry> entries = new ArrayList<>(allEntries.subList(0, visibleCount));
			historyPanel.setEntries(entries, allEntries.size());
			Set<String> visibleEventIds = new HashSet<>();
			for (RareDropHistoryEntry entry : entries) visibleEventIds.add(entry.getEventId());
			thumbnailEventIds.retainAll(visibleEventIds);
			if (loadThumbnails)
			{
				for (RareDropHistoryEntry entry : entries)
				{
					if (!thumbnailEventIds.add(entry.getEventId())) continue;
					try { historyPanel.setThumbnail(entry.getEventId(), store.loadScreenshot(entry.getEventId())); }
					catch (IOException | RuntimeException exception)
					{
						thumbnailEventIds.remove(entry.getEventId());
						historyPanel.setThumbnail(entry.getEventId(), null);
					}
				}
			}
		}
		catch (IOException | RuntimeException exception)
		{
			log.warn("Unable to refresh bingo event history", exception);
		}
	}

	private void pushHistoryEntry(String eventId)
	{
		if (!running || !config.sendPings())
		{
			historyPanel.markFailed(eventId, 0);
			showLocalMessage("Exodus Bingo: enable Send bingo events before retrying evidence.");
			return;
		}
		if (deviceToken().isEmpty())
		{
			historyPanel.markFailed(eventId, 0);
			showLocalMessage("Exodus Bingo: pair RuneLite before retrying saved evidence.");
			return;
		}
		queueStoredDelivery(eventId, webhookClient);
	}

	private void queueStoredDelivery(String eventId, RareDropWebhookClient clientSnapshot)
	{
		if (eventId == null || clientSnapshot == null || !inFlightEventIds.add(eventId)) return;
		historyPanel.markSending(eventId);
		try { scheduler.execute(() -> deliverStoredEntry(eventId, clientSnapshot)); }
		catch (RejectedExecutionException exception) { failStoredDelivery(eventId, "the upload queue is unavailable."); }
	}

	private void deliverStoredEntry(String eventId, RareDropWebhookClient clientSnapshot)
	{
		RareDropHistoryStore store = historyStore;
		String token = deviceToken();
		if (!running || store == null || webhookClient != clientSnapshot || token.isEmpty())
		{
			failStoredDelivery(eventId, "pair RuneLite, then press Push to retry.");
			return;
		}
		try
		{
			RareDropHistoryEntry entry = store.find(eventId)
				.orElseThrow(() -> new IOException("The saved event was not found"));
			if (entry.isResolved())
			{
				inFlightEventIds.remove(eventId);
				publishHistory(store, false);
				return;
			}
			if (!entry.getTokenFingerprint().equals(RareDropHistoryStore.tokenFingerprint(token)))
				entry = store.rebindDeviceToken(eventId, token);
			if (entry.isAwaitingPreflight())
			{
				new RareDropOutageRetry(store, clientSnapshot, token, eventId)
					.start(this::onOutageRetryResult);
			}
			else
			{
				RareDropScreenshot screenshot = store.loadScreenshot(eventId);
				clientSnapshot.sendProof(token, eventId, screenshot, this::onProofResult);
			}
		}
		catch (IOException | RuntimeException exception)
		{
			log.warn("Unable to load saved bingo evidence", exception);
			failStoredDelivery(eventId, "the saved evidence could not be read.");
		}
	}

	private void onOutageRetryResult(RareDropOutageRetry.Result result)
	{
		if (result == null) return;
		String eventId = result.getEventId();
		inFlightEventIds.remove(eventId);
		RareDropHistoryStore store = historyStore;
		if (store != null)
		{
			try
			{
				if (result.getDisposition() == RareDropOutageRetry.Disposition.SENT
					|| result.getDisposition() == RareDropOutageRetry.Disposition.IGNORED)
				{
					store.pruneOldestSent(config.maxSentHistory());
				}
				publishHistory(store, false);
			}
			catch (IOException | RuntimeException exception)
			{
				log.warn("Unable to refresh history after an outage retry", exception);
			}
		}

		switch (result.getDisposition())
		{
			case SENT:
				showLocalMessage("Exodus Bingo: saved evidence was accepted for "
					+ result.getMatches().size() + " tile"
					+ (result.getMatches().size() == 1 ? "." : "s."));
				break;
			case IGNORED:
				showLocalMessage("Exodus Bingo: the saved event was checked; no active bingo tile needs it.");
				break;
			case PREFLIGHT_FAILED:
			case PROOF_FAILED:
				historyPanel.markFailed(eventId, result.getStatusCode());
				if (result.getStatusCode() == 401)
				{
					invalidateDeviceCredential("Your RuneLite connection expired. Pair again, then retry the saved event.");
				}
				else
				{
					showLocalMessage(result.getStatusCode() > 0
						? "Exodus Bingo: saved event retry failed with HTTP " + result.getStatusCode() + "."
						: "Exodus Bingo: the service is still unavailable; the event remains saved.");
				}
				break;
			case LOCAL_FAILURE:
			default:
				log.warn("A saved outage event could not be retried", result.getFailure());
				historyPanel.markFailed(eventId, 0);
				showLocalMessage("Exodus Bingo: the saved event could not be read or updated.");
				break;
		}
	}

	private void onProofResult(RareDropWebhookClient.ProofResult result)
	{
		if (result == null) return;
		String eventId = result.getEventId();
		inFlightEventIds.remove(eventId);
		RareDropHistoryStore store = historyStore;
		boolean receiptSaved = false;
		if (running && store != null)
		{
			try
			{
				if (result.isAccepted())
				{
					store.markSent(eventId, Instant.now(), result.getStatusCode() == 201 ? 201 : 200);
					receiptSaved = true;
					store.pruneOldestSent(config.maxSentHistory());
				}
				else
				{
					store.markFailure(eventId, result.getStatusCode());
					receiptSaved = true;
				}
				publishHistory(store, false);
			}
			catch (IOException | RuntimeException exception) { log.warn("Unable to update bingo event history", exception); }
		}
		if (!result.isAccepted() || !receiptSaved) historyPanel.markFailed(eventId, result.isAccepted() ? 0 : result.getStatusCode());
		if (result.getStatusCode() == 401)
		{
			invalidateDeviceCredential("Your RuneLite connection expired. Pair again, then retry the saved event.");
			return;
		}
		if (!config.showUploadMessages()) return;
		if (result.isAccepted() && receiptSaved)
		{
			int count = result.getMatches().size();
			showLocalMessage("Exodus Bingo: evidence accepted"
				+ (count == 0 ? "." : " for " + count + " tile" + (count == 1 ? "." : "s.")));
		}
		else if (!result.isAccepted())
		{
			showLocalMessage(result.getStatusCode() > 0
				? "Exodus Bingo: upload rejected with HTTP " + result.getStatusCode()
					+ "; open Settings > Drop history and press Push to retry."
				: "Exodus Bingo: upload failed; it is saved in Settings > Drop history. Press Push to retry.");
		}
	}

	private void failStoredDelivery(String eventId, String reason)
	{
		inFlightEventIds.remove(eventId);
		historyPanel.markFailed(eventId, 0);
		showLocalMessage("Exodus Bingo: " + reason);
	}

	private void clearSentHistory()
	{
		RareDropHistoryStore store = historyStore;
		if (!running || store == null) return;
		try
		{
			scheduler.execute(() ->
			{
				try
				{
					int removed = store.clearSent();
					publishHistory(store, true);
					showLocalMessage("Exodus Bingo: cleared " + removed + " resolved event" + (removed == 1 ? "." : "s."));
				}
				catch (IOException | RuntimeException exception) { showLocalMessage("Exodus Bingo: resolved history could not be cleared."); }
			});
		}
		catch (RejectedExecutionException exception) { showLocalMessage("Exodus Bingo: the history queue is unavailable."); }
	}

	private void loadOlderHistory()
	{
		RareDropHistoryStore store = historyStore;
		if (!running || store == null) return;
		historyDisplayLimit = historyDisplayLimit > Integer.MAX_VALUE - HISTORY_PAGE_SIZE
			? Integer.MAX_VALUE : historyDisplayLimit + HISTORY_PAGE_SIZE;
		try { scheduler.execute(() -> publishHistory(store, true)); }
		catch (RejectedExecutionException ignored) { }
	}

	private RareDropReport resolvePetIdentity(RareDropReport report)
	{
		if (!report.isPet()) return report;
		RecentPetIdentity recent = recentPetIdentity;
		if (recent != null && recent.generation == captureGeneration.get() && recent.tick == client.getTickCount())
		{
			recentPetIdentity = null;
			return report.withPetIdentity(recent.identity.itemId, recent.identity.name);
		}
		if (!RareDropPetDetector.PetAwardType.FOLLOWER.name().equals(report.getPetAwardType())) return report;
		NPC follower = client.getFollower();
		String name = follower == null ? null : follower.getName();
		if (name == null || name.trim().isEmpty()) return report;
		PetIdentity identity = findPetIdentity(name);
		return identity == null ? report.withPetIdentity(null, name) : report.withPetIdentity(identity.itemId, identity.name);
	}

	private void recordCollectionLogPet(String message)
	{
		String plainText = message == null ? "" : Text.removeTags(message);
		if (!plainText.startsWith(COLLECTION_LOG_PREFIX)) return;
		PetIdentity identity = findPetIdentity(plainText.substring(COLLECTION_LOG_PREFIX.length()).trim());
		if (identity != null)
			recentPetIdentity = new RecentPetIdentity(identity, client.getTickCount(), captureGeneration.get());
	}

	private PetIdentity findPetIdentity(String name)
	{
		if (name == null || name.trim().isEmpty()) return null;
		loadPetCatalog();
		return petCatalog.get(name.trim().toLowerCase(Locale.ROOT));
	}

	private void loadPetCatalog()
	{
		if (petCatalogLoaded) return;
		petCatalogLoaded = true;
		try
		{
			EnumComposition pets = client.getEnum(EnumID.PETS);
			for (int index = 0; index < pets.size(); index++)
			{
				int itemId = pets.getIntValue(index);
				ItemComposition composition = itemManager.getItemComposition(itemId);
				String name = composition == null ? null : composition.getName();
				if (name != null && !name.trim().isEmpty())
					petCatalog.put(name.trim().toLowerCase(Locale.ROOT), new PetIdentity(itemId, name.trim()));
			}
		}
		catch (RuntimeException exception)
		{
			petCatalogLoaded = false;
			log.debug("Unable to load RuneLite pet catalog ({})", exception.getClass().getSimpleName());
		}
	}

	private void recordNpcLifecycle(NPC npc, boolean despawn)
	{
		if (npc == null || client.getGameState() != GameState.LOGGED_IN || npc == client.getFollower()) return;
		Player localPlayer = client.getLocalPlayer();
		Actor npcInteraction = npc.getInteracting();
		Actor playerInteraction = localPlayer == null ? null : localPlayer.getInteracting();
		boolean interacting = localPlayer != null && (npcInteraction == localPlayer || playerInteraction == npc);
		if (despawn) npcSourceTracker.recordDespawn(npc.getId(), npc.getName(), npc.getCombatLevel(), client.getTickCount(), interacting);
		else npcSourceTracker.recordSpawn(npc.getId(), npc.getName(), npc.getCombatLevel(), client.getTickCount(), interacting);
	}

	private boolean canCollectForBingo(String username)
	{
		String paired = configManager.getConfiguration(
			RareDropPingConfig.GROUP, RareDropPingConfig.PAIRED_CHARACTER_KEY);
		return client.getGameState() == GameState.LOGGED_IN && sameCharacter(paired, username);
	}

	private boolean canCollectForDiscord(String username)
	{
		return client.getGameState() == GameState.LOGGED_IN
			&& username != null && !username.trim().isEmpty();
	}

	private boolean canCaptureCurrentFrame(String username, long generation)
	{
		Player localPlayer = client.getLocalPlayer();
		return isCaptureCurrent(generation) && client.getGameState() == GameState.LOGGED_IN
			&& localPlayer != null && username.equals(localPlayer.getName());
	}

	private boolean isCaptureCurrent(long generation)
	{
		return running && captureGeneration.get() == generation;
	}

	private boolean isCaptureCurrent(RareDropWebhookClient clientSnapshot, long generation)
	{
		return isCaptureCurrent(generation) && clientSnapshot != null && webhookClient == clientSnapshot;
	}

	private boolean isDiscordTransportCurrent(
		DiscordWebhookClient clientSnapshot,
		String discordUrl)
	{
		String currentUrl = activeDiscordWebhookUrl();
		return running && clientSnapshot != null
			&& discordWebhookClient == clientSnapshot && discordUrl != null
			&& discordUrl.equals(currentUrl);
	}

	private boolean isDiscordScreenshotCurrent(
		DiscordWebhookClient clientSnapshot,
		String discordUrl,
		long generation)
	{
		return isCaptureCurrent(generation)
			&& isDiscordTransportCurrent(clientSnapshot, discordUrl);
	}

	private void resetCaptureState()
	{
		captureGeneration.incrementAndGet();
		recentPetIdentity = null;
		npcSourceTracker.reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN) resetCaptureState();
		refreshPairingUi();
		if (event.getGameState() == GameState.LOGGED_IN) warnIfLootTrackerIsDisabled();
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		if (event.getPlugin() != lootTrackerPlugin) return;
		lootTrackerWarningShown = false;
		lootTrackerActive = event.isLoaded();
		refreshPairingUi();
		if (!event.isLoaded()) warnIfLootTrackerIsDisabled();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RareDropPingConfig.GROUP.equals(event.getGroup())) return;
		String key = event.getKey();
		if ("sendPings".equals(key))
		{
			lootTrackerWarningShown = false;
			pairingWarningShown = false;
			refreshPairingUi();
			warnIfLootTrackerIsDisabled();
		}
		else if (RareDropPingConfig.DEVICE_TOKEN_KEY.equals(key) || RareDropPingConfig.PAIRED_CHARACTER_KEY.equals(key))
		{
			refreshPairingUi();
		}
		else if (RareDropPingConfig.DISCORD_WEBHOOK_ENABLED_KEY.equals(key))
		{
			discordDeliveryWarningShown.set(false);
			lootTrackerWarningShown = false;
			if (!changingDiscordEnabledFromPanel.get()) refreshDiscordWebhookUi();
			warnIfLootTrackerIsDisabled();
		}
		else if (RareDropPingConfig.DISCORD_DROP_FILTER_KEY.equals(key))
		{
			if (!changingDiscordFilterFromPanel.get())
			{
				discordDropFilter = loadDiscordDropFilter();
				historyPanel.setDiscordFilterState(discordDropFilter);
			}
			lootTrackerWarningShown = false;
			warnIfLootTrackerIsDisabled();
		}
		else if ("maxSentHistory".equals(key) && historyStore != null)
		{
			RareDropHistoryStore store = historyStore;
			try { scheduler.execute(() ->
			{
				try { store.pruneOldestSent(config.maxSentHistory()); publishHistory(store, true); }
				catch (IOException | RuntimeException ignored) { }
			}); }
			catch (RejectedExecutionException ignored) { }
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		discordDeliveryWarningShown.set(false);
		lootTrackerWarningShown = false;
		discordDropFilter = loadDiscordDropFilter();
		refreshDiscordWebhookUi();
		warnIfLootTrackerIsDisabled();
	}

	private void warnIfLootTrackerIsDisabled()
	{
		clientThread.invokeLater(() ->
		{
			if (!running || lootTrackerWarningShown
				|| (!config.sendPings() && (activeDiscordWebhookUrl() == null
					|| !discordDropFilter.acceptsItemDrops()))
				|| client.getGameState() != GameState.LOGGED_IN || lootTrackerActive) return false;
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Exodus Bingo: enable RuneLite's built-in Loot Tracker plugin to detect drops.", null);
			lootTrackerWarningShown = true;
			return true;
		});
	}

	private void showLocalMessage(String message)
	{
		if (!running || !config.showUploadMessages()) return;
		clientThread.invokeLater(() ->
		{
			if (!running || !config.showUploadMessages()) return false;
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
			return true;
		});
	}

