package com.raredropping;

import com.google.gson.Gson;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Compact, validated JSON representation used only by the durable outage queue. */
final class RareDropRawEventCodec
{
	static final int MAX_JSON_LENGTH = 32 * 1024;
	private static volatile Gson gson;

	private RareDropRawEventCodec()
	{
	}

	static void configure(Gson injectedGson)
	{
		if (injectedGson == null) throw new IllegalArgumentException("A Gson instance is required");
		gson = injectedGson;
	}

	static String encode(RareDropReport report)
	{
		if (report == null) return null;
		Payload payload = new Payload();
		payload.eventId = report.getEventId();
		payload.occurredAt = report.getOccurredAt();
		payload.username = report.getUsername();
		payload.eventType = report.getEventType();
		payload.sourceNpc = report.getSourceNpc();
		payload.items = new ArrayList<>();
		for (RareDropItem item : report.getItems())
		{
			ItemPayload value = new ItemPayload();
			value.itemId = item.getItemId();
			value.name = item.getName();
			value.quantity = item.getQuantity();
			value.unitGePrice = item.getUnitGePrice();
			value.stackGeValue = item.getStackGeValue();
			payload.items.add(value);
		}
		if (report.isPet())
		{
			payload.pet = new PetPayload();
			payload.pet.itemId = report.getPetItemId();
			payload.pet.name = report.getPetName();
			payload.pet.awardType = report.getPetAwardType();
		}
		String json = requireGson().toJson(payload);
		if (json.length() > MAX_JSON_LENGTH)
		{
			throw new IllegalArgumentException("Raw event history is too large");
		}
		return json;
	}

	static RareDropReport decode(String json)
	{
		if (json == null || json.trim().isEmpty() || json.length() > MAX_JSON_LENGTH)
		{
			throw new IllegalArgumentException("Raw event history is missing or too large");
		}
		Payload payload;
		try
		{
			payload = requireGson().fromJson(json, Payload.class);
		}
		catch (RuntimeException exception)
		{
			throw new IllegalArgumentException("Raw event history is invalid", exception);
		}
		validateText(payload.eventId, 180);
		validateText(payload.username, 20);
		Instant occurredAt;
		try { occurredAt = Instant.parse(payload.occurredAt); }
		catch (RuntimeException exception) { throw new IllegalArgumentException("Raw event time is invalid", exception); }

		if (RareDropEventType.ITEM_DROP.getWireValue().equals(payload.eventType))
		{
			if (payload.items == null || payload.items.isEmpty() || payload.items.size() > 50)
				throw new IllegalArgumentException("Raw item event is invalid");
			List<RareDropItem> items = new ArrayList<>();
			for (ItemPayload value : payload.items)
			{
				validateText(value.name, 120);
				if (value.itemId < 0 || value.itemId > 1_000_000 || value.quantity <= 0
					|| value.quantity > Integer.MAX_VALUE || value.unitGePrice < 0 || value.stackGeValue < 0)
					throw new IllegalArgumentException("Raw item metadata is invalid");
				items.add(new RareDropItem(value.itemId, value.name, value.quantity,
					value.unitGePrice, value.stackGeValue));
			}
			return RareDropReport.pending(payload.eventId, payload.username, occurredAt,
				Collections.unmodifiableList(items), payload.sourceNpc);
		}

		if (RareDropEventType.PET_OBTAINED.getWireValue().equals(payload.eventType) && payload.pet != null)
		{
			validateText(payload.pet.name, 120);
			RareDropPetDetector.PetAwardType awardType;
			try { awardType = RareDropPetDetector.PetAwardType.valueOf(payload.pet.awardType); }
			catch (RuntimeException exception) { throw new IllegalArgumentException("Raw pet award is invalid", exception); }
			if (payload.pet.itemId != null && (payload.pet.itemId < 0 || payload.pet.itemId > 1_000_000))
				throw new IllegalArgumentException("Raw pet item ID is invalid");
			return RareDropReport.pendingPet(payload.eventId, payload.username, payload.pet.name,
				awardType, occurredAt, payload.sourceNpc)
				.withPetIdentity(payload.pet.itemId, payload.pet.name);
		}
		throw new IllegalArgumentException("Raw event type is invalid");
	}

	private static void validateText(String value, int maximum)
	{
		if (value == null || value.trim().isEmpty() || value.length() > maximum)
			throw new IllegalArgumentException("Raw event text is invalid");
	}

	private static Gson requireGson()
	{
		Gson configured = gson;
		if (configured == null) throw new IllegalStateException("The raw-event codec is not initialized");
		return configured;
	}

	private static final class Payload
	{
		private String eventId;
		private String occurredAt;
		private String username;
		private String eventType;
		private String sourceNpc;
		private List<ItemPayload> items;
		private PetPayload pet;
	}

	private static final class ItemPayload
	{
		private int itemId;
		private String name;
		private long quantity;
		private int unitGePrice;
		private long stackGeValue;
	}

	private static final class PetPayload
	{
		private Integer itemId;
		private String name;
		private String awardType;
	}
}

package com.raredropping;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;

final class RareDropReport
{
	private static final String ITEM_DROP_TYPE = "ITEM";
	private static final String PET_DROP_TYPE = "PET";

	private final String eventId;
	private final String occurredAt;
	private final String username;
	private final String dropType;
	private final String eventType;
	private final String sourceNpc;
	private final List<RareDropItem> items;
	private final Integer petItemId;
	private final String petName;
	private final String petAwardType;
	private final RareDropScreenshot screenshot;

	private RareDropReport(
		String eventId,
		String occurredAt,
		String username,
		String dropType,
		String eventType,
		String sourceNpc,
		List<RareDropItem> items,
		Integer petItemId,
		String petName,
		String petAwardType,
		RareDropScreenshot screenshot)
	{
		this.eventId = eventId;
		this.occurredAt = occurredAt;
		this.username = username;
		this.dropType = dropType;
		this.eventType = eventType;
		this.sourceNpc = normalizeSourceNpc(sourceNpc);
		this.items = Collections.unmodifiableList(new ArrayList<>(items));
		this.petItemId = petItemId;
		this.petName = petName;
		this.petAwardType = petAwardType;
		this.screenshot = screenshot;
	}

	static RareDropReport pending(String username, Instant occurredAt, List<RareDropItem> items)
	{
		return pending(UUID.randomUUID().toString(), username, occurredAt, items, null);
	}

	static RareDropReport pending(String eventId, String username, Instant occurredAt, List<RareDropItem> items)
	{
		return pending(eventId, username, occurredAt, items, null);
	}

	static RareDropReport pending(
		String eventId,
		String username,
		Instant occurredAt,
		List<RareDropItem> items,
		String sourceNpc)
	{
		return pendingItem(
			eventId,
			username,
			occurredAt,
			items,
			RareDropEventType.ITEM_DROP,
			sourceNpc);
	}

	private static RareDropReport pendingItem(
		String eventId,
		String username,
		Instant occurredAt,
		List<RareDropItem> items,
		RareDropEventType eventType,
		String sourceNpc)
	{
		return new RareDropReport(
			eventId,
			occurredAt.toString(),
			username,
			ITEM_DROP_TYPE,
			eventType.getWireValue(),
			sourceNpc,
			items,
			null,
			null,
			null,
			null);
	}

	static RareDropReport pendingPet(
		String username,
		String petName,
		RareDropPetDetector.PetAwardType awardType,
		Instant occurredAt)
	{
		return pendingPet(UUID.randomUUID().toString(), username, petName, awardType, occurredAt, null);
	}

	static RareDropReport pendingPet(
		String eventId,
		String username,
		String petName,
		RareDropPetDetector.PetAwardType awardType,
		Instant occurredAt)
	{
		return pendingPet(eventId, username, petName, awardType, occurredAt, null);
	}

	static RareDropReport pendingPet(
		String eventId,
		String username,
		String petName,
		RareDropPetDetector.PetAwardType awardType,
		Instant occurredAt,
		String sourceNpc)
	{
		String normalizedName = petName == null || petName.trim().isEmpty() ? "Pet" : petName.trim();
		String normalizedAwardType = awardType == null ? "UNKNOWN" : awardType.name();
		return new RareDropReport(
			eventId,
			occurredAt.toString(),
			username,
			PET_DROP_TYPE,
			RareDropEventType.PET_OBTAINED.getWireValue(),
			sourceNpc,
			Collections.emptyList(),
			null,
			normalizedName,
			normalizedAwardType,
			null);
	}

	RareDropReport withScreenshot(RareDropScreenshot screenshot)
	{
		return new RareDropReport(
			eventId,
			occurredAt,
			username,
			dropType,
			eventType,
			sourceNpc,
			items,
			petItemId,
			petName,
			petAwardType,
			screenshot);
	}

	RareDropReport withItems(List<RareDropItem> filteredItems)
	{
		if (filteredItems == null)
		{
			throw new IllegalArgumentException("Filtered drop items are required");
		}
		return new RareDropReport(
			eventId,
			occurredAt,
			username,
			dropType,
			eventType,
			sourceNpc,
			filteredItems,
			petItemId,
			petName,
			petAwardType,
			screenshot);
	}

	RareDropReport withPetIdentity(Integer resolvedItemId, String resolvedPetName)
	{
		if (!isPet())
		{
			return this;
		}
		String normalizedName = resolvedPetName == null || resolvedPetName.trim().isEmpty()
			? petName
			: resolvedPetName.trim();
		return new RareDropReport(
			eventId,
			occurredAt,
			username,
			dropType,
			eventType,
			sourceNpc,
			items,
			resolvedItemId,
			normalizedName,
			petAwardType,
			screenshot);
	}

	String getEventId()
	{
		return eventId;
	}

	String getOccurredAt()
	{
		return occurredAt;
	}

	String getUsername()
	{
		return username;
	}

	String getDropType()
	{
		return dropType;
	}

	String getEventType()
	{
		return eventType;
	}

	String getSourceNpc()
	{
		return sourceNpc;
	}

	List<RareDropItem> getItems()
	{
		return items;
	}

	String getPetName()
	{
		return petName;
	}

	Integer getPetItemId()
	{
		return petItemId;
	}

	String getPetAwardType()
	{
		return petAwardType;
	}

	boolean isPet()
	{
		return PET_DROP_TYPE.equals(dropType);
	}

	RareDropScreenshot getScreenshot()
	{
		return screenshot;
	}

	private static String normalizeSourceNpc(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return null;
		}
		String normalized = value.trim();
		if (normalized.length() > RareDropSubmission.MAX_SOURCE_NPC_LENGTH)
		{
			return normalized.substring(0, RareDropSubmission.MAX_SOURCE_NPC_LENGTH);
		}
		return normalized;
	}
}

package com.raredropping;

final class RareDropScreenshot
{
	private final String mediaType;
	private final byte[] data;
	private final int width;
	private final int height;

	RareDropScreenshot(String mediaType, byte[] data, int width, int height)
	{
		if (mediaType == null || data == null || data.length == 0
			|| data.length > RareDropScreenshotEncoder.MAX_SCREENSHOT_BYTES
			|| width <= 0 || height <= 0)
		{
			throw new IllegalArgumentException("Invalid rare-drop screenshot");
		}
		this.mediaType = mediaType;
		this.data = data.clone();
		this.width = width;
		this.height = height;
	}

	String getMediaType()
	{
		return mediaType;
	}

	byte[] copyData()
	{
		return data.clone();
	}

	int getByteLength()
	{
		return data.length;
	}

	int getWidth()
	{
		return width;
	}

	int getHeight()
	{
		return height;
	}
}

package com.raredropping;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Iterator;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.MemoryCacheImageOutputStream;

final class RareDropScreenshotEncoder
{
	static final int MAX_SCREENSHOT_BYTES = 1_000_000;
	private static final String MEDIA_TYPE = "image/jpeg";
	private static final float MIN_QUALITY = 0.35f;
	private static final float MAX_QUALITY = 0.92f;
	private static final int QUALITY_SEARCH_STEPS = 7;

	private final int maximumBytes;

	RareDropScreenshotEncoder()
	{
		this(MAX_SCREENSHOT_BYTES);
	}

	RareDropScreenshotEncoder(int maximumBytes)
	{
		if (maximumBytes <= 0)
		{
			throw new IllegalArgumentException("maximumBytes must be positive");
		}
		this.maximumBytes = maximumBytes;
	}

	RareDropScreenshot encode(BufferedImage source) throws IOException
	{
		if (source == null || source.getWidth() <= 0 || source.getHeight() <= 0)
		{
			throw new IOException("Screenshot image is empty");
		}

		BufferedImage current = toRgb(source);
		while (true)
		{
			byte[] highQuality = encodeJpeg(current, MAX_QUALITY);
			if (highQuality.length <= maximumBytes)
			{
				return screenshot(highQuality, current);
			}

			byte[] lowQuality = encodeJpeg(current, MIN_QUALITY);
			if (lowQuality.length <= maximumBytes)
			{
				byte[] best = findHighestQuality(current, lowQuality);
				return screenshot(best, current);
			}

			if (current.getWidth() == 1 && current.getHeight() == 1)
			{
				throw new IOException("Unable to encode screenshot within byte limit");
			}

			double estimatedScale = Math.sqrt((double) maximumBytes / lowQuality.length) * 0.92d;
			double scale = Math.max(0.50d, Math.min(0.90d, estimatedScale));
			int width = Math.max(1, (int) Math.floor(current.getWidth() * scale));
			int height = Math.max(1, (int) Math.floor(current.getHeight() * scale));
			if (width == current.getWidth() && width > 1)
			{
				width--;
			}
			if (height == current.getHeight() && height > 1)
			{
				height--;
			}
			current = resize(current, width, height);
		}
	}

	private byte[] findHighestQuality(BufferedImage image, byte[] initialBest) throws IOException
	{
		byte[] best = initialBest;
		float lower = MIN_QUALITY;
		float upper = MAX_QUALITY;
		for (int step = 0; step < QUALITY_SEARCH_STEPS; step++)
		{
			float quality = (lower + upper) / 2f;
			byte[] candidate = encodeJpeg(image, quality);
			if (candidate.length <= maximumBytes)
			{
				best = candidate;
				lower = quality;
			}
			else
			{
				upper = quality;
			}
		}
		return best;
	}

	private static RareDropScreenshot screenshot(byte[] data, BufferedImage image) throws IOException
	{
		if (data.length > MAX_SCREENSHOT_BYTES)
		{
			throw new IOException("Encoded screenshot exceeds hard byte limit");
		}
		return new RareDropScreenshot(MEDIA_TYPE, data, image.getWidth(), image.getHeight());
	}

	private static BufferedImage toRgb(BufferedImage source)
	{
		if (source.getType() == BufferedImage.TYPE_INT_RGB)
		{
			return source;
		}

		BufferedImage rgb = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = rgb.createGraphics();
		graphics.setColor(Color.BLACK);
		graphics.fillRect(0, 0, rgb.getWidth(), rgb.getHeight());
		graphics.drawImage(source, 0, 0, null);
		graphics.dispose();
		return rgb;
	}

	private static BufferedImage resize(BufferedImage source, int width, int height)
	{
		BufferedImage resized = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = resized.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		graphics.drawImage(source, 0, 0, width, height, null);
		graphics.dispose();
		return resized;
	}

	private static byte[] encodeJpeg(BufferedImage image, float quality) throws IOException
	{
		Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpeg");
		if (!writers.hasNext())
		{
			throw new IOException("No JPEG writer is available");
		}

		ImageWriter writer = writers.next();
		try (ByteArrayOutputStream output = new ByteArrayOutputStream();
			 MemoryCacheImageOutputStream imageOutput = new MemoryCacheImageOutputStream(output))
		{
			ImageWriteParam parameters = writer.getDefaultWriteParam();
			parameters.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			parameters.setCompressionQuality(quality);
			writer.setOutput(imageOutput);
			writer.write(null, new IIOImage(image, null, null), parameters);
			imageOutput.flush();
			return output.toByteArray();
		}
		finally
		{
			writer.dispose();
		}
	}
}

package com.raredropping;

final class RareDropSubmission
{
	static final int MAX_ITEM_DROP_LENGTH = 180;
	static final int MAX_SOURCE_NPC_LENGTH = 120;

	private final String eventId;
	private final String occurredAt;
	private final String username;
	private final String itemDrop;
	private final String eventType;
	private final String sourceNpc;
	private final int tilePosition;
	private final boolean markComplete;
	private final RareDropScreenshot screenshot;
	private final RareDropReport rawReport;

	static RareDropSubmission forPendingPreflight(
		RareDropReport report,
		RareDropScreenshot screenshot)
	{
		if (report == null || screenshot == null)
		{
			throw new IllegalArgumentException("A raw bingo event is required");
		}
		return new RareDropSubmission(
			report.getEventId(),
			report.getOccurredAt(),
			report.getUsername(),
			description(report),
			report.getEventType(),
			report.getSourceNpc(),
			0,
			false,
			screenshot,
			report);
	}

	static RareDropSubmission forServerMatch(
		RareDropReport report,
		RareDropScreenshot screenshot,
		RareDropWebhookClient.TileMatch match)
	{
		if (report == null || screenshot == null || match == null)
		{
			throw new IllegalArgumentException("A matched bingo event is required");
		}
		return new RareDropSubmission(
			report.getEventId(),
			report.getOccurredAt(),
			report.getUsername(),
			description(report),
			report.getEventType(),
			report.getSourceNpc(),
			match.getTilePosition(),
			false,
			screenshot,
			report);
	}

	RareDropSubmission(
		String eventId,
		String occurredAt,
		String username,
		String itemDrop,
		int tilePosition,
		boolean markComplete,
		RareDropScreenshot screenshot)
	{
		this(
			eventId,
			occurredAt,
			username,
			itemDrop,
			RareDropEventType.ITEM_DROP.getWireValue(),
			null,
			tilePosition,
			markComplete,
			screenshot,
			null);
	}

	RareDropSubmission(
		String eventId,
		String occurredAt,
		String username,
		String itemDrop,
		String eventType,
		String sourceNpc,
		int tilePosition,
		boolean markComplete,
		RareDropScreenshot screenshot)
	{
		this(
			eventId,
			occurredAt,
			username,
			itemDrop,
			eventType,
			sourceNpc,
			tilePosition,
			markComplete,
			screenshot,
			null);
	}

	RareDropSubmission(
		String eventId,
		String occurredAt,
		String username,
		String itemDrop,
		String eventType,
		String sourceNpc,
		int tilePosition,
		boolean markComplete,
		RareDropScreenshot screenshot,
		RareDropReport rawReport)
	{
		String normalizedEventType = normalizeEventType(eventType);
		String normalizedSourceNpc = normalizeSourceNpc(sourceNpc);
		if (eventId == null || eventId.trim().isEmpty() || eventId.length() > 180
			|| occurredAt == null || occurredAt.trim().isEmpty()
			|| username == null || username.trim().isEmpty()
			|| itemDrop == null || itemDrop.trim().isEmpty() || itemDrop.length() > MAX_ITEM_DROP_LENGTH
			|| tilePosition < 0 || tilePosition > 25
			|| (tilePosition == 0 && rawReport == null)
			|| (rawReport != null && !eventId.equals(rawReport.getEventId()))
			|| screenshot == null)
		{
			throw new IllegalArgumentException("Invalid bingo drop submission");
		}
		this.eventId = eventId;
		this.occurredAt = occurredAt;
		this.username = username;
		this.itemDrop = itemDrop;
		this.eventType = normalizedEventType;
		this.sourceNpc = normalizedSourceNpc;
		this.tilePosition = tilePosition;
		this.markComplete = markComplete;
		this.screenshot = screenshot;
		this.rawReport = rawReport;
	}

	String getEventId()
	{
		return eventId;
	}

	String getOccurredAt()
	{
		return occurredAt;
	}

	String getUsername()
	{
		return username;
	}

	String getItemDrop()
	{
		return itemDrop;
	}

	String getEventType()
	{
		return eventType;
	}

	String getSourceNpc()
	{
		return sourceNpc;
	}

	int getTilePosition()
	{
		return tilePosition;
	}

	boolean isMarkComplete()
	{
		return markComplete;
	}

	RareDropScreenshot getScreenshot()
	{
		return screenshot;
	}

	RareDropReport getRawReport()
	{
		return rawReport;
	}

	private static String normalizeEventType(String value)
	{
		RareDropEventType type = RareDropEventType.fromWireValue(value);
		return type == null ? null : type.getWireValue();
	}

	private static String normalizeSourceNpc(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return null;
		}
		String normalized = value.trim();
		if (normalized.length() > MAX_SOURCE_NPC_LENGTH)
		{
			throw new IllegalArgumentException("Invalid bingo drop NPC source");
		}
		return normalized;
	}

	private static String description(RareDropReport report)
	{
		StringBuilder value = new StringBuilder();
		if (report.isPet())
		{
			value.append("Pet: ").append(text(report.getPetName(), "name unavailable"));
			if (report.getPetItemId() != null)
			{
				value.append(" (item ").append(report.getPetItemId()).append(')');
			}
		}
		else
		{
			for (RareDropItem item : report.getItems())
			{
				if (value.length() > 0)
				{
					value.append(", ");
				}
				value.append(text(item.getName(), "Item " + item.getItemId()))
					.append(" x").append(item.getQuantity())
					.append(" (item ").append(item.getItemId()).append(')');
			}
		}
		String description = value.length() == 0 ? "Bingo event" : value.toString();
		return description.length() <= MAX_ITEM_DROP_LENGTH
			? description
			: description.substring(0, MAX_ITEM_DROP_LENGTH - 3) + "...";
	}

	private static String text(String value, String fallback)
	{
		return value == null || value.trim().isEmpty() ? fallback : value.trim();
	}
}

package com.raredropping;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/** Board-agnostic transport for the fixed Exodus Bingo service. */
@Slf4j
final class RareDropWebhookClient implements AutoCloseable
{
	private static final int MAX_ATTEMPTS = 3;
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String PRODUCTION_HOST = "exodus-prime-bingo.vercel.app";
	private static final String PAIR_START_PATH = "/api/v2/integrations/runelite/pair/start";
	private static final String PAIR_POLL_PATH = "/api/v2/integrations/runelite/pair/poll";
	private static final String PREFLIGHT_PATH = "/api/v2/integrations/runelite/events/preflight";
	private static final String PROOF_PATH = "/api/v2/integrations/runelite/events/proof";

	private final OkHttpClient okHttpClient;
	private final ScheduledExecutorService scheduler;
	private final HttpUrl baseUrl;
	private final Gson gson;
	private final Set<Call> activeCalls = Collections.synchronizedSet(new HashSet<>());
	private final Set<ScheduledFuture<?>> scheduledRetries = Collections.synchronizedSet(new HashSet<>());
	private volatile boolean closed;

	RareDropWebhookClient(OkHttpClient okHttpClient, ScheduledExecutorService scheduler, Gson gson)
	{
		this(okHttpClient, scheduler, gson, RareDropPingConfig.PRODUCTION_BASE_URL);
	}

	/** Package-private override exists only for local development and tests. */
	RareDropWebhookClient(OkHttpClient okHttpClient, ScheduledExecutorService scheduler, Gson gson,
		String baseUrl)
	{
		HttpUrl parsedBaseUrl = parseAllowedBaseUrl(baseUrl);
		if (okHttpClient == null || scheduler == null || gson == null || parsedBaseUrl == null)
		{
			throw new IllegalArgumentException("Invalid Exodus Bingo client configuration");
		}
		this.okHttpClient = okHttpClient.newBuilder()
			.followRedirects(false)
			.followSslRedirects(false)
			.build();
		this.scheduler = scheduler;
		this.baseUrl = parsedBaseUrl;
		this.gson = gson;
	}

	void startPairing(String characterName, String deviceName, ResultListener<PairStartResult> listener)
	{
		JsonObject body = new JsonObject();
		body.addProperty("characterName", characterName == null ? "" : characterName.trim());
		body.addProperty("deviceName", deviceName == null ? "Exodus Bingo for RuneLite" : deviceName.trim());
		executeJson(
			request(PAIR_START_PATH).post(RequestBody.create(JSON, gson.toJson(body))).build(),
			null,
			false,
			new ResponseParser<PairStartResult>()
			{
				@Override public PairStartResult parse(Response response, JsonObject json)
				{
					return PairStartResult.from(response.code(), json, baseUrl);
				}
				@Override public PairStartResult failed(String eventId, int statusCode) { return PairStartResult.failed(statusCode); }
			},
			listener,
			1);
	}

	void pollPairing(String deviceCode, ResultListener<PairPollResult> listener)
	{
		HttpUrl url = url(PAIR_POLL_PATH).newBuilder()
			.addQueryParameter("deviceCode", deviceCode == null ? "" : deviceCode.trim())
			.build();
		executeJson(
			new Request.Builder().url(url).header("Accept", "application/json").get().build(),
			null,
			false,
			new ResponseParser<PairPollResult>()
			{
				@Override public PairPollResult parse(Response response, JsonObject json) { return PairPollResult.from(response.code(), json); }
				@Override public PairPollResult failed(String eventId, int statusCode) { return PairPollResult.failed(statusCode); }
			},
			listener,
			1);
	}

	void preflight(String deviceToken, RareDropReport report, ResultListener<PreflightResult> listener)
	{
		if (report == null)
		{
			notifyListener(listener, PreflightResult.failed(0));
			return;
		}
		Request request;
		try
		{
			request = authorized(request(PREFLIGHT_PATH), deviceToken)
				.header("Idempotency-Key", report.getEventId())
				.post(RequestBody.create(JSON, gson.toJson(RawEventPayload.from(report))))
				.build();
		}
		catch (IllegalArgumentException exception)
		{
			notifyListener(listener, PreflightResult.failed(0));
			return;
		}
		executeJson(request, report.getEventId(), true,
			new ResponseParser<PreflightResult>()
			{
				@Override public PreflightResult parse(Response response, JsonObject json) { return PreflightResult.from(response.code(), json); }
				@Override public PreflightResult failed(String eventId, int statusCode) { return PreflightResult.failed(statusCode); }
			}, listener, 1);
	}

	void sendProof(String deviceToken, String eventId, RareDropScreenshot screenshot,
		ResultListener<ProofResult> listener)
	{
		if (eventId == null || eventId.trim().isEmpty() || screenshot == null)
		{
			notifyListener(listener, ProofResult.failed(eventId, 0));
			return;
		}
		MediaType screenshotType = MediaType.parse(screenshot.getMediaType());
		if (screenshotType == null)
		{
			notifyListener(listener, ProofResult.failed(eventId, 0));
			return;
		}
		MultipartBody body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("eventId", eventId)
			.addFormDataPart("screenshot", "drop.jpg", RequestBody.create(screenshotType, screenshot.copyData()))
			.build();
		Request request;
		try
		{
			request = authorized(request(PROOF_PATH), deviceToken)
				.header("Idempotency-Key", eventId)
				.post(body)
				.build();
		}
		catch (IllegalArgumentException exception)
		{
			notifyListener(listener, ProofResult.failed(eventId, 0));
			return;
		}
		executeJson(request, eventId, true,
			new ResponseParser<ProofResult>()
			{
				@Override public ProofResult parse(Response response, JsonObject json) { return ProofResult.from(eventId, response.code(), json); }
				@Override public ProofResult failed(String ignored, int statusCode) { return ProofResult.failed(eventId, statusCode); }
			}, listener, 1);
	}

	static boolean isAllowedBaseUrl(String value)
	{
		return parseAllowedBaseUrl(value) != null;
	}

	private Request.Builder request(String path)
	{
		return new Request.Builder().url(url(path)).header("Accept", "application/json");
	}

	private static Request.Builder authorized(Request.Builder builder, String deviceToken)
	{
		return builder.header("Authorization", "Bearer " + (deviceToken == null ? "" : deviceToken.trim()));
	}

	private HttpUrl url(String path)
	{
		return baseUrl.newBuilder().encodedPath(path).query(null).fragment(null).build();
	}

	private <T extends HttpResult> void executeJson(Request request, String eventId, boolean retryableRequest,
		ResponseParser<T> parser, ResultListener<T> listener, int attempt)
	{
		if (closed)
		{
			notifyListener(listener, parser.failed(eventId, 0));
			return;
		}
		Call call = okHttpClient.newCall(request);
		activeCalls.add(call);
		if (closed && activeCalls.remove(call))
		{
			call.cancel();
			return;
		}
		call.enqueue(new Callback()
		{
			@Override public void onFailure(Call failedCall, IOException exception)
			{
				activeCalls.remove(failedCall);
				if (closed || failedCall.isCanceled()) return;
				if (!retryableRequest || attempt >= MAX_ATTEMPTS
					|| !scheduleRetry(() -> executeJson(request, eventId, true, parser, listener, attempt + 1), attempt + 1))
				{
					notifyListener(listener, parser.failed(eventId, 0));
				}
			}

			@Override public void onResponse(Call completedCall, Response response)
			{
				activeCalls.remove(completedCall);
				try (Response ignored = response)
				{
					int statusCode = response.code();
					if (retryableRequest && isRetryable(statusCode) && attempt < MAX_ATTEMPTS)
					{
						if (!scheduleRetry(() -> executeJson(request, eventId, true, parser, listener, attempt + 1), attempt + 1))
							notifyListener(listener, parser.failed(eventId, statusCode));
						return;
					}
					notifyListener(listener, parser.parse(response, readJsonObject(response)));
				}
				catch (IOException | RuntimeException exception)
				{
					notifyListener(listener, parser.failed(eventId, response.code()));
				}
			}
		});
	}

	private boolean scheduleRetry(Runnable operation, int attempt)
	{
		if (closed || attempt > MAX_ATTEMPTS) return false;
		long delaySeconds = 1L << Math.max(0, attempt - 2);
		try
		{
			final ScheduledFuture<?>[] holder = new ScheduledFuture<?>[1];
			holder[0] = scheduler.schedule(() ->
			{
				scheduledRetries.remove(holder[0]);
				operation.run();
			}, delaySeconds, TimeUnit.SECONDS);
			scheduledRetries.add(holder[0]);
			return true;
		}
		catch (RejectedExecutionException exception)
		{
			return false;
		}
	}

	private static boolean isRetryable(int statusCode)
	{
		return statusCode == 408 || statusCode == 429 || statusCode >= 500;
	}

	private static JsonObject readJsonObject(Response response) throws IOException
	{
		String body = BoundedHttpBody.readUtf8(response.body());
		if (body.trim().isEmpty()) return new JsonObject();
		JsonElement parsed = new JsonParser().parse(body);
		return parsed.isJsonObject() ? parsed.getAsJsonObject() : new JsonObject();
	}

	private static HttpUrl parseAllowedBaseUrl(String value)
	{
		if (value == null || value.trim().isEmpty()) return null;
		HttpUrl url = HttpUrl.parse(value.trim());
		if (url == null || !url.username().isEmpty() || !url.password().isEmpty()
			|| !"/".equals(url.encodedPath()) || url.query() != null || url.fragment() != null) return null;
		boolean production = "https".equalsIgnoreCase(url.scheme())
			&& PRODUCTION_HOST.equalsIgnoreCase(url.host()) && url.port() == 443;
		String host = url.host().toLowerCase(Locale.ROOT);
		boolean loopback = "localhost".equals(host) || "127.0.0.1".equals(host) || "::1".equals(host);
		return production || (loopback && ("http".equalsIgnoreCase(url.scheme()) || "https".equalsIgnoreCase(url.scheme())))
			? url : null;
	}

	static boolean isAllowedPairingVerificationUrl(String value, String userCode)
	{
		return isAllowedPairingVerificationUrl(value, userCode,
			HttpUrl.parse(RareDropPingConfig.PRODUCTION_BASE_URL));
	}

	private static boolean isAllowedPairingVerificationUrl(String value, String userCode,
		HttpUrl expectedOrigin)
	{
		if (value == null || userCode == null || userCode.trim().isEmpty() || expectedOrigin == null)
			return false;
		HttpUrl url = HttpUrl.parse(value.trim());
		return url != null
			&& expectedOrigin.scheme().equalsIgnoreCase(url.scheme())
			&& expectedOrigin.host().equalsIgnoreCase(url.host())
			&& expectedOrigin.port() == url.port()
			&& url.username().isEmpty()
			&& url.password().isEmpty()
			&& "/runelite/pair".equals(url.encodedPath())
			&& url.fragment() == null
			&& url.queryParameterNames().size() == 1
			&& url.queryParameterNames().contains("code")
			&& url.queryParameterValues("code").size() == 1
			&& userCode.trim().equals(url.queryParameter("code"));
	}

	private static String string(JsonObject json, String... names)
	{
		for (String name : names)
		{
			JsonElement value = json.get(name);
			if (value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()) return value.getAsString();
		}
		return null;
	}

	private static boolean bool(JsonObject json, String name, boolean fallback)
	{
		try { return json.has(name) ? json.get(name).getAsBoolean() : fallback; }
		catch (RuntimeException ignored) { return fallback; }
	}

	private static int integer(JsonObject json, int fallback, String... names)
	{
		for (String name : names)
		{
			try { if (json.has(name)) return json.get(name).getAsInt(); }
			catch (RuntimeException ignored) { }
		}
		return fallback;
	}

	private static List<TileMatch> matches(JsonObject json)
	{
		JsonArray values = json.has("matches") && json.get("matches").isJsonArray()
			? json.getAsJsonArray("matches") : new JsonArray();
		List<TileMatch> result = new ArrayList<>();
		for (JsonElement value : values)
		{
			if (!value.isJsonObject()) continue;
			JsonObject match = value.getAsJsonObject();
			String competitionId = string(match, "competitionId");
			String tileId = string(match, "tileId");
			int position = integer(match, 0, "tilePosition", "position");
			if (competitionId != null && tileId != null && position > 0)
				result.add(new TileMatch(competitionId, tileId, position, string(match, "title", "tileTitle")));
		}
		return Collections.unmodifiableList(result);
	}

	private static <T> void notifyListener(ResultListener<T> listener, T result)
	{
		if (listener == null) return;
		try { listener.onResult(result); }
		catch (RuntimeException exception) { log.debug("RuneLite API listener failed ({})", exception.getClass().getSimpleName()); }
	}

	@Override public void close()
	{
		closed = true;
		List<Call> calls;
		synchronized (activeCalls) { calls = new ArrayList<>(activeCalls); activeCalls.clear(); }
		for (Call call : calls) call.cancel();
		List<ScheduledFuture<?>> retries;
		synchronized (scheduledRetries) { retries = new ArrayList<>(scheduledRetries); scheduledRetries.clear(); }
		for (ScheduledFuture<?> retry : retries) retry.cancel(false);
	}

	interface ResultListener<T> { void onResult(T result); }
	private interface HttpResult { int getStatusCode(); }
	private interface ResponseParser<T extends HttpResult>
	{
		T parse(Response response, JsonObject json);
		T failed(String eventId, int statusCode);
	}

	static final class PairStartResult implements HttpResult
	{
		private final boolean accepted;
		private final int statusCode;
		private final String deviceCode;
		private final String userCode;
		private final String verificationUrl;
		private final int expiresInSeconds;
		private final int pollIntervalSeconds;
		private PairStartResult(boolean accepted, int statusCode, String deviceCode, String userCode,
			String verificationUrl, int expiresInSeconds, int pollIntervalSeconds)
		{
			this.accepted = accepted; this.statusCode = statusCode; this.deviceCode = deviceCode;
			this.userCode = userCode; this.verificationUrl = verificationUrl;
			this.expiresInSeconds = expiresInSeconds; this.pollIntervalSeconds = pollIntervalSeconds;
		}
		private static PairStartResult from(int statusCode, JsonObject json, HttpUrl expectedOrigin)
		{
			String deviceCode = string(json, "deviceCode", "device_code");
			String userCode = string(json, "userCode", "user_code", "code");
			String verificationUrl = string(json, "verificationUrl", "verificationUri", "verification_uri");
			boolean accepted = (statusCode == 200 || statusCode == 201)
				&& deviceCode != null && userCode != null
				&& isAllowedPairingVerificationUrl(verificationUrl, userCode, expectedOrigin);
			return new PairStartResult(accepted, statusCode, deviceCode, userCode, verificationUrl,
				integer(json, 600, "expiresIn", "expiresInSeconds", "expires_in"),
				Math.max(2, integer(json, 3, "pollInterval", "pollIntervalSeconds", "interval")));
		}
		static PairStartResult failed(int statusCode) { return new PairStartResult(false, statusCode, null, null, null, 0, 3); }
		boolean isAccepted() { return accepted; }
		@Override public int getStatusCode() { return statusCode; }
		String getDeviceCode() { return deviceCode; }
		String getUserCode() { return userCode; }
		String getVerificationUrl() { return verificationUrl; }
		int getExpiresInSeconds() { return expiresInSeconds; }
		int getPollIntervalSeconds() { return pollIntervalSeconds; }
	}

	static final class PairPollResult implements HttpResult
	{
		private final String status;
		private final int statusCode;
		private final String deviceToken;
		private final String characterName;
		private PairPollResult(String status, int statusCode, String deviceToken, String characterName)
		{ this.status = status; this.statusCode = statusCode; this.deviceToken = deviceToken; this.characterName = characterName; }
		private static PairPollResult from(int statusCode, JsonObject json)
		{
			String token = string(json, "deviceToken", "device_token", "token");
			String status = string(json, "status");
			if (token != null && (status == null || status.trim().isEmpty())) status = "approved";
			return new PairPollResult(status == null ? (statusCode == 202 ? "pending" : "failed") : status.toLowerCase(Locale.ROOT),
				statusCode, token, string(json, "characterName", "character"));
		}
		static PairPollResult failed(int statusCode) { return new PairPollResult("failed", statusCode, null, null); }
		boolean isPending() { return "pending".equals(status) || "authorization_pending".equals(status); }
		boolean isApproved() { return "approved".equals(status) && deviceToken != null && !deviceToken.trim().isEmpty(); }
		boolean isTerminal() { return !isPending() && !isApproved(); }
		String getStatus() { return status; }
		@Override public int getStatusCode() { return statusCode; }
		String getDeviceToken() { return deviceToken; }
		String getCharacterName() { return characterName; }
	}

	static final class TileMatch
	{
		private final String competitionId;
		private final String tileId;
		private final int tilePosition;
		private final String title;
		private TileMatch(String competitionId, String tileId, int tilePosition, String title)
		{ this.competitionId = competitionId; this.tileId = tileId; this.tilePosition = tilePosition; this.title = title == null ? "Tile " + tilePosition : title; }
		String getCompetitionId() { return competitionId; }
		String getTileId() { return tileId; }
		int getTilePosition() { return tilePosition; }
		String getTitle() { return title; }
	}

	static final class PreflightResult implements HttpResult
	{
		private final boolean accepted;
		private final boolean duplicate;
		private final int statusCode;
		private final List<TileMatch> matches;
		private PreflightResult(boolean accepted, boolean duplicate, int statusCode, List<TileMatch> matches)
		{ this.accepted = accepted; this.duplicate = duplicate; this.statusCode = statusCode; this.matches = matches; }
		private static PreflightResult from(int statusCode, JsonObject json)
		{
			boolean duplicate = bool(json, "duplicate", false);
			boolean accepted = (statusCode == 200 || statusCode == 201 || (statusCode == 409 && duplicate))
				&& bool(json, "accepted", true);
			return new PreflightResult(accepted, duplicate, statusCode, matches(json));
		}
		static PreflightResult failed(int statusCode) { return new PreflightResult(false, false, statusCode, Collections.emptyList()); }
		boolean isAccepted() { return accepted; }
		boolean isDuplicate() { return duplicate; }
		@Override public int getStatusCode() { return statusCode; }
		List<TileMatch> getMatches() { return matches; }
	}

	static final class ProofResult implements HttpResult
	{
		private final String eventId;
		private final boolean accepted;
		private final boolean duplicate;
		private final int statusCode;
		private final List<TileMatch> matches;
		private ProofResult(String eventId, boolean accepted, boolean duplicate, int statusCode, List<TileMatch> matches)
		{ this.eventId = eventId; this.accepted = accepted; this.duplicate = duplicate; this.statusCode = statusCode; this.matches = matches; }
		private static ProofResult from(String eventId, int statusCode, JsonObject json)
		{
			boolean duplicate = bool(json, "duplicate", false);
			boolean accepted = (statusCode == 200 || statusCode == 201 || (statusCode == 409 && duplicate))
				&& bool(json, "accepted", true);
			return new ProofResult(eventId, accepted, duplicate, statusCode, matches(json));
		}
		static ProofResult failed(String eventId, int statusCode) { return new ProofResult(eventId, false, false, statusCode, Collections.emptyList()); }
		String getEventId() { return eventId; }
		boolean isAccepted() { return accepted; }
		boolean isDuplicate() { return duplicate; }
		@Override public int getStatusCode() { return statusCode; }
		List<TileMatch> getMatches() { return matches; }
	}

	private static final class RawEventPayload
	{
		private final String eventId;
		private final String occurredAt;
		private final String characterName;
		private final String eventType;
		private final String sourceNpc;
		private final List<RawItemPayload> items;
		private final RawPetPayload pet;
		private RawEventPayload(String eventId, String occurredAt, String characterName, String eventType,
			String sourceNpc, List<RawItemPayload> items, RawPetPayload pet)
		{ this.eventId = eventId; this.occurredAt = occurredAt; this.characterName = characterName; this.eventType = eventType; this.sourceNpc = sourceNpc; this.items = items; this.pet = pet; }
		private static RawEventPayload from(RareDropReport report)
		{
			List<RawItemPayload> items = new ArrayList<>();
			for (RareDropItem item : report.getItems()) items.add(new RawItemPayload(item));
			RawPetPayload pet = report.isPet() ? new RawPetPayload(report.getPetItemId(), report.getPetName(), report.getPetAwardType()) : null;
			return new RawEventPayload(report.getEventId(), report.getOccurredAt(), report.getUsername(), report.getEventType(), report.getSourceNpc(), items, pet);
		}
	}

	private static final class RawItemPayload
	{
		private final int itemId;
		private final String name;
		private final long quantity;
		private final int unitGePrice;
		private final long stackGeValue;
		private RawItemPayload(RareDropItem item)
		{ itemId = item.getItemId(); name = item.getName(); quantity = item.getQuantity(); unitGePrice = item.getUnitGePrice(); stackGeValue = item.getStackGeValue(); }
	}

	private static final class RawPetPayload
	{
		private final Integer itemId;
		private final String name;
		private final String awardType;
		private RawPetPayload(Integer itemId, String name, String awardType)
		{ this.itemId = itemId; this.name = name; this.awardType = awardType; }
	}
}

