	private static BingoSidebarData.Catalog catalog(String... names)
	{
		BingoSidebarData.CompetitionSummary[] summaries = new BingoSidebarData.CompetitionSummary[names.length];
		for (int index = 0; index < names.length; index++)
		{
			String id = index == 0 ? COMPETITION_ID : SECOND_COMPETITION_ID;
			summaries[index] = summary(id, names[index], 7);
		}
		return new BingoSidebarData.Catalog("Ayra", "Ayra", Arrays.asList(summaries), COMPETITION_ID);
	}

	private static BingoSidebarData.Board board(String name, BingoSidebarData.Tile... tiles)
	{
		int completed = 0;
		for (BingoSidebarData.Tile tile : tiles) if (tile.done) completed++;
		return new BingoSidebarData.Board(summary(COMPETITION_ID, name, completed), "claim-1", "Ayra",
			Collections.singletonList(new BingoSidebarData.Member("member-1", "Drew")), Arrays.asList(tiles));
	}

	private static BingoSidebarData.CompetitionSummary summary(String id, String name, int completed)
	{
		return new BingoSidebarData.CompetitionSummary(id, name, "Prime", "2026-08-23T00:00:00Z",
			"2026-10-23T00:00:00Z", completed, 25, "claim-1");
	}

	private static BingoSidebarData.Tile tile(String id, int position, boolean done, double percent)
	{
		return tile(id, position, done, percent, "Tile " + position);
	}

	private static BingoSidebarData.Tile tile(
		String id, int position, boolean done, double percent, String title)
	{
		double current = percent <= 0d ? 0d : Math.min(2d, Math.max(1d, percent / 50d));
		BingoSidebarData.Requirement requirement = new BingoSidebarData.Requirement(
			"<script>tile</script>", "runelite_event", 2d, "drops", "team_sum",
			true, false, current, percent);
		BingoSidebarData.Requirement supporting = new BingoSidebarData.Requirement(
			"Supporting proof", "manual_boolean", 1d, "proof", "any_participant",
			false, true, 0d, 0d);
		BingoSidebarData.MemberProgress memberProgress = new BingoSidebarData.MemberProgress(
			"<script>tile</script>", "member-1", "Drew", "Ayra", current, "drops", "runelite");
		return new BingoSidebarData.Tile(id, position, title, "Tile", "Short description for this task.",
			null, "any", done, done ? "2026-08-23T16:00:00Z" : null,
			done ? "Drew" : null, done ? "Ayra" : null, false, 1,
			new BingoSidebarData.Progress("runelite", current, 2d, "drops", percent,
				compactTestNumber(current) + " / 2 drops"),
			Arrays.asList(requirement, supporting), Collections.singletonList(memberProgress));
	}

	private static BingoSidebarData.Achievement achievement(String id, String title, String detail,
		String character, Double value, String unit)
	{
		String type = id.startsWith("tile") ? "tile_completed" : "wom_gain";
		return new BingoSidebarData.Achievement(id, type, "2026-08-23T16:00:00Z",
			title, detail, "Drew", character, 1, "Tile", value, unit);
	}

	private static String compactTestNumber(double value)
	{
		return Math.rint(value) == value ? Long.toString((long) value) : String.format("%.1f", value);
	}

	private static BufferedImage paint(Component component, int width, int height)
	{
		component.setSize(width, height);
		component.doLayout();
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		component.paint(graphics);
		graphics.dispose();
		return image;
	}

	private static void layoutTree(Container container)
	{
		container.doLayout();
		for (Component component : container.getComponents())
			if (component instanceof Container) layoutTree((Container) component);
	}

	private static boolean containsNearColor(BufferedImage image, Color expected, int tolerance)
	{
		for (int y = 0; y < image.getHeight(); y++)
			for (int x = 0; x < image.getWidth(); x++)
			{
				Color actual = new Color(image.getRGB(x, y), true);
				if (actual.getAlpha() > 0 && colorDistance(actual, expected) <= tolerance) return true;
			}
		return false;
	}

	private static int colorDistance(Color first, Color second)
	{
		return Math.abs(first.getRed() - second.getRed())
			+ Math.abs(first.getGreen() - second.getGreen())
			+ Math.abs(first.getBlue() - second.getBlue());
	}

	private static String repeat(char value, int length)
	{
		StringBuilder builder = new StringBuilder(length);
		for (int index = 0; index < length; index++) builder.append(value);
		return builder.toString();
	}

	private static Component findNamed(Container container, String name)
	{
		for (Component component : container.getComponents())
		{
			if (name.equals(component.getName())) return component;
			if (component instanceof Container)
			{
				Component found = findNamed((Container) component, name);
				if (found != null) return found;
			}
		}
		return null;
	}

	private static String allLabelText(Container container)
	{
		StringBuilder text = new StringBuilder();
		for (Component component : container.getComponents())
		{
			if (component instanceof JLabel) text.append(((JLabel) component).getText()).append('\n');
			if (component instanceof Container) text.append(allLabelText((Container) component));
		}
		return text.toString();
	}

	private static <T> T onEdt(Callable<T> operation) throws Exception
	{
		if (SwingUtilities.isEventDispatchThread()) return operation.call();
		FutureTask<T> task = new FutureTask<>(operation);
		SwingUtilities.invokeAndWait(task);
		return task.get();
	}

	private static void flushEdt() throws Exception
	{
		onEdt(() -> null);
	}
}

