			"\"username\":\"Ayra\",\"displayName\":\"Ayra\"}," +
			"\"members\":[{\"id\":\"member-1\",\"name\":\"Drew\",\"characters\":[]}]," +
			"\"tiles\":[{\"id\":\"tile-1\",\"position\":1,\"title\":\"A <tile>\"," +
			"\"shortTitle\":\"Tile\",\"description\":\"Description\",\"imageUrl\":null," +
			"\"conditionLogic\":\"any\",\"done\":false,\"completedAt\":null," +
			"\"completedByName\":null,\"completedByCharacterName\":null,\"completedByTeam\":false," +
			"\"proofCount\":0,\"conditions\":[{\"id\":\"condition-1\",\"label\":\"A drop\"," +
			"\"kind\":\"runelite_event\",\"target\":2,\"unit\":\"drops\",\"aggregation\":\"team_sum\"," +
			"\"required\":false,\"supportingOnly\":true,\"current\":1,\"percent\":50," +
			"\"memberProgress\":[{\"conditionId\":\"condition-1\",\"memberId\":\"member-1\"," +
			"\"memberName\":\"Drew\",\"characterClaimId\":\"claim-1\",\"characterName\":\"Ayra\"," +
			"\"current\":1,\"unit\":\"drops\",\"source\":\"runelite\"}]}]," +
			"\"progress\":{\"source\":\"runelite\",\"current\":1,\"target\":2,\"unit\":\"drops\"," +
			"\"percent\":50,\"label\":\"1 / 2 drops\"}}]}";
	}

	private static CapturedRequest capture(HttpExchange exchange) throws IOException
	{
		byte[] bytes = exchange.getRequestBody().readAllBytes();
		return new CapturedRequest(exchange.getRequestMethod(),
			exchange.getRequestHeaders().getFirst("Authorization"),
			exchange.getRequestURI().getRawQuery(), new String(bytes, StandardCharsets.UTF_8));
	}

	private static void respond(HttpExchange exchange, int status, String body) throws IOException
	{
		byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
		exchange.getResponseHeaders().set("Content-Type", "application/json");
		exchange.sendResponseHeaders(status, bytes.length);
		exchange.getResponseBody().write(bytes);
		exchange.close();
	}

	private static final class CapturedRequest
	{
		private final String method;
		private final String authorization;
		private final String query;
		private final String body;

		private CapturedRequest(String method, String authorization, String query, String body)
		{
			this.method = method;
			this.authorization = authorization;
			this.query = query == null ? "" : query;
			this.body = body;
		}
	}
}

package com.raredropping;

import java.time.Instant;
import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DiscordDropFilterTest
{
	@Test
	public void defaultsSuppressRoutineLootButKeepValuableDropsAndPets()
	{
		DiscordDropFilter filter = DiscordDropFilter.defaults();
		assertFalse(filter.allows(itemReport(new RareDropItem(995, "Coins", 50_000, 1, 50_000))));
		assertTrue(filter.allows(itemReport(new RareDropItem(6571, "Uncut onyx", 1, 2_500_000, 2_500_000))));
		assertTrue(filter.allows(petReport()));
	}

	@Test
	public void enabledItemRulesAreOrConditions()
	{
		DiscordDropFilter filter = DiscordDropFilter.of(true, 1_000_000, true, "4151, 11802", false);
		assertTrue(filter.allows(itemReport(new RareDropItem(4151, "Abyssal whip", 1, 900_000, 900_000))));
		assertTrue(filter.allows(itemReport(new RareDropItem(2, "Cannonball", 5_000, 200, 1_000_000))));
		assertFalse(filter.allows(itemReport(new RareDropItem(995, "Coins", 999_999, 1, 999_999))));
		assertFalse(filter.allows(petReport()));
	}

	@Test
	public void filteredReportKeepsOnlyItemsThatIndividuallyMatchARule()
	{
		DiscordDropFilter filter = DiscordDropFilter.of(true, 1_000_000, false, "", false);
		RareDropItem greataxe = new RareDropItem(
			4718, "Dharok's greataxe", 1, 1_250_000, 1_250_000);
		RareDropItem mindRunes = new RareDropItem(558, "Mind rune", 50, 3, 150);
		RareDropReport original = itemReport(greataxe, mindRunes);

		RareDropReport filtered = filter.filteredReport(original);

		assertEquals(1, filtered.getItems().size());
		assertEquals("Dharok's greataxe", filtered.getItems().get(0).getName());
		assertEquals(1_250_000, filtered.getItems().get(0).getStackGeValue());
		assertEquals(original.getEventId(), filtered.getEventId());
		assertEquals(original.getOccurredAt(), filtered.getOccurredAt());
	}

	@Test
	public void filteredReportKeepsEveryIndividuallyValuableItem()
	{
		DiscordDropFilter filter = DiscordDropFilter.of(true, 1_000_000, false, "", false);
		RareDropReport filtered = filter.filteredReport(itemReport(
			new RareDropItem(4718, "Dharok's greataxe", 1, 1_250_000, 1_250_000),
			new RareDropItem(6571, "Uncut onyx", 1, 2_500_000, 2_500_000),
			new RareDropItem(558, "Mind rune", 50, 3, 150)));

		assertEquals(2, filtered.getItems().size());
		assertEquals("Dharok's greataxe", filtered.getItems().get(0).getName());
		assertEquals("Uncut onyx", filtered.getItems().get(1).getName());
	}

	@Test
	public void listedUniqueItemIsKeptWithoutIncludingCheapCompanionLoot()
	{
		DiscordDropFilter filter = DiscordDropFilter.of(false, 1_000_000, true, "4718", false);
		RareDropReport filtered = filter.filteredReport(itemReport(
			new RareDropItem(4718, "Dharok's greataxe", 1, 0, 0),
			new RareDropItem(558, "Mind rune", 50, 3, 150)));

		assertEquals(1, filtered.getItems().size());
		assertEquals(4718, filtered.getItems().get(0).getItemId());
	}

	@Test
	public void uniqueOnlyModeUsesCanonicalItemIdsAndNormalizesTheList()
	{
		DiscordDropFilter filter = DiscordDropFilter.of(false, 1_000_000, true,
			" 11802,4151 4151 ", false);
		assertEquals("4151, 11802", filter.getUniqueItemIdsText());
		assertTrue(filter.allows(itemReport(new RareDropItem(11802, "Armadyl godsword", 1, 0, 0))));
		assertFalse(filter.allows(itemReport(new RareDropItem(11804, "Bandos godsword", 1, 50_000_000, 50_000_000))));
	}

	@Test
	public void storedFormRoundTripsAndMalformedNonblankValuesFailClosed()
	{
		DiscordDropFilter original = DiscordDropFilter.of(false, 42, true, "4151, 11802", false);
		DiscordDropFilter restored = DiscordDropFilter.fromStoredValue(original.toStoredValue());
		assertFalse(restored.isMinimumValueEnabled());
		assertEquals(42, restored.getMinimumStackValue());
		assertTrue(restored.isUniqueItemsEnabled());
		assertEquals("4151, 11802", restored.getUniqueItemIdsText());
		assertFalse(restored.isPetsEnabled());

		DiscordDropFilter fallback = DiscordDropFilter.fromStoredValue("not-a-filter");
		assertFalse(fallback.isMinimumValueEnabled());
		assertEquals(DiscordDropFilter.DEFAULT_MINIMUM_STACK_VALUE, fallback.getMinimumStackValue());
		assertFalse(fallback.isUniqueItemsEnabled());
		assertFalse(fallback.isPetsEnabled());
		assertFalse(fallback.allows(itemReport(
			new RareDropItem(6571, "Uncut onyx", 1, 2_500_000, 2_500_000))));
		assertFalse(fallback.allows(petReport()));

		DiscordDropFilter firstUse = DiscordDropFilter.fromStoredValue(null);
		assertTrue(firstUse.isMinimumValueEnabled());
		assertTrue(firstUse.isPetsEnabled());
	}

	@Test
	public void rejectsInvalidRuleValues()
	{
		assertNull(DiscordDropFilter.of(true, -1, false, "", true));
		assertNull(DiscordDropFilter.of(true, 0, false, "", true));
		assertNull(DiscordDropFilter.of(true, DiscordDropFilter.MAXIMUM_STACK_VALUE + 1, false, "", true));
		assertNull(DiscordDropFilter.of(false, 1_000_000, true, "", false));
		assertNull(DiscordDropFilter.of(false, 1_000_000, true, "4151,nope", false));
		assertNull(DiscordDropFilter.of(false, 1_000_000, true, "-5", false));
	}

	@Test
	public void separateCheapItemsDoNotCombineToReachTheMinimum()
	{
		DiscordDropFilter filter = DiscordDropFilter.of(true, 1_000_000, false, "", false);
		RareDropReport combined = RareDropReport.pending(
			"event-combined",
			"Ayra",
			Instant.parse("2026-08-27T12:00:00Z"),
			Arrays.asList(
				new RareDropItem(1, "First", 1, 600_000, 600_000),
				new RareDropItem(2, "Second", 1, 400_000, 400_000)));
		assertFalse(filter.allows(combined));
		assertNull(filter.filteredReport(combined));
	}

	private static RareDropReport itemReport(RareDropItem item)
	{
		return itemReport(new RareDropItem[]{item});
	}

	private static RareDropReport itemReport(RareDropItem... items)
	{
		return RareDropReport.pending(
			"event-item",
			"Ayra",
			Instant.parse("2026-08-27T12:00:00Z"),
			Arrays.asList(items));
	}

	private static RareDropReport petReport()
	{
		return RareDropReport.pendingPet(
			"event-pet",
			"Ayra",
			"Pet",
			RareDropPetDetector.PetAwardType.FOLLOWER,
			Instant.parse("2026-08-27T12:00:00Z"));
	}
}

package com.raredropping;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DiscordScreenshotQueueTest
{
	@Test
	public void rejectsImageWorkWhenItsPrivateQueueIsFull() throws Exception
	{
		DiscordScreenshotQueue queue = new DiscordScreenshotQueue();
		CountDownLatch workerStarted = new CountDownLatch(1);
		CountDownLatch releaseWorker = new CountDownLatch(1);
		try
		{
			assertTrue(queue.submit(() ->
			{
				workerStarted.countDown();
				try
				{
					releaseWorker.await();
				}
				catch (InterruptedException ignored)
				{
					Thread.currentThread().interrupt();
				}
			}));
			assertTrue(workerStarted.await(2, TimeUnit.SECONDS));

			for (int index = 0; index < DiscordScreenshotQueue.MAX_QUEUED_SCREENSHOTS; index++)
			{
				assertTrue(queue.submit(() -> { }));
			}
			AtomicInteger imageRuns = new AtomicInteger();
			AtomicInteger metadataFallbacks = new AtomicInteger();
			queue.submitOrRunFallback(imageRuns::incrementAndGet, metadataFallbacks::incrementAndGet);
			assertEquals(0, imageRuns.get());
			assertEquals(1, metadataFallbacks.get());
		}
		finally
		{
			releaseWorker.countDown();
			queue.close();
		}
	}

	@Test
	public void rejectsWorkAfterClose()
	{
		DiscordScreenshotQueue queue = new DiscordScreenshotQueue();
		queue.close();
		assertFalse(queue.submit(() -> { }));
	}
}

