	@Test
	public void serializesAndBoundsAggregatePendingDeliveries() throws Exception
	{
		CountDownLatch firstRequestArrived = new CountDownLatch(1);
		CountDownLatch releaseFirstRequest = new CountDownLatch(1);
		AtomicInteger activeRequests = new AtomicInteger();
		AtomicInteger maximumActiveRequests = new AtomicInteger();
		server.createContext("/api/webhooks/" + ID + "/" + TOKEN, exchange ->
		{
			int active = activeRequests.incrementAndGet();
			maximumActiveRequests.accumulateAndGet(active, Math::max);
			firstRequestArrived.countDown();
			try
			{
				releaseFirstRequest.await(2, TimeUnit.SECONDS);
				capture(exchange);
				respond(exchange, 204, "");
			}
			catch (InterruptedException exception)
			{
				Thread.currentThread().interrupt();
				exchange.close();
			}
			finally
			{
				activeRequests.decrementAndGet();
			}
		});

		List<CompletableFuture<DiscordWebhookClient.DeliveryResult>> results = new ArrayList<>();
		for (int index = 0; index <= DiscordWebhookClient.MAX_PENDING_DELIVERIES; index++)
		{
			CompletableFuture<DiscordWebhookClient.DeliveryResult> result = new CompletableFuture<>();
			results.add(result);
			client.send(itemReport("runelite:discord-burst-" + index), null, result::complete);
		}

		assertTrue(firstRequestArrived.await(1, TimeUnit.SECONDS));
		DiscordWebhookClient.DeliveryResult overflow =
			results.get(DiscordWebhookClient.MAX_PENDING_DELIVERIES).get(1, TimeUnit.SECONDS);
		assertFalse(overflow.isAccepted());
		assertEquals(0, overflow.getStatusCode());
		releaseFirstRequest.countDown();
		for (int index = 0; index < DiscordWebhookClient.MAX_PENDING_DELIVERIES; index++)
		{
			assertTrue(results.get(index).get(3, TimeUnit.SECONDS).isAccepted());
		}
		assertEquals(1, maximumActiveRequests.get());
	}

