	private RareDropReport itemReport(String eventId)
	{
		return RareDropReport.pending(
			eventId,
			"Ayra",
			Instant.parse("2026-08-27T15:30:00Z"),
			Collections.singletonList(new RareDropItem(29886, "Hallowfell", 1, 250_000, 250_000)),
			"The Hueycoatl");
	}

	private static RareDropScreenshot screenshot()
	{
		return new RareDropScreenshot("image/jpeg", new byte[] {1, 2, 3, 4}, 2, 2);
	}

	private String webhookUrl(String path)
	{
		return "http://127.0.0.1:" + server.getAddress().getPort() + path;
	}

	private static CapturedRequest capture(HttpExchange exchange) throws IOException
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		byte[] buffer = new byte[4096];
		int count;
		while ((count = exchange.getRequestBody().read(buffer)) >= 0)
		{
			if (count > 0) output.write(buffer, 0, count);
		}
		return new CapturedRequest(
			exchange.getRequestMethod(),
			exchange.getRequestHeaders().getFirst("Content-Type"),
			new String(output.toByteArray(), StandardCharsets.ISO_8859_1));
	}

	private static void respond(HttpExchange exchange, int statusCode, String body) throws IOException
	{
		byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
		if (statusCode == 204)
		{
			exchange.sendResponseHeaders(statusCode, -1);
		}
		else
		{
			exchange.sendResponseHeaders(statusCode, bytes.length);
			exchange.getResponseBody().write(bytes);
		}
		exchange.close();
	}

	private static JsonObject payload(CapturedRequest request)
	{
		String marker = "name=\"payload_json\"";
		int disposition = request.body.indexOf(marker);
		int start = request.body.indexOf("\r\n\r\n", disposition);
		int end = request.body.indexOf("\r\n--", start + 4);
		if (disposition < 0 || start < 0 || end < 0)
		{
			throw new AssertionError("Multipart payload_json part was not found");
		}
		return new JsonParser().parse(request.body.substring(start + 4, end)).getAsJsonObject();
	}

	private static JsonObject firstEmbed(JsonObject payload)
	{
		return payload.getAsJsonArray("embeds").get(0).getAsJsonObject();
	}

	private static String fieldText(JsonObject embed)
	{
		StringBuilder text = new StringBuilder();
		for (JsonElement value : embed.getAsJsonArray("fields"))
		{
			JsonObject field = value.getAsJsonObject();
			text.append(field.get("name").getAsString()).append('\n');
			text.append(field.get("value").getAsString()).append('\n');
		}
		return text.toString();
	}

	private static final class CapturedRequest
	{
		private final String method;
		private final String contentType;
		private final String body;

		private CapturedRequest(String method, String contentType, String body)
		{
			this.method = method;
			this.contentType = contentType == null ? "" : contentType;
			this.body = body;
		}
	}

	private static final class BlockingRetryScheduler extends ScheduledThreadPoolExecutor
	{
		private final CountDownLatch scheduled = new CountDownLatch(1);
		private final CountDownLatch allowScheduleReturn = new CountDownLatch(1);
		private final CountDownLatch cancelled = new CountDownLatch(1);
		private volatile ScheduledFuture<?> retry;

		private BlockingRetryScheduler()
		{
			super(1);
		}

		@Override
		public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
		{
			ScheduledFuture<?> delegate = super.schedule(command, delay, unit);
			retry = new CancelTrackingFuture(delegate, cancelled);
			scheduled.countDown();
			boolean interrupted = false;
			while (true)
			{
				try
				{
					allowScheduleReturn.await();
					break;
				}
				catch (InterruptedException exception)
				{
					interrupted = true;
				}
			}
			if (interrupted) Thread.currentThread().interrupt();
			return retry;
		}
	}

	private static final class CancelTrackingFuture implements ScheduledFuture<Object>
	{
		private final ScheduledFuture<?> delegate;
		private final CountDownLatch cancelled;

		private CancelTrackingFuture(ScheduledFuture<?> delegate, CountDownLatch cancelled)
		{
			this.delegate = delegate;
			this.cancelled = cancelled;
		}

		@Override public long getDelay(TimeUnit unit) { return delegate.getDelay(unit); }
		@Override public int compareTo(Delayed other) { return delegate.compareTo(other); }
		@Override public boolean cancel(boolean mayInterruptIfRunning)
		{
			boolean result = delegate.cancel(mayInterruptIfRunning);
			cancelled.countDown();
			return result;
		}
		@Override public boolean isCancelled() { return delegate.isCancelled(); }
		@Override public boolean isDone() { return delegate.isDone(); }
		@Override public Object get() throws InterruptedException, ExecutionException
		{
			return delegate.get();
		}
		@Override public Object get(long timeout, TimeUnit unit)
			throws InterruptedException, ExecutionException, TimeoutException
		{
			return delegate.get(timeout, unit);
		}
	}
}

package com.raredropping;

import com.google.gson.Gson;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DiscordWebhookClientTest
{
	private static final String ID = "123456789012345678";
	private static final String TOKEN = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-";
	private ScheduledExecutorService scheduler;

	@Before
	public void setUp()
	{
		scheduler = Executors.newSingleThreadScheduledExecutor();
	}

	@After
	public void tearDown()
	{
		scheduler.shutdownNow();
	}

	@Test
	public void acceptsAndNormalizesCopiedDiscordWebhookUrls()
	{
		String url = "  https://DISCORD.com/api/webhooks/" + ID + "/" + TOKEN + "  ";
		assertTrue(DiscordWebhookClient.isAllowedWebhookUrl(url));
		assertEquals("https://discord.com/api/webhooks/" + ID + "/" + TOKEN,
			DiscordWebhookClient.normalizeWebhookUrl(url));
		assertTrue(DiscordWebhookClient.isAllowedWebhookUrl(
			"https://canary.discord.com/api/webhooks/" + ID + "/" + TOKEN));
		assertTrue(DiscordWebhookClient.isAllowedWebhookUrl(
			"https://ptb.discord.com/api/webhooks/" + ID + "/" + TOKEN));
	}

	@Test
	public void rejectsNonDiscordAndStructurallyUnsafeUrls()
	{
		String path = "/api/webhooks/" + ID + "/" + TOKEN;
		String[] rejected = {
			null,
			"",
			"not-a-url",
			"http://discord.com" + path,
			"https://discord.com.evil.test" + path,
			"https://evil.discord.com" + path,
			"https://user:password@discord.com" + path,
			"https://discord.com:8443" + path,
			"https://discord.com/api/webhooks/not-a-snowflake/" + TOKEN,
			"https://discord.com/api/webhooks/" + ID + "/short",
			"https://discord.com" + path + "/extra",
			"https://discord.com" + path + "?wait=true",
			"https://discord.com" + path + "#fragment",
			"https://discord.com/api/v10/webhooks/" + ID + "/" + TOKEN,
			"https://discord.com/api/webhooks/" + ID + "/abc%2F" + TOKEN
		};
		for (String value : rejected)
		{
			assertFalse(String.valueOf(value), DiscordWebhookClient.isAllowedWebhookUrl(value));
			assertNull(String.valueOf(value), DiscordWebhookClient.normalizeWebhookUrl(value));
		}
	}

	@Test(expected = IllegalArgumentException.class)
	public void productionConstructorRejectsLoopback()
	{
		new DiscordWebhookClient(
			new OkHttpClient(), scheduler, new Gson(),
			"http://127.0.0.1:8080/api/webhooks/" + ID + "/" + TOKEN);
	}
}

package com.raredropping;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class DiscordWebhookSettingsStoreTest
{
	private static final String ID = "123456789012345678";
	private static final String TOKEN_ONE =
		"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-";
	private static final String TOKEN_TWO =
		"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz9876543210_-";

	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void savesAndLoadsOneCanonicalUtf8Url() throws Exception
	{
		Path file = path("secrets", "discord-webhook");
		DiscordWebhookSettingsStore store = new DiscordWebhookSettingsStore(file);
		String input = "  https://DISCORD.com/api/webhooks/" + ID + "/" + TOKEN_ONE + "  ";
		String expected = "https://discord.com/api/webhooks/" + ID + "/" + TOKEN_ONE;

		assertTrue(store.save(input));
		assertEquals(expected, store.load());
		assertEquals(expected, new String(Files.readAllBytes(file), StandardCharsets.UTF_8));
		assertEquals(file.toAbsolutePath().normalize(), store.getFile());
	}

	@Test
	public void atomicallyReplacesExistingSecretWithoutExtraContent() throws Exception
	{
		Path file = path("discord-webhook");
		DiscordWebhookSettingsStore store = new DiscordWebhookSettingsStore(file);
		String first = webhook(TOKEN_ONE);
		String second = webhook(TOKEN_TWO);

		assertTrue(store.save(first));
		assertTrue(store.save(second));
		assertEquals(second, store.load());
		assertEquals(second, new String(Files.readAllBytes(file), StandardCharsets.UTF_8));
		assertEquals(1, children(file.getParent()).size());
		assertEquals(file.getFileName(), children(file.getParent()).get(0).getFileName());
	}

	@Test
	public void clearRemovesOnlyASecretFileOrSymlink() throws Exception
	{
		Path file = path("discord-webhook");
		DiscordWebhookSettingsStore store = new DiscordWebhookSettingsStore(file);
		assertFalse(store.clear());
		assertTrue(store.save(webhook(TOKEN_ONE)));
		assertTrue(store.clear());
		assertFalse(Files.exists(file));
		assertNull(store.load());
		assertFalse(store.clear());

		Files.createDirectory(file);
		assertFalse(store.clear());
		assertTrue(Files.isDirectory(file));
	}

	@Test
	public void rejectsInvalidSaveAndInvalidOrNonCanonicalDiskContent() throws Exception
	{
		Path file = path("discord-webhook");
		DiscordWebhookSettingsStore store = new DiscordWebhookSettingsStore(file);
		assertFalse(store.save("https://example.test/api/webhooks/" + ID + "/" + TOKEN_ONE));
		assertFalse(Files.exists(file));

		Files.write(file, "not a webhook".getBytes(StandardCharsets.UTF_8));
		assertNull(store.load());
		Files.write(file, (webhook(TOKEN_ONE) + "\n").getBytes(StandardCharsets.UTF_8));
		assertNull(store.load());
		Files.write(file, new byte[] {(byte) 0xC3, (byte) 0x28});
		assertNull(store.load());
	}

	@Test
	public void refusesOversizedContentWithoutReadingPastBound() throws Exception
	{
		Path file = path("discord-webhook");
		DiscordWebhookSettingsStore store = new DiscordWebhookSettingsStore(file);
		byte[] oversized = new byte[DiscordWebhookSettingsStore.MAX_FILE_BYTES + 1];
		java.util.Arrays.fill(oversized, (byte) 'a');
		Files.write(file, oversized);
		assertNull(store.load());
	}

	@Test
	public void removesTemporaryFileWhenReplacementFails() throws Exception
	{
		Path file = path("discord-webhook");
		Files.createDirectory(file);
		DiscordWebhookSettingsStore store = new DiscordWebhookSettingsStore(file);

		try
		{
			store.save(webhook(TOKEN_ONE));
			fail("Expected replacement of a directory to fail");
		}
		catch (IOException expected)
		{
			// The target is intentionally a directory; only the temp file is disposable.
		}

		List<Path> remaining = children(file.getParent());
		assertEquals(1, remaining.size());
		assertEquals(file.getFileName(), remaining.get(0).getFileName());
		assertTrue(Files.isDirectory(file));
	}

	@Test
	public void removesCrashOrphanedSecretTempsWithoutTouchingOtherFiles() throws Exception
	{
		Path file = path("discord-webhook");
		Path orphan = file.getParent().resolve(".discord-webhook.crashed.tmp");
		Path unrelated = file.getParent().resolve(".another-webhook.crashed.tmp");
		Path similar = file.getParent().resolve(".discord-webhook.crashed.txt");
		Files.write(orphan, webhook(TOKEN_ONE).getBytes(StandardCharsets.UTF_8));
		Files.write(unrelated, "keep".getBytes(StandardCharsets.UTF_8));
		Files.write(similar, "keep".getBytes(StandardCharsets.UTF_8));

		DiscordWebhookSettingsStore store = new DiscordWebhookSettingsStore(file);
		assertNull(store.load());
		assertFalse(Files.exists(orphan));
		assertTrue(Files.exists(unrelated));
		assertTrue(Files.exists(similar));

		Path secondOrphan = file.getParent().resolve(".discord-webhook.second.tmp");
		Files.write(secondOrphan, webhook(TOKEN_TWO).getBytes(StandardCharsets.UTF_8));
		assertFalse(store.clear());
		assertFalse(Files.exists(secondOrphan));
		assertTrue(Files.exists(unrelated));
	}

	private Path path(String... parts)
	{
		Path value = temporaryFolder.getRoot().toPath();
		for (String part : parts) value = value.resolve(part);
		return value;
	}

	private static String webhook(String token)
	{
		return "https://discord.com/api/webhooks/" + ID + "/" + token;
	}

	private static List<Path> children(Path directory) throws IOException
	{
		try (Stream<Path> stream = Files.list(directory))
		{
			return stream.collect(Collectors.toList());
		}
