package com.raredropping;

import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class RareDropCaptureAreaTest
{
	@Test
	public void scalesLogicalViewportBoundsForHighDensityFrames()
	{
		BufferedImage source = coordinateImage(200, 100);
		RareDropCaptureArea area = new RareDropCaptureArea(100, 50, 30, 15, 40, 20);

		BufferedImage cropped = area.crop(source);

		// The 24-logical-pixel context padding clamps this viewport to the full height
		// and to x=12..188 in the doubled-resolution source frame.
		assertEquals(176, cropped.getWidth());
		assertEquals(100, cropped.getHeight());
		assertEquals(source.getRGB(12, 0), cropped.getRGB(0, 0));
		assertEquals(source.getRGB(187, 99), cropped.getRGB(175, 99));
	}

	@Test
	public void fallsBackToAFullIndependentCopyForInvalidViewportData()
	{
		BufferedImage source = coordinateImage(20, 10);
		RareDropCaptureArea area = new RareDropCaptureArea(0, 0, 0, 0, 0, 0);

		BufferedImage copy = area.crop(source);
		source.setRGB(0, 0, 0x00ff0000);

		assertEquals(20, copy.getWidth());
		assertEquals(10, copy.getHeight());
		assertEquals(0xff000000, copy.getRGB(0, 0));
	}

	private static BufferedImage coordinateImage(int width, int height)
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				image.setRGB(x, y, (x << 8) | y);
			}
		}
		return image;
	}
}

package com.raredropping;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.game.ItemStack;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RareDropEvaluatorTest
{
	private RareDropEvaluator evaluator;

	@Before
	public void setUp()
	{
		FakeItemData itemData = new FakeItemData();
		itemData.add(100, 100, "Valuable item", 600_000);
		itemData.add(101, 100, "Valuable item", 600_000);
		itemData.add(200, 200, "Untradeable", 0);
		itemData.add(300, 300, "Common item", 10);
		evaluator = new RareDropEvaluator(itemData);
	}

	@Test
	public void collectsEveryValidStackWithoutClientSideFiltering()
	{
		List<RareDropItem> result = evaluator.collectItems(Arrays.asList(
			new ItemStack(300, 2),
			new ItemStack(200, 1),
			new ItemStack(101, 3),
			new ItemStack(100, 4),
			new ItemStack(300, 0)));

		assertEquals(3, result.size());
		assertEquals(300, result.get(0).getItemId());
		assertEquals("Common item", result.get(0).getName());
		assertEquals(2L, result.get(0).getQuantity());
		assertEquals(20L, result.get(0).getStackGeValue());
		assertEquals(200, result.get(1).getItemId());
		assertEquals(0L, result.get(1).getStackGeValue());
		assertEquals(100, result.get(2).getItemId());
		assertEquals(7L, result.get(2).getQuantity());
		assertEquals(4_200_000L, result.get(2).getStackGeValue());
	}

	@Test
	public void returnsEmptyForMissingLoot()
	{
		assertTrue(evaluator.collectItems(null).isEmpty());
		assertTrue(evaluator.collectItems(java.util.Collections.emptyList()).isEmpty());
	}

	private static final class FakeItemData implements RareDropEvaluator.ItemData
	{
		private final Map<Integer, Integer> canonicalIds = new HashMap<>();
		private final Map<Integer, String> names = new HashMap<>();
		private final Map<Integer, Integer> prices = new HashMap<>();
		private void add(int itemId, int canonicalId, String name, int price)
		{
			canonicalIds.put(itemId, canonicalId);
			names.put(canonicalId, name);
			prices.put(canonicalId, price);
		}
		@Override public int canonicalize(int itemId) { return canonicalIds.get(itemId); }
		@Override public int getPrice(int itemId) { return prices.get(itemId); }
		@Override public String getName(int itemId) { return names.get(itemId); }
	}
}

