public class RareDropEvidenceRendererTest
{
	@Test
	public void addsEvidenceWithoutChangingTheCapturedFrame()
	{
		BufferedImage source = new BufferedImage(320, 180, BufferedImage.TYPE_INT_RGB);
		for (int y = 0; y < source.getHeight(); y++)
		{
			for (int x = 0; x < source.getWidth(); x++)
			{
				source.setRGB(x, y, Color.WHITE.getRGB());
			}
