	private static RareDropHistoryEntry entry(
		String eventId,
		String occurredAt,
		String username,
		String itemDrop,
		int tilePosition,
		boolean markComplete,
		RareDropHistoryEntry.State state,
		int statusCode,
		Color screenshotColor) throws Exception
	{
		String hash = eventId.startsWith("old") ? repeat('a')
			: eventId.startsWith("new") ? repeat('b')
			: eventId.startsWith("sent") ? repeat('c') : repeat('d');
		RareDropScreenshot screenshot = screenshot(screenshotColor);
		return new RareDropHistoryEntry(
			hash,
			eventId,
			occurredAt,
			occurredAt,
			username,
			itemDrop,
			tilePosition,
			markComplete,
			RareDropPingConfig.PRODUCTION_BASE_URL + "/api/v2/integrations/runelite/events/proof",
			repeat('e'),
			screenshot.getMediaType(),
			screenshot.getWidth(),
			screenshot.getHeight(),
			screenshot.getByteLength(),
			repeat('f'),
			state,
			state == RareDropHistoryEntry.State.SENT ? Instant.parse(occurredAt).plusSeconds(1).toString() : null,
			statusCode);
	}

	private static RareDropScreenshot screenshot(Color color) throws Exception
	{
		BufferedImage image = new BufferedImage(400, 200, BufferedImage.TYPE_INT_RGB);
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				image.setRGB(x, y, color.getRGB());
			}
		}
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		ImageIO.write(image, "jpg", output);
		return new RareDropScreenshot("image/jpeg", output.toByteArray(), image.getWidth(), image.getHeight());
	}

