	private static String repeat(char value)
	{
		StringBuilder builder = new StringBuilder(64);
		for (int index = 0; index < 64; index++)
		{
			builder.append(value);
		}
		return builder.toString();
	}

	private static BufferedImage paint(Component component, int width, int height)
	{
		component.setSize(width, height);
		component.doLayout();
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		component.paint(graphics);
		graphics.dispose();
		return image;
	}

	private static void layoutTree(Container container)
	{
		container.doLayout();
		for (Component component : container.getComponents())
		{
			if (component instanceof Container) layoutTree((Container) component);
		}
	}

	private static Component findNamed(Container container, String name)
	{
		for (Component component : container.getComponents())
		{
			if (name.equals(component.getName()))
			{
				return component;
			}
			if (component instanceof Container)
			{
				Component found = findNamed((Container) component, name);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static int countNamedPrefix(Container container, String prefix)
	{
		int count = 0;
		for (Component component : container.getComponents())
		{
			if (component.getName() != null && component.getName().startsWith(prefix)) count++;
			if (component instanceof Container) count += countNamedPrefix((Container) component, prefix);
		}
		return count;
	}

	private static String allLabelText(Container container)
	{
		StringBuilder text = new StringBuilder();
		for (Component component : container.getComponents())
		{
			if (component instanceof JLabel)
			{
				text.append(((JLabel) component).getText()).append('\n');
			}
			if (component instanceof Container)
			{
				text.append(allLabelText((Container) component));
			}
		}
		return text.toString();
	}

	private static void flushEdt() throws Exception
	{
		onEdt(() -> null);
	}

	private static <T> T onEdt(Callable<T> task) throws Exception
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			return task.call();
		}
		FutureTask<T> future = new FutureTask<>(task);
		SwingUtilities.invokeAndWait(future);
		return future.get();
	}
}

