	@Test
	public void persistsAndReconstructsExactPendingSubmissionAcrossRestart() throws Exception
	{
		Path root = temporaryFolder.newFolder("history").toPath();
		RareDropSubmission submission = new RareDropSubmission(
			"runelite:persisted:tile:9",
			"2026-08-23T18:45:12.345Z",
			"Ayra",
			"Coins x1250 (item 995)",
			"item_drop",
			"Sarachnis",
			9,
			false,
			new RareDropScreenshot("image/jpeg", bytes(1), 8, 8));
		RareDropHistoryStore firstStore = new RareDropHistoryStore(root);

		RareDropHistoryEntry saved = firstStore.savePending(ENDPOINT, TOKEN, submission);
		RareDropHistoryStore restartedStore = new RareDropHistoryStore(root);
		RareDropHistoryEntry loaded = restartedStore.find(submission.getEventId()).orElseThrow();
		RareDropSubmission reconstructed = restartedStore.loadSubmission(submission.getEventId());

		assertEquals(saved.getStorageId(), loaded.getStorageId());
		assertEquals(RareDropHistoryEntry.State.PENDING, loaded.getState());
		assertFalse(loaded.isSent());
		assertEquals(0, loaded.getLastStatusCode());
		assertEquals(submission.getEventId(), reconstructed.getEventId());
		assertEquals(submission.getOccurredAt(), reconstructed.getOccurredAt());
		assertEquals(submission.getUsername(), reconstructed.getUsername());
		assertEquals(submission.getItemDrop(), reconstructed.getItemDrop());
		assertEquals(submission.getEventType(), reconstructed.getEventType());
		assertEquals(submission.getSourceNpc(), reconstructed.getSourceNpc());
		assertEquals(submission.getTilePosition(), reconstructed.getTilePosition());
		assertEquals(submission.isMarkComplete(), reconstructed.isMarkComplete());
		assertEquals(submission.getScreenshot().getMediaType(), reconstructed.getScreenshot().getMediaType());
		assertEquals(submission.getScreenshot().getWidth(), reconstructed.getScreenshot().getWidth());
		assertEquals(submission.getScreenshot().getHeight(), reconstructed.getScreenshot().getHeight());
		assertArrayEquals(submission.getScreenshot().copyData(), reconstructed.getScreenshot().copyData());
		assertEquals(RareDropHistoryStore.tokenFingerprint(TOKEN), loaded.getTokenFingerprint());
		assertNotEquals(TOKEN, loaded.getTokenFingerprint());

		String allMetadata = Files.readString(root.resolve(saved.getStorageId() + ".properties"));
		assertFalse("Bearer token must never be stored in history metadata", allMetadata.contains(TOKEN));
	}

