			new RareDropHistoryStore(root).loadSubmission(submission.getEventId()).getScreenshot().copyData());

		store.markFailure(submission.getEventId(), 403);
		RareDropHistoryEntry reboundAgain = store.rebindDeviceToken(
			submission.getEventId(),
			"another-replacement-token-that-is-long-enough");
		assertEquals(403, reboundAgain.getLastStatusCode());
		assertEquals(
			RareDropHistoryStore.tokenFingerprint("another-replacement-token-that-is-long-enough"),
			reboundAgain.getTokenFingerprint());

		RareDropSubmission sentSubmission = submission(
			"runelite:sent-rebind:tile:9",
			"Sent drop",
			9,
			false,
			bytes(15));
		store.savePending(ENDPOINT, TOKEN, sentSubmission);
		store.markFailure(sentSubmission.getEventId(), 401);
		store.markSent(sentSubmission.getEventId(), Instant.now(), 201);
		assertThrows(
			IllegalStateException.class,
			() -> store.rebindRejectedToken(sentSubmission.getEventId(), "replacement-token-that-is-long-enough"));
	}

	@Test
	public void multipleStoreInstancesCannotRegressSentStateDuringConcurrentUpdates() throws Exception
	{
		Path root = temporaryFolder.newFolder("multi-instance").toPath();
		RareDropHistoryStore first = new RareDropHistoryStore(root);
		RareDropHistoryStore second = new RareDropHistoryStore(root);
		ExecutorService workers = Executors.newFixedThreadPool(2);
		try
		{
			for (int iteration = 0; iteration < 20; iteration++)
			{
				String eventId = "runelite:concurrent-" + iteration + ":tile:9";
				first.savePending(
					ENDPOINT,
					TOKEN,
					submission(eventId, "Concurrent " + iteration, 9, false, bytes(30 + iteration)));
				CountDownLatch ready = new CountDownLatch(2);
				CountDownLatch start = new CountDownLatch(1);
				Future<?> failure = workers.submit(() ->
				{
					ready.countDown();
					start.await();
					first.markFailure(eventId, 503);
					return null;
				});
				Future<?> success = workers.submit(() ->
				{
					ready.countDown();
					start.await();
					second.markSent(eventId, Instant.now(), 201);
					return null;
				});
				assertTrue(ready.await(2, TimeUnit.SECONDS));
				start.countDown();
				failure.get(5, TimeUnit.SECONDS);
				success.get(5, TimeUnit.SECONDS);

				assertTrue(new RareDropHistoryStore(root).find(eventId).orElseThrow().isSent());
			}
		}
		finally
		{
			workers.shutdownNow();
		}
	}

	@Test
	public void startupCleansOnlyOldOrphanAndTemporaryFiles() throws Exception
	{
		Path root = temporaryFolder.newFolder("cleanup").toPath();
		RareDropHistoryStore store = new RareDropHistoryStore(root);
		RareDropHistoryEntry valid = store.savePending(
			ENDPOINT,
			TOKEN,
			submission("runelite:valid-cleanup:tile:9", "Valid", 9, false, bytes(16)));
		Path validImage = root.resolve(valid.getStorageId() + ".jpg");
		Path validMetadata = root.resolve(valid.getStorageId() + ".properties");
		Path oldOrphan = root.resolve(repeat('a') + ".jpg");
		Path recentOrphan = root.resolve(repeat('b') + ".jpg");
		Path oldTemporary = root.resolve(".rare-drop-abandoned.tmp");
		Path recentTemporary = root.resolve(".rare-drop-active.tmp");
		Files.write(oldOrphan, bytes(17));
		Files.write(recentOrphan, bytes(18));
		Files.write(oldTemporary, bytes(19));
		Files.write(recentTemporary, bytes(20));

		FileTime old = FileTime.fromMillis(
			System.currentTimeMillis() - RareDropHistoryStore.CLEANUP_GRACE_MILLIS - 5_000L);
		Files.setLastModifiedTime(oldOrphan, old);
		Files.setLastModifiedTime(oldTemporary, old);
		Files.setLastModifiedTime(validImage, old);
		Files.setLastModifiedTime(validMetadata, old);

		new RareDropHistoryStore(root);

		assertFalse(Files.exists(oldOrphan));
		assertFalse(Files.exists(oldTemporary));
		assertTrue(Files.exists(recentOrphan));
		assertTrue(Files.exists(recentTemporary));
		assertTrue(Files.exists(validImage));
		assertTrue(Files.exists(validMetadata));
		assertTrue(new RareDropHistoryStore(root).find(valid.getEventId()).isPresent());
	}

	private RareDropHistoryEntry saveWithClockGap(
		RareDropHistoryStore store,
		RareDropSubmission submission) throws Exception
	{
		RareDropHistoryEntry entry = store.savePending(ENDPOINT, TOKEN, submission);
		Thread.sleep(2L);
		return entry;
	}

	private static RareDropSubmission submission(
		String eventId,
		String itemDrop,
		int tilePosition,
		boolean markComplete,
		byte[] screenshotBytes)
	{
		return new RareDropSubmission(
			eventId,
			"2026-08-23T18:45:12.345Z",
			"Ayra",
			itemDrop,
			tilePosition,
			markComplete,
			new RareDropScreenshot("image/jpeg", screenshotBytes, 8, 8));
	}

	private static RareDropSubmission outageSubmission(String eventId, byte[] screenshotBytes)
	{
		RareDropReport report = RareDropReport.pending(
			eventId,
			"Ayra",
			Instant.parse("2026-08-23T18:45:12.345Z"),
			java.util.Collections.singletonList(new RareDropItem(995, "Coins", 40, 1, 40)),
			"Sarachnis");
		return RareDropSubmission.forPendingPreflight(
			report,
			new RareDropScreenshot("image/jpeg", screenshotBytes, 8, 8));
	}

	private static byte[] bytes(int seed)
	{
		byte[] value = new byte[32];
		Arrays.fill(value, (byte) seed);
		return value;
	}

	private static String repeat(char value)
	{
		char[] repeated = new char[64];
		Arrays.fill(repeated, value);
		return new String(repeated);
	}

	private static Properties loadProperties(Path path) throws IOException
	{
		Properties properties = new Properties();
		try (InputStream input = Files.newInputStream(path))
		{
			properties.load(input);
		}
		return properties;
	}

	private static void storeProperties(Path path, Properties properties) throws IOException
	{
		try (OutputStream output = Files.newOutputStream(
			path,
			StandardOpenOption.WRITE,
			StandardOpenOption.TRUNCATE_EXISTING))
		{
			properties.store(output, "tampered test metadata");
		}
	}
}

