package com.raredropping;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.Random;
import javax.imageio.ImageIO;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class RareDropScreenshotEncoderTest
{
	@Test
	public void encodesWithinTheStrictOneMegabyteLimit() throws Exception
	{
		assertEquals(1_000_000, RareDropScreenshotEncoder.MAX_SCREENSHOT_BYTES);
		BufferedImage source = noisyImage(1280, 720, 42L);

		RareDropScreenshot screenshot = new RareDropScreenshotEncoder().encode(source);

		assertEquals("image/jpeg", screenshot.getMediaType());
		assertTrue(screenshot.getByteLength() <= 1_000_000);
		BufferedImage decoded = ImageIO.read(new ByteArrayInputStream(screenshot.copyData()));
		assertNotNull(decoded);
		assertEquals(screenshot.getWidth(), decoded.getWidth());
		assertEquals(screenshot.getHeight(), decoded.getHeight());
	}

	@Test
	public void downscalesWhenQualityReductionAloneCannotMeetTheLimit() throws Exception
	{
		BufferedImage source = noisyImage(640, 480, 84L);

		RareDropScreenshot screenshot = new RareDropScreenshotEncoder(20_000).encode(source);

		assertTrue(screenshot.getByteLength() <= 20_000);
		assertTrue(screenshot.getWidth() < source.getWidth());
		assertTrue(screenshot.getHeight() < source.getHeight());
		assertNotNull(ImageIO.read(new ByteArrayInputStream(screenshot.copyData())));
	}

	@Test
	public void screenshotBytesAreDefensivelyCopied()
	{
		byte[] source = new byte[]{1, 2, 3};
		RareDropScreenshot screenshot = new RareDropScreenshot("image/jpeg", source, 1, 1);
		source[0] = 9;
		byte[] firstRead = screenshot.copyData();
		firstRead[1] = 9;

		assertArrayEquals(new byte[]{1, 2, 3}, screenshot.copyData());
	}

	private static BufferedImage noisyImage(int width, int height, long seed)
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Random random = new Random(seed);
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				image.setRGB(x, y, 0xff000000 | random.nextInt(0x01000000));
			}
		}
		return image;
	}
}

