			respond(exchange, 201, "{\"deviceCode\":\"device-1\",\"userCode\":\"ABCD-EFGH\","
				+ "\"verificationUrl\":\"" + verificationUrl
				+ "\",\"expiresIn\":900,\"pollInterval\":5}");
		});
