		client.startPairing("Ayra", "RuneLite Drop Ping", started::complete);
		RareDropWebhookClient.PairStartResult start = started.get(3, TimeUnit.SECONDS);
		assertTrue(start.isAccepted());
		assertEquals("ABCD-EFGH", start.getUserCode());
		assertEquals("POST", captured.method);
		assertTrue(captured.body.contains("\"characterName\":\"Ayra\""));

		server.createContext("/api/v2/integrations/runelite/pair/poll", exchange ->
		{
			captured = capture(exchange);
			respond(exchange, 200, "{\"status\":\"approved\",\"deviceToken\":\"device-token\","
				+ "\"characterName\":\"Ayra\"}");
		});
		CompletableFuture<RareDropWebhookClient.PairPollResult> polled = new CompletableFuture<>();
		client.pollPairing("device-1", polled::complete);
		RareDropWebhookClient.PairPollResult poll = polled.get(3, TimeUnit.SECONDS);
		assertTrue(poll.isApproved());
