	@Test
	public void durableOutageRetryPreflightsThenSendsMatchingProof() throws Exception
	{
		server.createContext("/api/v2/integrations/runelite/events/preflight", exchange ->
		{
			CapturedRequest request = capture(exchange);
			assertTrue(request.body.contains("\"eventId\":\"runelite:outage-match\""));
			respond(exchange, 200, matchResponse(false));
		});
		server.createContext("/api/v2/integrations/runelite/events/proof", exchange ->
		{
			CapturedRequest request = capture(exchange);
			assertEquals("runelite:outage-match", request.idempotencyKey);
			assertTrue(request.body.contains("runelite:outage-match"));
			respond(exchange, 201, matchResponse(false));
		});
		RareDropHistoryStore store = saveOutage("runelite:outage-match");
		CompletableFuture<RareDropOutageRetry.Result> future = new CompletableFuture<>();
		new RareDropOutageRetry(store, client, "device-token", "runelite:outage-match")
			.start(future::complete);
		RareDropOutageRetry.Result result = future.get(5, TimeUnit.SECONDS);

		assertEquals(RareDropOutageRetry.Disposition.SENT, result.getDisposition());
		RareDropHistoryEntry entry = new RareDropHistoryStore(storeRoot("runelite-outage-match"))
			.find("runelite:outage-match").orElseThrow();
		assertTrue(entry.isSent());
		assertEquals(22, entry.getTilePosition());
	}

	@Test
	public void durableOutageRetryResolvesSuccessfulNoMatchWithoutProof() throws Exception
	{
		server.createContext("/api/v2/integrations/runelite/events/preflight", exchange ->
		{
			capture(exchange);
			respond(exchange, 200, "{\"accepted\":true,\"duplicate\":false,\"matches\":[]}");
		});
		RareDropHistoryStore store = saveOutage("runelite:outage-no-match");
		CompletableFuture<RareDropOutageRetry.Result> future = new CompletableFuture<>();
		new RareDropOutageRetry(store, client, "device-token", "runelite:outage-no-match")
			.start(future::complete);
		RareDropOutageRetry.Result result = future.get(5, TimeUnit.SECONDS);

		assertEquals(RareDropOutageRetry.Disposition.IGNORED, result.getDisposition());
		RareDropHistoryEntry entry = store.find("runelite:outage-no-match").orElseThrow();
		assertTrue(entry.isIgnored());
		assertTrue(entry.isResolved());
		assertFalse(entry.isSent());
	}

	@Test
	public void duplicateOutageRetryKeepsEventIdAndResolvesIdempotently() throws Exception
	{
		server.createContext("/api/v2/integrations/runelite/events/preflight", exchange ->
		{
			CapturedRequest request = capture(exchange);
			assertEquals("runelite:outage-duplicate", request.idempotencyKey);
			respond(exchange, 200, matchResponse(true));
		});
		server.createContext("/api/v2/integrations/runelite/events/proof", exchange ->
		{
			CapturedRequest request = capture(exchange);
			assertEquals("runelite:outage-duplicate", request.idempotencyKey);
			respond(exchange, 200, matchResponse(true));
		});
		RareDropHistoryStore store = saveOutage("runelite:outage-duplicate");
		CompletableFuture<RareDropOutageRetry.Result> future = new CompletableFuture<>();
		new RareDropOutageRetry(store, client, "replacement-device-token", "runelite:outage-duplicate")
			.start(future::complete);
		RareDropOutageRetry.Result result = future.get(5, TimeUnit.SECONDS);

		assertEquals(RareDropOutageRetry.Disposition.SENT, result.getDisposition());
		assertEquals(200, result.getStatusCode());
		assertTrue(store.find("runelite:outage-duplicate").orElseThrow().isSent());
	}

	private static RareDropReport itemReport(String eventId)
	{
		return RareDropReport.pending(
			eventId,
			"Ayra",
			Instant.parse("2026-08-23T16:00:00Z"),
			Collections.singletonList(new RareDropItem(
				29886, "Hallowfell", 1, 250_000, 250_000)),
			"The Hueycoatl");
	}

	private RareDropHistoryStore saveOutage(String eventId) throws Exception
	{
		Path root = storeRoot(eventId.replace(':', '-'));
		RareDropHistoryStore store = new RareDropHistoryStore(root);
		RareDropSubmission submission = RareDropSubmission.forPendingPreflight(
			itemReport(eventId),
			new RareDropScreenshot("image/jpeg", new byte[] {1, 2, 3, 4}, 2, 2));
		store.savePending(
			RareDropPingConfig.PRODUCTION_BASE_URL + "/api/v2/integrations/runelite/events/proof",
			"device-token",
			submission);
		return store;
	}

	private Path storeRoot(String name) throws Exception
	{
		return temporaryFolder.getRoot().toPath().resolve(name);
	}

	private static String matchResponse(boolean duplicate)
	{
		return "{\"accepted\":true,\"duplicate\":" + duplicate + ",\"matches\":[{"
			+ "\"competitionId\":\"comp-1\",\"tileId\":\"tile-22\",\"tilePosition\":22,"
			+ "\"title\":\"Mad Angel\"}]}";
	}

	private static CapturedRequest capture(HttpExchange exchange) throws IOException
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		byte[] buffer = new byte[4096];
		int count;
		while ((count = exchange.getRequestBody().read(buffer)) >= 0) output.write(buffer, 0, count);
		return new CapturedRequest(
			exchange.getRequestMethod(),
			exchange.getRequestURI().getRawQuery(),
			exchange.getRequestHeaders().getFirst("Authorization"),
			exchange.getRequestHeaders().getFirst("Idempotency-Key"),
			exchange.getRequestHeaders().getFirst("Content-Type"),
			new String(output.toByteArray(), StandardCharsets.ISO_8859_1));
	}

	private static void respond(HttpExchange exchange, int status, String body) throws IOException
	{
		byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
		exchange.getResponseHeaders().set("Content-Type", "application/json");
		exchange.sendResponseHeaders(status, bytes.length);
		exchange.getResponseBody().write(bytes);
		exchange.close();
	}

	private static final class CapturedRequest
	{
		private final String method;
		private final String query;
		private final String authorization;
		private final String idempotencyKey;
		private final String contentType;
		private final String body;
		private CapturedRequest(String method, String query, String authorization, String idempotencyKey,
			String contentType, String body)
		{
			this.method = method;
			this.query = query == null ? "" : query;
			this.authorization = authorization;
			this.idempotencyKey = idempotencyKey;
			this.contentType = contentType == null ? "" : contentType;
			this.body = body;
		}
	}
}

package com.raredropping;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RareDropWebhookClientTest
{
	@Test
	public void permitsHttpsAndLocalDevelopmentHttp()
	{
		assertTrue(RareDropWebhookClient.isAllowedBaseUrl(RareDropPingConfig.PRODUCTION_BASE_URL));
		assertTrue(RareDropWebhookClient.isAllowedBaseUrl("http://localhost:8080/"));
		assertTrue(RareDropWebhookClient.isAllowedBaseUrl("http://127.0.0.1:8080/"));
		assertTrue(RareDropWebhookClient.isAllowedBaseUrl("https://[::1]:8443/"));
	}

	@Test
	public void rejectsMissingMalformedAndRemoteHttpEndpoints()
	{
		assertFalse(RareDropWebhookClient.isAllowedBaseUrl(""));
		assertFalse(RareDropWebhookClient.isAllowedBaseUrl("not-a-url"));
		assertFalse(RareDropWebhookClient.isAllowedBaseUrl("http://api.example.com/"));
		assertFalse(RareDropWebhookClient.isAllowedBaseUrl("https://api.example.com/"));
		assertFalse(RareDropWebhookClient.isAllowedBaseUrl("https://exodus-prime-bingo.vercel.app/not-a-base"));
		assertFalse(RareDropWebhookClient.isAllowedBaseUrl("https://user:password@exodus-prime-bingo.vercel.app/"));
	}

	@Test
	public void permitsOnlyTheExactProductionPairingUrl()
	{
		assertTrue(RareDropWebhookClient.isAllowedPairingVerificationUrl(
			"https://exodus-prime-bingo.vercel.app/runelite/pair?code=ABCD-EFGH", "ABCD-EFGH"));
		assertFalse(RareDropWebhookClient.isAllowedPairingVerificationUrl(
			"http://exodus-prime-bingo.vercel.app/runelite/pair?code=ABCD-EFGH", "ABCD-EFGH"));
		assertFalse(RareDropWebhookClient.isAllowedPairingVerificationUrl(
			"https://exodus-prime-bingo.vercel.app.evil.test/runelite/pair?code=ABCD-EFGH", "ABCD-EFGH"));
		assertFalse(RareDropWebhookClient.isAllowedPairingVerificationUrl(
			"https://exodus-prime-bingo.vercel.app/not-pairing?code=ABCD-EFGH", "ABCD-EFGH"));
		assertFalse(RareDropWebhookClient.isAllowedPairingVerificationUrl(
			"https://exodus-prime-bingo.vercel.app/runelite/pair?code=WRONG", "ABCD-EFGH"));
		assertFalse(RareDropWebhookClient.isAllowedPairingVerificationUrl(
			"https://exodus-prime-bingo.vercel.app/runelite/pair?code=ABCD-EFGH&next=https://evil.test", "ABCD-EFGH"));
		assertFalse(RareDropWebhookClient.isAllowedPairingVerificationUrl(
			"https://exodus-prime-bingo.vercel.app/runelite/pair?code=ABCD-EFGH&code=WRONG", "ABCD-EFGH"));
	}
}
